const CHAPTERS: VizChapter[] = [{"id":"fs-ch01","subj":"fullstack","title":"Web 工作原理：HTTP 协议与浏览器-服务器交互","summary":"一次网页请求的完整链路（URL 解析→DNS→TCP/TLS→HTTP→服务端→渲染）；HTTP 报文结构（请求行/状态行、头部、空行、主体）与方法的语义契约（安全性/幂等性）；状态码五类语义与高频码辨析（301/302/307、401/4…","concepts":[{"id":"fs-ch01/01-http-message-and-methods","file":"01-http-message-and-methods.md","title":"01 · HTTP 报文与请求方法：文本协议的设计与语义契约","kind":"timeline","secs":[{"h":"一、理论根基：HTTP 是「无状态的文本协议」","s":"HTTP 的两个根本属性决定了它的一切设计：","c":null},{"h":"二、实现机制：报文的确切结构","s":"","c":{"lang":"text","code":"GET /api/users?page=2 HTTP/1.1          <- 请求行：方法 + 目标 + 版本\nHost: api.example.com                    <- 头部（Header），一行一个\nAccept: application/json\nAuthorization: Bearer eyJhbGciOi...\nX-Request-Id: 7f3a-...\n                                         <- 空行（CRLF CRLF）：头部结束\n{\"name\":\"cppcat\"}                        <- 消息体（Body，GET 通常没有）"}},{"h":"三、工程实践","s":"","c":null},{"h":"四、边界与陷阱","s":"","c":null}]},{"id":"fs-ch01/02-status-codes-and-headers","file":"02-status-codes-and-headers.md","title":"02 · 状态码与常用头部：把「结果」与「元信息」编码进协议","kind":"flow","secs":[{"h":"一、理论根基：状态码是「机器可判断的结果类别」","s":"状态码只有三位、首位定类：1xx 信息、2xx 成功、3xx 重定向、4xx 客户端错、5xx 服务端错。","c":null},{"h":"二、实现机制：高频状态码的精确语义","s":"","c":null},{"h":"三、工程实践：头部才是 HTTP 的表达力所在","s":"","c":null},{"h":"四、边界与陷阱","s":"","c":null}]},{"id":"fs-ch01/03-caching-cookie-and-state","file":"03-caching-cookie-and-state.md","title":"03 · 缓存、Cookie 与状态：在无状态协议上模拟「记忆」","kind":"flow","secs":[{"h":"一、理论根基：HTTP 无状态，一切「记忆」都是外置的","s":"HTTP 本身不记得你是谁。所有「记得」的假象，都来自三种外置机制：","c":null},{"h":"二、实现机制","s":"","c":{"lang":"text","code":"Cache-Control: max-age=3600          # 1 小时内直接用本地副本，不发请求\nCache-Control: no-store              # 完全不缓存（含敏感数据）\nCache-Control: no-cache              # 可缓存，但每次必须向服务端校验\nCache-Control: private / public      # 只有浏览器 / 允许 CDN 等共享缓存\nExpires: Wed, 21 Oct 2026 07:28:00 GMT   # HTTP/1.0 旧式绝对时间（已被 Cache-Control 取代）"}},{"h":"三、工程实践","s":"","c":null},{"h":"四、边界与陷阱","s":"","c":null}]},{"id":"fs-ch01/04-browser-server-cors","file":"04-browser-server-cors.md","title":"04 · 一次请求的完整链路：DNS、TCP、TLS、渲染与 CORS","kind":"timeline","secs":[{"h":"一、理论根基：为什么必须知道「整条链路」","s":"「输入 URL 到页面展示」之所以是经典面试题，是因为它强制你把网络、操作系统、浏览器、后端串成一条线。任何一段不清楚，都会在排查问题（慢？错？跨域？）时抓瞎。","c":null},{"h":"二、实现机制","s":"浏览器出于安全（防止 A 站点偷读 B 站点的数据）实施同源策略：跨源请求可以发出，但响应被浏览器拦截（除非服务端明确允许）。","c":{"lang":"text","code":"OPTIONS /api/data HTTP/1.1\nOrigin: https://app.example.com\nAccess-Control-Request-Method: PUT\nAccess-Control-Request-Headers: authorization, content-type"}},{"h":"三、工程实践","s":"","c":null},{"h":"四、边界与陷阱","s":"","c":null}]},{"id":"fs-ch01/05-http-in-practice","file":"05-http-in-practice.md","title":"HTTP 实战：报文、缓存与连接复用","kind":"flow","secs":[{"h":"一、一次请求的完整报文","s":"看两处：状态行后面的版本与状态码决定后续行为（1.1 支持 keep-alive，304 表示用缓存），","c":{"lang":"text","code":"GET /api/v1/exercises?subject=cpp HTTP/1.1\nHost: 127.0.0.1:8000\nUser-Agent: curl/8.5.0\nAccept: application/json\nConnection: keep-alive\n\n（空行后是请求体）"}},{"h":"二、缓存：让第二次请求变便宜","s":"关键点：带用户隐私的响应必须 private/no-store，否则 CDN 会把 A 用户的响应发给 B 用户。","c":{"lang":"js","code":"// 服务端：给出可缓存的响应，带 ETag；客户端带 If-None-Match，命中就回 304\nconst crypto = require('node:crypto');\n\nconst PAYLOAD = JSON.stringify({ items: [{ id: 'cpp-ch01-01', title: '指针与数组' }] });\nconst etag = '\"' + crypto.createHash('sha1').update(PAYLOAD).digest('hex').slice(0, 8) + '\"';\n\nfunction handle(req, res) {\n  if (req.headers['if-none-match'] === etag) {\n    res.writeHead(304, { ETag: etag });\n…"}},{"h":"三、幂等重试：网络抖动不该等于重复下单","s":"服务端要记住 Idempotency-Key（Redis 设 TTL），否则重试会真的重复创建。","c":{"lang":"js","code":"// 客户端：超时/5xx 时带同一个 Idempotency-Key 重试，服务端据此去重\nconst crypto = require('node:crypto');\n\nasync function postWithRetry(url, body, max = 3) {\n  const key = crypto.randomUUID();                 // 一次业务操作一个 key\n  for (let attempt = 1; attempt <= max; attempt += 1) {\n    try {\n      const res = await fetch(url, {\n        method: 'POST',\n…"}},{"h":"四、CORS：浏览器发的跨域请求长什么样","s":"\"绕过鉴权\"的漏洞——真正的防线在 token 校验与权限判定上。","c":{"lang":"text","code":"# 浏览器发起跨域 POST：\nPOST /api/v1/auth/login\nOrigin: https://app.example.com\nContent-Type: application/json\n\n# 服务端必须回：\nAccess-Control-Allow-Origin: https://app.example.com\nAccess-Control-Allow-Credentials: true\nAccess-Control-Allow-Headers: content-type\n…"}},{"h":"🧑‍💻 程序员视角","s":"带 If-None-Match 的第二次请求返回 304，响应体为空但仍消耗一次往返——静态资源用 Cache-Control: max-age + 内容哈希文件名，比协商缓存更省。POST 重试不等于「安全」：网关超时重试会造成重复下…","c":null},{"h":"🎓 博士生视角","s":"HTTP 的语义核心是「方法 + 状态码 + 头字段」三者共同表达意图：GET 安全幂等、PUT 幂等、POST 非幂等、DELETE 幂等。缓存分「强缓存」（Cache-Control/Expires）与「协商缓存」（ETag/Las…","c":null},{"h":"📚 考研者视角","s":"全栈面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"HTTP 方法的安全性与幂等性","stem":"关于 HTTP 方法的安全性（safe）与幂等性（idempotent），下列说法正确的是？ A. GET 是安全的且幂等的，因此网络超时可以放心重试 B. POST 是幂等的，重复提交不会产生副作用 C. PUT 是安全的，因为它只修改资源不创建资源 D. DELETE 不安全但也不幂等，重试会报错","opts":[{"k":"A","t":"GET 是安全的且幂等的，因此网络超时可以放心重试"},{"k":"B","t":"POST 是幂等的，重复提交不会产生副作用"},{"k":"C","t":"PUT 是安全的，因为它只修改资源不创建资源"},{"k":"D","t":"DELETE 不安全但也不幂等，重试会报错"}],"ans":"A","why":"GET 安全（不改服务端状态）且幂等（执行多次效果相同），因此可被预取、缓存，网络层也可自动重试。 B 错：POST 既不安全也不幂等，重复提交会重复创建，必须靠幂等键去重。 C 错：PUT 不安全（会改变状态），但幂等（同一份内容重复 PUT 结果相同）。 D 错：DELETE 不安全，但幂等——删同一个资源，删一次和删多次的最终状态相同。"},{"kind":"choice","q":"301 / 302 / 307 的差别","stem":"某站把 /old 临时迁移到 /new（几周后会迁回），但有工程师写成了 301。另一个接口在 POST 成功后返回 302 跳到结果页，导致部分客户端把 POST 变成了 GET。下列判断正确的是？ A. 写成 301 没问题，301 和 302 只差一个数字 B. 临时迁移应使用 302 或 307；301 会被浏览器长期缓存，难以回滚 C. 302 保证方法不变，问题出在客户端实现有 bug…","opts":[{"k":"A","t":"写成 301 没问题，301 和 302 只差一个数字"},{"k":"B","t":"临时迁移应使用 302 或 307；301 会被浏览器长期缓存，难以回滚"},{"k":"C","t":"302 保证方法不变，问题出在客户端实现有 bug"},{"k":"D","t":"POST 后应返回 301 以形成 POST-Redirect-GET 模式"}],"ans":"B","why":"A 错、B 对：301 是永久重定向，浏览器/CDN 会长期缓存，临时迁移用 301 一旦要迁回极难生效。 C 错：302 在历史实现中允许把 POST 改写为 GET，这不是客户端 bug 而是规范遗留；要保证方法不变必须用 307/308。 D 错：POST-Redirect-GET 模式应返回 303 See Other（明确要求用 GET 取新地址），不是 301。"},{"kind":"choice","q":"no-cache 与 no-store 的区别","stem":"服务端在一个含用户隐私数据的接口上写了 Cache-Control: no-cache，认为这样就「不会缓存、数据不会泄露」。这个判断的问题是？ A. 没问题，no-cache 就是完全不缓存 B. no-cache 表示「可缓存但每次必须校验」，仍可能被存下来；禁止存储应用 no-store C. no-cache 等价于 max-age=0，两者完全一致，写法没错 D. 隐私数据只需把 max…","opts":[{"k":"A","t":"没问题，no-cache 就是完全不缓存"},{"k":"B","t":"no-cache 表示「可缓存但每次必须校验」，仍可能被存下来；禁止存储应用 no-store"},{"k":"C","t":"no-cache 等价于 max-age=0，两者完全一致，写法没错"},{"k":"D","t":"隐私数据只需把 max-age 设为 0 即可"}],"ans":"B","why":"A 错、B 对：no-cache 的语义是「可以缓存，但每次使用前必须向服务端校验」，副本仍会被写入缓存；真正「任何情况下都不存储」是 no-store。 C 错：no-cache 与 max-age=0 语义相近但不等价（前者更强制、不依赖启发式新鲜度）。 D 错：隐私数据不仅要禁存储，还应配合 private（避免共享缓存/代理缓存造成越权），更稳妥的是 no-store。"},{"kind":"fix_error","q":"把业务错误塞进 200 的反模式","stem":"下面是一个存在问题的接口响应设计，请指出问题并给出修正方案。 json HTTP/1.1 200 OK Content-Type: application/json { \"code\": 401, \"msg\": \"未登录\", \"data\": null } 该接口在未登录时返回 HTTP 200，把业务错误码放在响应体的 code 字段里。请说明这样做会造成什么后果，并给出符合协议语义的改法。","opts":[],"ans":"后果：网关、CDN、监控告警、自动重试中间件全部只看 HTTP 状态码，把错误塞进 200 会让它们认为「一切正常」—— 1. 监控的 4xx/5xx 指标恒为 0，告警完全失效； 2. CDN/代理可能把这份「200 响应」缓存下来，导致其他用户也拿到「未登录」； 3. 幂等重试逻辑无法判断是否该重试。 修正：状态码…","why":"考察「状态码是给机器/中间件判断的，响应体是给业务判断的」这一分层原则。"},{"kind":"output","q":"重试策略的判定输出","stem":"阅读下面代码，写出运行输出（console.log 的完整结果）： js const canRetry = (code, idempotent) => code === 408 || code === 429 || code >= 500 ? idempotent : false; const cases = [[500, true], [503, false], [400, true], [42…","opts":[],"ans":"text 500 幂等=true -> 可重试? true 503 幂等=false -> 可重试? false 400 幂等=true -> 可重试? false 429 幂等=true -> 可重试? true","why":"把「状态码分类」与「幂等性」两个知识点结合成一条可执行的判定逻辑。"},{"kind":"coding","q":"用 Node 原生 http 实现符合语义的创建接口","stem":"使用 Node.js 原生 http 模块实现一个最小的「创建用户」接口，要求： 1. POST /v1/users → 成功返回 201 Created，并在 Location 头部给出新资源地址 /v1/users/<id>； 2. 请求体不是合法 JSON → 返回 400 Bad Request； 3. 请求体缺少 name 字段 → 返回 422 Unprocessable Entity…","opts":[],"ans":"const http = require('http'); const send = (res, status, body, extra = {}) => { res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', ...ex…","why":"检验能否把状态码语义落到真实代码中，重点是 400 与 422 的分工、201 带 Location、405 带 Allow。"},{"kind":"coding","q":"LRU 缓存（缓存淘汰策略）","stem":"设计并实现一个 LRU（最近最少使用）缓存，支持 get(key) 与 put(key, value)，两者都要求 O(1) 平均时间复杂度；容量满时淘汰最久未使用的键。 提示：需要「哈希表 + 双向链表」的组合——哈希表负责 O(1) 定位节点，双向链表负责 O(1) 移动节点到表头 / 摘除表尾。 （本题只给元数据与链接，题面以原站为准。）","opts":[],"ans":"解法要点（不给完整题面）： 1. 用 Map（或手写哈希表）存 key -> 链表节点； 2. 用双向链表维护使用顺序：表头 = 最近使用、表尾 = 最久未用； 3. get 命中后把节点移到表头； 4. put 时若 key 已存在则更新并移到表头；否则新建节点插到表头，若超出容量则摘除表尾节点并同步删除哈希表条目…","why":"考察哈希表 + 双向链表的组合设计能力，同时呼应 HTTP 缓存的淘汰策略。"},{"kind":"coding","q":"日志速率限制器（限流与 429）","stem":"设计一个日志速率限制器：给定一条消息与其时间戳，若该消息在过去 10 秒内已经出现过，则丢弃并返回 false；否则记录并返回 true。 （本题只给元数据与链接，题面以原站为准。）","opts":[],"ans":"解法要点（不给完整题面）： 用一个哈希表记录「消息 -> 上次通过的时间戳」，每次到来时判断差值是否 < 10：是则拒绝，否则更新时间戳并放行。 与本章的关联：这正是服务端限流的最小模型。真实限流（令牌桶/漏桶/滑动窗口）触发时应返回 429 Too Many Requests 并带 Retry-After 告知客户端…","why":"考察时间窗口去重的实现，并关联 429 状态码与 Retry-After 的工程含义。"}],"works":[{"h":"用 GET 触发副作用","d":"GET 语义上是「安全 + 幂等」的，会被浏览器预取、爬虫遍历、CDN 预取、网络层自动重试。把「下单」「删除」「发送」放在 GET 上，随时可能被意外触发或重复触发。正确做法：写操作一律用 POST/PUT/PATCH/DELETE。"},{"h":"把错误塞进 200 OK","d":"业务失败也返回 200 + {code: 500, msg: ...}，会让网关、CDN、监控告警、自动重试全部失效（它们只看状态码）。正确做法：状态码表达协议级结果，错误详情放响应体。"},{"h":"no-cache 当成「不缓存」","d":"no-cache 是「可缓存但每次必须向服务端校验」，真正禁止缓存是 no-store。写反了会导致：以为禁了缓存，实际仍可能命中旧副本；或以为能加速，实际每次都发请求。"},{"h":"301 用于临时迁移","d":"301 是永久重定向，浏览器/CDN 会长期缓存，一旦配错极难回滚（用户长期被带到错误地址）。临时迁移应用 302/307。"},{"h":"302 后被浏览器把 POST 变 GET","d":"历史实现允许改写方法，导致 POST 后刷新重复提交或参数丢失。正确做法：POST 成功后返回 303（POST-Redirect-GET 模式）让客户端用 GET 取结果页。"},{"h":"Cookie 漏配 HttpOnly / Secure / SameSite","d":"三者分别防 XSS 窃取（JS 读不到）、明文窃听（只在 HTTPS 发送）、CSRF（限制跨站携带）。全缺 = 会话凭证几乎裸奔。"},{"h":"Access-Control-Allow-Origin: 同时带凭证","d":"浏览器会直接拒绝（规范禁止）。需要携带 Cookie 时必须回显具体 Origin 并设 Access-Control-Allow-Credentials: true。"},{"h":"以为 CORS 是前端能解决的问题","d":"CORS 是响应头机制，前端无法通过「加个请求头」绕过。开发期用代理（把跨域变同源），生产期在服务端/网关配置。"}],"asks":[{"q":"在浏览器地址栏输入 URL 到页面展示，中间发生了什么？请尽量完整。","a":"按层次拆开答（分层归因是这道题真正的考点）： 1. URL 解析：拆出协议/主机/端口/路径/查询/片段。 2. DNS 解析：浏览器 DNS 缓存 → 系统缓存/hosts → 本地 DNS 服务器（递归查询：根 → 顶级域 → 权威）→ 得到 IP。 3. 建立连接：TCP 三次握手（1 RTT）；HTTPS 再做 TLS 握手（TLS 1.3 约 1 RTT，会话恢复可 0-RTT）并校验证…","fu":["为什么 TCP 握手是三次而不是两次？","HTTP/2 的队头阻塞和 HTTP/1.1 的队头阻塞有什么区别？HTTP/3 怎么解决？"],"tag":"通用/字节"},{"q":"HTTP 方法里哪些是幂等的？为什么幂等性在工程上如此重要？","a":"幂等：GET、HEAD、OPTIONS、PUT、DELETE 幂等；POST 不幂等（PATCH 语义上不保证）。 安全（不改状态）：GET、HEAD、OPTIONS；PUT/POST/PATCH/DELETE 都不安全。 为什么重要： 1. 自动重试：网络层/客户端在超时后是否可安全重发，取决于幂等性；对非幂等操作盲目重试会重复产生副作用（重复下单、重复扣款）。 2. 预取与爬虫：浏览器预取、搜…","fu":["PATCH 为什么通常不被认为幂等？举例说明。","幂等键应该由客户端还是服务端生成？为什么？"],"tag":"通用/阿里"},{"q":"强缓存和协商缓存的区别？Cache-Control 常用指令有哪些？","a":"强缓存（不发请求）：Cache-Control: max-age=N / Expires。在新鲜期内浏览器直接用本地副本，连请求都不发（Network 面板显示 (from disk cache)）。 协商缓存（发请求校验）：ETag + If-None-Match，或 Last-Modified + If-Modified-Since。服务端判断未变更时回 304 Not Modified（无主…","fu":["ETag 一般怎么生成？强 ETag 和弱 ETag（W/）有什么区别？","Vary 头部解决什么问题？不写会怎样？"],"tag":"通用/腾讯"},{"q":"Cookie、Session、JWT(Token) 有什么区别？各自的安全属性怎么配？","a":"Cookie：浏览器存储的小段数据，每次同域请求自动携带。可设 HttpOnly（防 XSS 读取）、Secure（只走 HTTPS）、SameSite（防 CSRF）。 Session：会话状态存在服务端（内存/Redis），Cookie 里只放会话 ID。优点是可即时撤销；缺点是横向扩展需共享存储。 JWT / Token：状态以自包含令牌形式存于客户端，通常放 Authorization:…","fu":["JWT 怎么实现「登出」？黑名单方案有什么代价？","为什么要用 refresh token？access token 的有效期设多长合适？"],"tag":"通用/字节"}]},{"id":"fs-ch02","subj":"fullstack","title":"前端基础：HTML 语义化与 CSS 盒模型/布局","summary":"HTML 语义化结构与可访问性（header/nav/main/article/section/footer 等）；浏览器渲染管线（解析→样式计算→布局→绘制→合成）；CSS 盒模型（content/padding/border/margi…","concepts":[{"id":"fs-ch02/01-html-semantics","file":"01-html-semantics.md","title":"01 · HTML 语义化：从「机器可读」到「可访问」","kind":"flow","secs":[{"h":"一、理论根基：语义化不是「好看」，而是「机器可读」","s":"从计算机科学视角，语义（semantics） 指标记（markup）携带的含义，而非呈现。HTML 的设计目标是描述文档结构（类似 LaTeX 的 \\section/\\emph），呈现交给 CSS。语义化的本质是：","c":null},{"h":"二、实现机制：解析器与「无障碍树」","s":"博士视角要看浏览器到底构建了什么：","c":null},{"h":"三、工程实践：程序员怎么写","s":"","c":null},{"h":"四、边界与陷阱","s":"","c":null},{"h":"五、可运行示例（结构正确即可，浏览器渲染验证）","s":"","c":{"lang":"html","code":"<body>\n  <header><h1>站点标题</h1></header>\n  <nav aria-label=\"主导航\"><ul><li><a href=\"/\">首页</a></li></ul></nav>\n  <main>\n    <article>\n      <h2>文章标题</h2>\n      <p>正文段落，<time datetime=\"2026-09-23\">2026-09-23</time> 发布。</p>\n    </article>\n  </main>\n…"}}]},{"id":"fs-ch02/02-css-box-model","file":"02-css-box-model.md","title":"02 · CSS 盒模型与 BFC：布局的几何真相","kind":"stack","secs":[{"h":"一、理论根基：一切皆盒子","s":"CSS 的基石是盒模型（box model）：文档流中的每个元素都被渲染为一个矩形盒子，由内到外四层：","c":{"lang":"text","code":"margin(外边距) | border(边框) | padding(内边距) | content(内容)"}},{"h":"二、实现机制：content-box vs border-box","s":"浏览器在布局阶段（Layout/Reflow） 为每个盒子计算几何坐标。两种模式（见 ex03/ex04）：","c":null},{"h":"三、BFC：块级格式化上下文","s":"1. 包含浮动（contain floats）：BFC 会计算浮动子元素的高度，父容器不再\"高度塌陷\"。","c":null},{"h":"四、工程实践","s":"","c":null},{"h":"五、边界与陷阱","s":"","c":null},{"h":"六、可运行示例（Node 验证盒模型数学，见 ex10/ex11）","s":"","c":{"lang":"js","code":"// 见 examples/ex10-js-box-sizing-math.json（Node 实测）\n// border-box 总宽: 200 ; content-box 总宽: 236（width=200,padding=16,border=2）"}}]},{"id":"fs-ch02/03-rendering-pipeline","file":"03-rendering-pipeline.md","title":"03 · 浏览器渲染管线：从字节到像素","kind":"stack","secs":[{"h":"一、理论根基：关键渲染路径（Critical Rendering Path）","s":"\"为什么页面会闪/卡/慢\"的回答，必须落到渲染管线这一工程事实上。现代浏览器（Blink/WebKit/Gecko）把 HTML/CSS/JS 变成屏幕像素，主线是：","c":{"lang":"text","code":"字节 → 字符 → Token → DOM        (HTML 解析)\nCSS  → CSSOM                     (样式解析)\nDOM + CSSOM → Render Tree        (样式计算)\nRender Tree → Layout(Reflow)     (几何)\nLayout → Paint(Raster)           (绘制)\nPaint → Composite → 像素          (合成，常走 GPU)"}},{"h":"二、实现机制（按线程与阶段拆解）","s":"1. 解析（Parse）","c":null},{"h":"三、Reflow / Repaint / Composite-only 的区别（面试高频）","s":"","c":null},{"h":"四、工程实践：程序员怎么避免卡顿","s":"","c":null},{"h":"五、边界与陷阱：layout thrashing 实例","s":"","c":{"lang":"js","code":"// 错误：循环里交替读 offsetHeight（强制 reflow）与写 width → 每轮都重排\nfor (const el of boxes) {\n  const h = el.offsetHeight;   // 读：强制同步布局\n  el.style.width = h + 10 + 'px'; // 写：下一轮读前又 reflow\n}\n// 修复：先批量读，再批量写\nconst hs = boxes.map(el => el.offsetHeight);\nboxes.forEach((el, i) => { el.style.width = hs[i] + 10 + 'px'; });"}}]},{"id":"fs-ch02/04-layout-flex-grid","file":"04-layout-flex-grid.md","title":"04 · 现代布局：Flexbox 与 Grid","kind":"stack","secs":[{"h":"一、理论根基：一维 vs 二维","s":"二者不是替代关系，而是互补：大骨架用 Grid，组件内排列用 Flex。","c":null},{"h":"二、实现机制：Flexbox","s":"容器 display:flex 后，子项成为 flex item，布局由以下属性驱动：","c":null},{"h":"三、实现机制：Grid","s":"","c":null},{"h":"四、工程实践","s":"","c":null},{"h":"五、边界与陷阱","s":"","c":null},{"h":"六、可运行示例（浏览器渲染，见 examples/ex07-flexbox-center.j…","s":"","c":null}]},{"id":"fs-ch02/05-html-css-practical-recipes","file":"05-html-css-practical-recipes.md","title":"HTML 与 CSS 实战手记：凯喵的十二次布局翻车现场","kind":"flow","secs":[{"h":"开场：一个只有四行的 CSS，为什么改了三天","s":"凯喵第一次接手时，需求是「卡片三列等宽，中间留 16px 间距，窄屏变两列，再窄变一列」。看起来四行 CSS 就能搞定，实际却先后遇到：卡片被内容撑破、间距在最后一列多出来、窄屏时横向出现滚动条、以及某个卡片高度比兄弟矮一截导致底部参差…","c":{"lang":"html","code":"<body>\n  <header>\n    <nav aria-label=\"主导航\">\n      <a href=\"/\">首页</a>\n      <a href=\"/courses\">课程</a>\n    </nav>\n  </header>\n\n  <main>\n…"}},{"h":"收尾：布局问题的答案，都在「盒子怎么算」里","s":"凯喵最后总结一句：前端布局看起来规则繁多，但绝大多数困惑都能归到三个问题上——这个盒子的宽度怎么算（盒模型）、这个元素在谁的上下文里（BFC、格式化上下文）、这个容器的默认行为是什么（Flex/Grid 的初始值）。","c":null}]}],"exams":[{"kind":"choice","q":"CSS 中 box-sizing 的默认值是什么？","stem":"选择 box-sizing 的初始值（未显式设置时）。","opts":[{"k":"A","t":"border-box"},{"k":"B","t":"content-box"},{"k":"C","t":"padding-box"},{"k":"D","t":"margin-box"}],"ans":"B","why":"CSS 规范中 box-sizing 初始值为 content-box：width/height 仅含内容区，padding 与 border 额外撑大元素。"},{"kind":"choice","q":"以下哪些做法会触发 BFC（块级格式化上下文）？","stem":"多选思路（本题单选最干净的触发方式）：哪个声明专门用于建立 BFC 且无裁切/定位副作用？","opts":[{"k":"A","t":"display: flow-root"},{"k":"B","t":"color: red"},{"k":"C","t":"font-size: 16px"},{"k":"D","t":"text-align: center"}],"ans":"A","why":"display:flow-root 是语义上最纯粹的 BFC 触发方式，不会导致 overflow:hidden 的裁切或 absolute 的脱离文档流等副作用。"},{"kind":"output","q":"盒模型尺寸计算（border-box）","stem":"给定 width:200px; padding:16px; border:2px; box-sizing:border-box，求元素总占位宽与内容区宽（单位 px，margin 不计）。","opts":[],"ans":"总占位宽=200，内容区宽=164","why":"border-box 下 width 含 content+padding+border，故总宽=200；内容区=200-162-22=164（与 examples/ex10 Node 实测一致）。"},{"kind":"fix_error","q":"修复浮动导致的父容器高度塌陷","stem":"以下父容器因子元素 float:left 而高度为 0、背景包不住。请修复（保留浮动效果）： css .box { background: #eee; } .box > .col { float: left; width: 100px; }","opts":[],"ans":".box { background: #eee; display: flow-root; } / 或 overflow: hidden; / .box > .col { float: left; width: 100px; }","why":"给父容器建立 BFC（display:flow-root 最干净）即可包含浮动子元素高度，不再塌陷。"},{"kind":"explain","q":"简述浏览器关键渲染路径（CRP）的五个阶段","stem":"解释：从 HTML/CSS/JS 到屏幕像素，浏览器主线程依次经历哪几个阶段？哪些是合成器线程做的？","opts":[],"ans":"DOM + CSSOM → Render Tree（样式计算）→ Layout(Reflow) → Paint(Raster) → Composite(GPU)。JS/Style/Layout/Paint 在主线程，Composite 在合成器线程，故 transform/opacity 动画即使主线程卡顿也能流畅。","why":"核心是流水线模型：任一阶段重做都会连带后续重做；优化即减少 Reflow、把动画放到合成层、批量读写避免 layout thrashing。"},{"kind":"design","q":"LeetCode 344 · 反转字符串（算法素养补充）","stem":"编写一个把字符数组原地反转的函数。本题作为前端算法素养补充，题面与约束以官方为准，详见 external_url，此处不复述题面。","opts":[],"ans":"function reverseString(s) { let i = 0, j = s.length - 1; while (i < j) { [s[i], s[j]] = [s[j], s[i]]; i++; j--; } return s; }","why":"双指针原地交换，空间 O(1)。注意 LeetCode 传的是字符数组，需原地修改。"}],"works":[{"h":"忘记 viewport 标签","d":"移动端页面按默认约 980px 视口缩放，字体极小需双指放大。务必在 <head> 加 <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">。"},{"h":"盒模型尺寸算错（content-box 陷阱）","d":"默认 content-box 下 width 不含 padding/border：设 width:200px 又加 padding:16px; border:2px 实际占 236px（见 ex10 Node 实测），导致换行/溢出。 全局 { box-sizing: border-box; }，让 width 即总宽。"},{"h":"用一堆 <div> 拼结构忽略语义","d":"损害 SEO 与读屏体验，<div class=\"nav\"> 对辅助技术只是无名方块。 用 header/nav/main/article/section/aside/footer 等地标标签。"},{"h":"外边距塌陷（margin collapse）","d":"相邻兄弟或「父 margin-top 与首子 margin-top」会取较大值合并为一个，不是简单相加。 用 padding/border/overflow:hidden/display:flow-root 阻断（计算见 ex11）。"},{"h":"浮动导致父容器高度塌陷","d":"子元素 float 后脱离普通流，父容器高度为 0，背景/边框不包住。 父容器建立 BFC：display:flow-root 或 overflow:hidden（注意裁切副作用）。"},{"h":"选择器优先级误判","d":"写了 .btn{color:red} 却被 button{color:blue} 覆盖，因标签选择器特异性低。 用类选择器、提高特异性，别急着 !important；优先级 (a=ID,b=类/属性/伪类,c=标签) 逐位比较。"},{"h":"强制同步布局（layout thrashing）","d":"循环里交替读 offsetHeight 等布局属性与写样式，每轮都触发重排，页面巨卡。 批量读、批量写，或用 requestAnimationFrame 对齐帧（见 concept/03）。"},{"h":"滥用 will-change 制造过多合成层","d":"will-change:transform 会给元素开独立 GPU 图层，乱用耗尽显存、反而更卡。 仅对真正持续动画的元素使用，动画结束移除。"}],"asks":[{"q":"从输入 URL 到页面渲染出来，浏览器经历了哪些关键阶段？请讲清楚关键渲染路径（CRP）。","a":"大致分：① 网络层解析域名、建立连接、下载 HTML（含 preload scanner 提前拉取子资源）；② 解析 HTML 生成 DOM 树，解析 CSS 生成 CSSOM；③ 样式计算把 CSSOM 与 DOM 匹配得到每个元素的 Computed Style，形成 Render Tree；④ 布局（Layout/Reflow）计算每个盒子的几何坐标；⑤ 绘制（Paint）生成绘制指令并光栅…","fu":["什么是强制同步布局？如何避免？","重排、重绘、合成的区别是什么？哪些属性只触发合成？"],"tag":"通用/字节"},{"q":"什么是 BFC（块级格式化上下文）？如何触发？能解决哪些实际问题？","a":"BFC 是一块独立的布局区域，内部块级盒正常流排布且与外部互不干扰。触发条件：float 非 none、position:absolute/fixed、display:flex/grid/inline-block/flow-root、overflow 非 visible、contain:layout/paint、根元素等。它能：① 包含浮动，解决父容器高度塌陷；② 阻止相邻/父子 margin 折…","fu":["为什么 display:flow-root 比 overflow:hidden 更适合清除浮动？","IFC（行内格式化上下文）和 BFC 有何区别？"],"tag":"通用/美团"},{"q":"content-box 和 border-box 的区别？为什么工程上推荐全局 border-box？","a":"默认 content-box 下 width/height 只含内容区，padding 与 border 会额外撑大元素实际占位（如 width:200 + padding162 + border22 = 236px）；border-box 下 width 包含 content+padding+border，元素总宽固定为设定值，排版可预测。因此常见重置 { box-sizing: border-…","fu":["margin 算进 width 吗？","inline 元素与 block 元素的盒模型差异？"],"tag":"通用/字节"}]},{"id":"fs-ch03","subj":"fullstack","title":"JavaScript 核心：类型、原型链、DOM 与事件、异步(Promise/async)","summary":"值与类型系统（原始类型/对象、typeof 与类型转换/隐式 coercion）；原型链与 class 语法糖、this 四种绑定；作用域与闭包、变量提升与 TDZ；V8 对象表示与隐藏类（shape/map）；事件循环（调用栈/宏任务/微…","concepts":[{"id":"fs-ch03/01-types-coercion","file":"01-types-coercion.md","title":"01 · 类型系统与相等性：原始类型、typeof 陷阱、== 与 Object.is","kind":"compare","secs":[{"h":"一、值与类型：原始类型 vs 引用类型","s":"JavaScript 的值分两大类：","c":null},{"h":"二、相等性三兄弟：== 、=== 、Object.is","s":"记住几个经典结果：1 == '1' → true；[] == false → true；NaN == NaN → false；null == undefined → true。+0 === -0 → true 但 Object.is(+…","c":null},{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"js","code":"const samples = [\n  ['number', 1],\n  ['string', 'a'],\n  ['boolean', true],\n  ['null', null],\n  ['undefined', undefined],\n  ['symbol', Symbol('s')],\n  ['bigint', 10n],\n  ['object', {}],\n…"}}]},{"id":"fs-ch03/02-scope-closure-this","file":"02-scope-closure-this.md","title":"02 · 作用域、闭包与 this 绑定","kind":"flow","secs":[{"h":"一、作用域、提升与 TDZ","s":"JavaScript 采用词法作用域（lexical scope）：函数能访问哪些变量由「定义时的位置」决定，而非调用位置。","c":null},{"h":"二、this 的五条绑定规则","s":"this 不是一个固定值，而是在每次函数调用时根据调用点决定的：","c":null},{"h":"可运行代码：TDZ 与 this 的五条规则","s":"提升、死区、绑定优先级三件事都能在同一个脚本里看到差别：","c":{"lang":"js","code":"// ① var 提升：声明提了、赋值没提\nconsole.log(typeof b);          // \"undefined\"（不报错）\nvar b = 2;\n\n// ② let 的 TDZ：声明前访问直接抛错，不是 undefined\ntry {\n  console.log(a);\n} catch (e) {\n  console.log(e.constructor.name, \"-\", e.message);   // ReferenceError - Cannot access 'a' before initialization\n…"}}]},{"id":"fs-ch03/03-prototype-oop","file":"03-prototype-oop.md","title":"03 · 原型链、class 语法糖与继承","kind":"flow","secs":[{"h":"一、原型链：JavaScript 的「类」真相","s":"JavaScript 的对象没有真正的类（ES6 class 只是语法糖）。每个对象都有一个内部槽 [[Prototype]]（可通过 Object.getPrototypeOf(obj) 读取，旧写法 obj.__proto__），指…","c":null},{"h":"二、继承：Object.create 与 class","s":"V8 视角：对象有一个 隐藏类（shape / map），描述属性布局。同名属性按相同顺序添加的对象共享 shape，属性访问被编译成偏移量读取（接近 C++ 成员访问速度）；动态增删属性或改顺序会「去优化」生成新 shape，拖慢访问…","c":null}]},{"id":"fs-ch03/04-async-eventloop","file":"04-async-eventloop.md","title":"04 · 事件循环、Promise 与 async/await","kind":"timeline","secs":[{"h":"一、事件循环：单线程如何不卡死","s":"JavaScript 是单线程，靠事件循环（Event Loop）调度异步任务。运行时有一条调用栈（call stack）和若干队列：","c":null},{"h":"二、Promise / async / await 与组合子","s":"","c":null}]},{"id":"fs-ch03/05-js-core-practical-recipes","file":"05-js-core-practical-recipes.md","title":"JavaScript 语言核心实战手记：凯喵的十二次「打印出来和我想的不一样」","kind":"flow","secs":[{"h":"开场：为什么 JS 的「坑」总在输出上","s":"其他语言的坑往往表现为编译错误，JS 的坑往往表现为「跑通了但结果不对」。原因是 JS 大量依赖运行期行为：类型在运行时才确定、this 在调用时才绑定、原型链在访问时才查找、回调在微任务队列里才执行。","c":{"lang":"javascript","code":"typeof null          // \"object\"\ntypeof undefined     // \"undefined\"\ntypeof function(){}  // \"function\"\ntypeof []            // \"object\"\ntypeof NaN           // \"number\""}},{"h":"收尾：JS 的「坑」都是执行模型的推论","s":"凯喵最后总结：这十二个现场看似零散，其实都在回答四个问题——这个值是什么类型（隐式转换）、这个变量存在哪（作用域与提升）、这个 this 指向谁（绑定规则）、这段代码什么时候执行（事件循环）。","c":null}]}],"exams":[{"kind":"choice","q":"typeof 对 null 的结果是什么？","stem":"在 JavaScript 中，typeof null 的返回值是什么？","opts":[{"k":"A","t":"null"},{"k":"B","t":"object"},{"k":"C","t":"undefined"},{"k":"D","t":"number"}],"ans":"B","why":"typeof null 返回 'object' 是历史包袱（初版 32 位 tag 中 null 的低位标识与对象相同），因此不能用于区分 null 与对象。"},{"kind":"choice","q":"下面哪条比较结果为 true？","stem":"只凭隐式转换规则判断，下列哪个表达式求值为 true？","opts":[{"k":"A","t":"1 === '1'"},{"k":"B","t":"null == undefined"},{"k":"C","t":"NaN === NaN"},{"k":"D","t":"[] === false"}],"ans":"B","why":"null == undefined 为 true 是规范特例；其余：A 严格相等类型不同为 false；C NaN 不等于自身；D 不同类型无转换直接 false。"},{"kind":"output","q":"预测事件循环的输出顺序","stem":"下面代码依次打印什么（按行写出输出）？ js console.log('1 sync'); setTimeout(() => console.log('5 macro'), 0); queueMicrotask(() => console.log('3 micro')); Promise.resolve().then(() => console.log('4 then')); (async ()…","opts":[],"ans":"1 sync 2 sync-async 7 sync-end 3 micro 4 then 6 after-await 5 macro","why":"同步代码先跑完（1,2,7）；然后微任务队列被一次性清空（3,4,6，其中 await 续体也是微任务）；最后才执行宏任务 setTimeout（5）。"},{"kind":"fix_error","q":"修复循环里 var 闭包打印全为终值的 bug","stem":"下面代码点击三次都打印 3，请修复（保留用闭包捕获索引的意图）： js var fns = []; for (var i = 0; i < 3; i++) { fns.push(() => console.log(i)); } fns.forEach(f => f());","opts":[],"ans":"var fns = []; for (let i = 0; i < 3; i++) { fns.push(() => console.log(i)); } fns.forEach(f => f()); // 或保留 var：for (var i = 0; i < 3; i++) { (function (j) { fn…","why":"改用 let 让每次迭代拥有独立的块级绑定；或用手动 IIFE 传参固化值，使每个闭包捕获各自的索引。"},{"kind":"choice","q":"箭头函数里的 this 来自哪里？","stem":"const obj = { name: 'o', fn() { const g = () => this.name; return g(); } }; obj.fn() 的返回值是？","opts":[{"k":"A","t":"undefined（箭头没有 this）"},{"k":"B","t":"String 'o'（捕获了 fn 的 this 即 obj）"},{"k":"C","t":"全局对象的 name"},{"k":"D","t":"运行时报错"}],"ans":"B","why":"箭头函数没有自己的 this，取定义时外层词法作用域（fn 调用时的 this=obj）的 this，因此返回 'o'。"},{"kind":"coding","q":"手写 debounce（防抖）","stem":"实现一个 debounce(fn, delay)：连续触发时只在最后一次触发后等待 delay 毫秒才真正执行 fn，期间再次触发会重置计时。保留 this 与参数。","opts":[],"ans":"function debounce(fn, delay) { let timer = null; return function (...args) { const ctx = this; clearTimeout(timer); timer = setTimeout(() => fn.apply(ctx, args)…","why":"靠闭包持有 timer；每次调用先 clearTimeout 再重设，因此只有「安静 delay 毫秒」后才会真正执行，并保留调用上下文与参数。"},{"kind":"coding","q":"LeetCode 20 · 有效的括号（算法素养补充）","stem":"给定一个只包含 '()[]{}' 的字符串，判断括号是否成对匹配且顺序正确。题面与约束以官方为准，详见 external_url，此处不复述题面。","opts":[],"ans":"function isValid(s) { const st = []; const pair = { ')': '(', ']': '[', '}': '{' }; for (const ch of s) { if (ch in pair) { if (st.pop() !== pair[ch]) return fa…","why":"栈的经典应用：左括号入栈，右括号与栈顶匹配；遍历完栈空即合法。时间 O(n)、空间 O(n)。"},{"kind":"coding","q":"LeetCode 2621 · Sleep（async/await 实践）","stem":"实现一个 sleep(milliseconds) 异步函数，返回一个在指定毫秒后 resolve 的 Promise。题面与约束详见 external_url，不抄题面。","opts":[],"ans":"async function sleep(ms) { return new Promise(function (resolve) { setTimeout(resolve, ms); }); }","why":"用 Promise 包裹 setTimeout；async 函数自动把返回值包成 Promise，调用处可 await sleep(200)。"}],"works":[{"h":"typeof null === 'object'","d":"typeof null 返回 'object'，无法用它区分 null 与对象。 判对象用 x !== null && typeof x === 'object' && !Array.isArray(x)。"},{"h":"用 == 做宽松比较引发隐式转换","d":"0 == ''、'0' == false、[] == false、null == undefined 都为真，导致逻辑错误。 默认用 ===，需要容错用 Object.is 或 ??/?.。"},{"h":"把 NaN 当普通值比较","d":"NaN === NaN 为 false，NaN == NaN 也为 false，无法用相等判断。 用 Number.isNaN(x)（不会把非数字误判成 NaN）。"},{"h":"var 循环闭包打印「最后一项」","d":"for (var i...) { cb(() => i) } 所有回调共享同一个 i，最终都拿到终值。 用 let（每块新绑定）或在循环内 bind(i)。"},{"h":"TDZ 中访问 let/const","d":"在声明语句之前访问会抛 ReferenceError，而非像 var 那样得到 undefined。 把 let/const 声明放在使用前，避免块顶部「先引用」。"},{"h":"this 在回调中丢失","d":"const f = obj.method; f() 或把方法当回调传入，隐式绑定丢失、this 变 undefined/全局。 用箭头函数捕获外层 this，或 bind 固化。"},{"h":"箭头函数当对象方法","d":"箭头没有自己的 this，obj = { fn: () => this.x } 里的 this 指向外层词法作用域而非 obj。 需要 this 归对象时用普通方法。"},{"h":"混淆 prototype 与 __proto__（原型）","d":"F.prototype 是构造函数上给实例用的原型；实例的内部原型是 [[Prototype]]（Object.getPrototypeOf）。改 __proto__ 性能差。 用 class / Object.create / Object.getPrototypeOf。"}],"asks":[{"q":"讲讲 JavaScript 的事件循环，宏任务和微任务的执行顺序是怎样的？给一段代码你能写出输出吗？","a":"JS 单线程，靠事件循环调度。每轮：先执行完当前调用栈的同步代码，然后一次性清空整个微任务队列（Promise.then/queueMicrotask/await 续体，含清空中新加入的），再取一个宏任务（setTimeout/I/O/渲染）执行，循环往复。结论：同步 > 所有微任务 > 一个宏任务。所以 Promise.then 永远早于 setTimeout(fn,0)；连续 queueMic…","fu":["await 后面那段代码是宏任务还是微任务？","Node 的 process.nextTick 和微任务谁先？"],"tag":"通用/字节"},{"q":"原型链是什么？属性查找和 instanceof 是怎么工作的？","a":"每个对象有内部原型 [[Prototype]]（用 Object.getPrototypeOf 读取），形成一条链。obj.x 先查自身自有属性，没有就沿原型链向上，直到 null。这就是「基于原型」的继承。instanceof 沿左侧对象的原型链查找能否到达右侧构造函数的 prototype。class 只是语法糖，底层仍是把 Sub.prototype 的 [[Prototype]] 指向 B…","fu":["prototype 和 __proto__ 的区别？","手写 new / 手写 instanceof？"],"tag":"通用/美团"},{"q":"this 的绑定规则有哪些？箭头函数为什么特殊？","a":"五条：默认（独立调用，非严格是全局、严格是 undefined）、隐式（obj.fn()，this=obj）、显式（call/apply/bind 指定）、new（this=新对象）、箭头（没有自己的 this，取外层词法 this，且优先级最高不可被改写）。优先级（非箭头）：new > 显式 > 隐式 > 默认。箭头函数常用于回调以捕获外层 this，避免 that/self hack；但对象方…","fu":["方法被当作回调传入时 this 为什么丢了？怎么修？","call/apply/bind 的区别？"],"tag":"通用/字节"},{"q":"闭包是什么？有什么用，有什么坑？","a":"闭包是函数与其定义时词法环境的绑定，内层函数即使在外层返回后仍能访问外层变量。用途：私有状态、工厂函数、回调携带上下文。代价：外层变量无法被 GC，持有大对象会内存泄漏；SPA 卸载组件要解绑事件、清空引用。经典题：循环里 var 闭包共享同一变量，用 let 或 bind 固化。","fu":["手写 once / 防抖 / 节流？","闭包为什么会导致内存泄漏？"],"tag":"通用/阿里"}]},{"id":"fs-ch09","subj":"fullstack","title":"TypeScript：结构化类型、泛型与类型收窄","summary":"TypeScript 的类型不是注释，是一套在编译期跑的约束求解。本章讲清：结构类型（structural typing）与名义类型的差别、unknown 与 any 的边界、联合类型的收窄（narrowing）与穷尽性检查、泛型与条件类型…","concepts":[{"id":"fs-ch09/01-structural-typing","file":"01-structural-typing.md","title":"结构类型：形状对了就是对的","kind":"flow","secs":[{"h":"为什么这样设计","s":"JS 是鸭子类型（duck typing）语言：运行时只看对象有没有那个方法/属性，从不看它是谁 new 出来的。","c":{"lang":"ts","code":"type UserId = string & { readonly __brand: \"UserId\" };\ntype OrderId = string & { readonly __brand: \"OrderId\" };\n// 现在 string 不能直接当 UserId，必须显式断言，误传在编译期就被拦下"}},{"h":"一条实用判据","s":"接口描述「这个对象必须具备什么」，而不是「这个对象只能是什么」。","c":null},{"h":"多余属性检查：为什么有时多也不行","s":"上面说「多了不报错」，但有个例外。直接写字面量时，编译器会额外做一次","c":{"lang":"ts","code":"interface Point { x: number; y: number }\n\nconst a: Point = { x: 1, y: 2, z: 3 };\n// ✗ Object literal may only specify known properties, and 'z' does not exist in type 'Point'\n\nconst tmp = { x: 1, y: 2, z: 3 };\nconst b: Point = tmp;   // ✓ 先过一层变量就不报了"}},{"h":"结构类型的三个边界反例","s":"以下三类场景，结构类型会给出「能用但不对」的结果，需要人工加约束：","c":{"lang":"ts","code":"type Brand<T, B extends string> = T & { readonly __brand: B };\ntype UserId = Brand<string, \"UserId\">;\n\nconst asUserId = (raw: string) => raw as UserId;   // 唯一入口，可在此做格式校验"}},{"h":"interface 与 type 怎么选","s":"初学者常在这两者之间纠结。判据只有一条：你要不要「后来往上面加东西」。","c":null}]},{"id":"fs-ch09/02-narrowing-and-exhaustive","file":"02-narrowing-and-exhaustive.md","title":"类型收窄与穷尽性检查","kind":"flow","secs":[{"h":"收窄的几种来源","s":"自定义守卫是唯一「编译器无条件相信你」的一条。写错守卫比不写更危险：","c":{"lang":"ts","code":"// 危险：只要非空就返回 true，但 null 也会被 typeof 判成 \"object\"\nfunction isUser(x: unknown): x is User {\n  return typeof x === \"object\" && x !== null;\n}"}},{"h":"为什么 any 是逃生舱而不是工具","s":"any 会让类型检查整段失效，而且会传染：一个 any 传给一个函数，函数返回值也可能退化成 any。","c":{"lang":"ts","code":"declare const maybeUser: User | null;\n\n// A：let + 回调 —— 不报错，收窄保持\nfunction a() {\n  if (!maybeUser) return;\n  let u = maybeUser;\n  setTimeout(() => { u.name; }, 1);\n}\n\n…"}}]},{"id":"fs-ch09/03-generics-and-erasure","file":"03-generics-and-erasure.md","title":"泛型、条件类型与它们的运行时代价","kind":"flow","secs":[{"h":"擦除（erasure）意味着什么","s":"类型在运行时不存在，因此：","c":null},{"h":"泛型不是越抽象越好","s":"function pick<T, K extends keyof T>(o: T, keys: K[]): Pick<T, K> 这种签名很好，","c":null}]},{"id":"fs-ch09/04-typescript-practical-recipes","file":"04-typescript-practical-recipes.md","title":"TypeScript 类型系统实战手记：凯喵的十二次「编译通过但运行炸」现场","kind":"flow","secs":[{"h":"开场：类型是编译期的，运行时什么都没有","s":"这句话听着像废话，但它是这一篇所有坑的总根。TypeScript 的类型在编译后全部擦除，产物里只剩下 JavaScript。所以任何依赖类型的运行时判断都不会起作用，任何泛型的运行时行为都只能靠你自己传进去的实参。","c":{"lang":"typescript","code":"interface Point { x: number; y: number; }\ninterface Vector { x: number; y: number; }\n\nconst p: Point = { x: 1, y: 2 };\nconst v: Vector = p;   // 完全合法：形状一样就是一样"}},{"h":"收尾：类型是文档，也是约束，但不是保证","s":"凯喵最后想说：TypeScript 最强的地方不是「让你写得更快」，而是「让你在重构时敢动手」。改了字段名，编译器会把所有引用点列出来；改了函数签名，调用方全部标红。这种「改一处、编译器告诉你影响范围」的能力，是动态语言给不了的。","c":null}]}],"exams":[{"kind":"choice","q":"关于 TypeScript 的结构类型，正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"结构类型要求两个类型声明继承自同一个父类型才能互相赋值"},{"k":"B","t":"结构类型只比较成员形状：多出成员合法，缺少必需成员不合法"},{"k":"C","t":"结构类型在运行时也会检查对象形状，因此能替代数据校验"},{"k":"D","t":"结构类型下 { id: string } 与 { orderId: string } 不能互相赋值"}],"ans":"B","why":"结构类型比形状不比名字：具备所需成员即可赋值，多出的成员不报错、缺少必需成员报错。类型在运行时被擦除，不做任何检查，因此不能替代数据校验。A 描述的是名义类型；D 恰好说反了——同形状不同类型在结构类型下可以互相赋值，这正是需要品牌类型的原因。"},{"kind":"output","q":"读代码写输出（类型擦除）","stem":"ts interface Circle { kind: \"circle\"; r: number } interface Square { kind: \"square\"; side: number } type Shape = Circle | Square; function describe(s: Shape): string { if (s.kind === \"circle\") return…","opts":[],"ans":"circle:number square:number function","why":"前三行与类型无关，只需注意两点：① typeof s.r 是 JS 的 typeof 运算符，返回运行时类型字符串 number，不是 TS 的类型查询；② 第三行 typeof describe 在函数声明之后返回 function。类型本身（Circle/Shape）编译后不存在，无法被 typeof 观察到。"},{"kind":"fix","q":"改错：这个守卫为什么形同虚设","stem":"下面的类型守卫编译通过，但在运行时会把 { r: 1 } 判成 Circle，导致 area 返回 NaN。指出问题并改正。 ts function isCircle(x: unknown): x is Circle { return typeof x === \"object\" && x !== null; } function area(s: unknown): number { if (isC…","opts":[],"ans":"function isCircle(x: unknown): x is Circle { return ( typeof x === \"object\" && x !== null && (x as { kind?: unknown }).kind === \"circle\" && typeof (x as { r?: u…","why":"守卫只判断了「是对象且非 null」，任何对象都会通过，于是 s.r 取到 undefined，undefined 2 得到 NaN。类型守卫的正确性靠逐字段校验，而 x is Circle 只是向编译器声明「我保证」，编译器不会验证。修法：校验判别字段 kind === \"circle\" 与必需字段 r 的类型。生产代码更推荐用 Zod 从 schema 生成守卫，避免手写与…"},{"kind":"choice","q":"unknown 与 any 的差别","stem":"关于 unknown，正确的是","opts":[{"k":"A","t":"unknown 与 any 完全等价，只是写法不同"},{"k":"B","t":"unknown 能接受任何值，但使用前必须先收窄，否则编译报错"},{"k":"C","t":"unknown 只能用于函数参数，不能用于变量"},{"k":"D","t":"unknown 会在运行时做类型检查，any 不会"}],"ans":"B","why":"unknown 是类型系统的「安全顶」：任何值都能赋给它，但它不能直接参与运算或取属性，必须先收窄（typeof / 守卫 / 断言）。any 则双向通行、跳过所有检查。二者在运行时都不存在，所以 D 错误。C 也错——let x: unknown 完全合法。"},{"kind":"coding","q":"实现类型安全的 groupBy","stem":"实现一个泛型函数 groupBy<T, K extends string>(items: T[], keyOf: (item: T) => K): Record<K, T[]>：把数组按 keyOf 返回的键分组，返回一个 Partial 语义的字典（某键可能不存在）。要求：① 不使用 any；② 空数组返回空对象；③ 同一键的元素保持原有相对顺序。写出实现并在 main 中自测两组数据。","opts":[],"ans":"function groupBy<T, K extends string>(items: T[], keyOf: (item: T) => K): Partial<Record<K, T[]>> { const out: Partial<Record<K, T[]>> = {}; for (const it of it…","why":"要点有三：① 返回类型用 Partial<Record<K, T[]>> 而不是 Record<K, T[]>——后者声称每个键都存在，与事实不符，会在运行时误导调用方（取到 undefined 却以为有数组）；② ??= 保证同键追加而不是覆盖，且顺序天然保持；③ 全程零 any，keyOf 的返回类型由泛型 K 约束，调用方传错字段名会在编译期报错。"},{"kind":"coding","q":"用可辨识联合 + never 实现穷尽检查","stem":"定义三种形状：Circle（r）、Square（side）、Triangle（a、b、c）。用可辨识联合 Shape 表示，实现 area(s: Shape): number，并在 default 分支上用 never 做穷尽性检查。然后新增一种 Rect（w、h）但故意不写它的分支，用注释说明此时编译器的报错会出现在哪一行。","opts":[],"ans":"type Circle = { kind: \"circle\"; r: number }; type Square = { kind: \"square\"; side: number }; type Triangle = { kind: \"triangle\"; a: number; b: number; c: number…","why":"三角形用海伦公式。穷尽检查的关键是 const never_: never = s：三个 case 全过后 s 的类型被收窄成 never，赋值成立；一旦给 Shape 加第四种 Rect 而 switch 没加分支，s 在 default 里将是 Rect，赋给 never 立刻报 Type 'Rect' is not assignable to type 'never'。报…"},{"kind":"output","q":"读代码写输出（泛型擦除后的行为）","stem":"ts function first<T>(arr: readonly T[]): T | undefined { return arr[0]; } console.log(first([10, 20])); console.log(first<string>([])); console.log(String(first([\"a\"])));","opts":[],"ans":"10 undefined a","why":"泛型参数 <string> 只在编译期存在，产物里 first([]) 与 first([10, 20]) 是同一个函数，都只是取下标 0。空数组取 [0] 得 undefined，console.log(undefined) 打印 undefined；第三行显式 String() 所以打印 a 而不是带引号的 'a'。"}],"works":[{"h":"把 any 当「先跑通再说」","d":"错在：function handler(req: any) { return req.body.user.name; } —— 一路 any 到底，编译零报错。 为什么：any 会让整条调用链的类型检查失效，而且会传染：返回 any 的函数赋给有类型的变量也不会报错。上线后 req.body.user 为 undefined 时，错误…"},{"h":"用 as 代替类型守卫","d":"错在：const user = data as User; —— 把接口返回直接断言成业务类型。 为什么：断言只在编译期有效，且编译器不检查可行性（只拦明显不可能的转换）。运行时 data 是什么就是什么，字段缺失时类型系统完全不知道。这类 bug 在联调期和数据格式变更后集中爆发。"},{"h":"以为泛型能约束运行时","d":"错在：function isType<T>(x: unknown): x is T { return true; } —— 想写一个通用类型判断。 为什么：类型被擦除，T 在运行时不存在，函数体里无法知道 T 是什么，所以只能 return true（等于永远相信）。这种守卫会让所有下游收窄都建立在谎言上，比不写更糟。"},{"h":"用 interface 期望拦住多余字段","d":"错在：interface User { id: string } 然后期待 { id, isAdmin: true } 赋值时报错。 为什么：结构类型只看「有没有缺少必需成员」，多出来的成员默认允许（只有对象字面量直接赋值时才有 excess property check，一旦经过变量中转就失效）。"},{"h":"switch 的 default 直接 throw 而不做 never 检查","d":"错在：可辨识联合写成 default: throw new Error(\"unreachable\")，以为运行时抛错就安全了。 为什么：这只能拦住「运行时真的走到 default」，拦不住「新增了一个 kind 却忘了加 case」——因为编译不报错，问题只在真有人提交那种数据时才暴露。类型系统本来能在这个 PR 里就提示，被 thr…"},{"h":"catch 里 as any 了事","d":"错在：catch (e: any) { console.log(e.message) }，或者直接 catch (e) { e.message } 被 TS 报错后改成 as any。 为什么：catch 捕获的东西理论上可以是任何值——JS 里 throw \"字符串\"、throw {code: 1} 都合法。断言成 any 之后，e…"},{"h":"把 enum 当唯一选项，忽略 as const 对象","d":"错在：用数字 enum 表示状态，接口返回 0/1/2，前后端各维护一份映射。 为什么：数字 enum 在编译后留下双向映射对象（{0: \"Active\", Active: 0}），体积翻倍；而且接口里传的是数字，语义完全丢失，后端加一个状态值前端不会报错。字符串 enum 好一些，但仍是运行时对象。"},{"h":"泛型约束写成 T extends any","d":"错在：写 function first<T extends any>(xs: T[]): T，以为这是「任意类型」的规范写法。 为什么：any 作为约束等于没有约束，T 依然是任意类型，而且 any 的传染性会影响推断。更实际的问题是：这个签名没有表达「xs 必须有长度」——传 {} 也能过编译。"}],"asks":[{"q":"TypeScript 的类型在运行时存在吗？这对工程实践有什么影响？","a":"不存在，TS 是 erasure 语义：编译后类型信息全部删除，产物是普通 JavaScript。影响有三层：① 不能用类型做运行时判断（instanceof T 对泛型参数不成立，重载编译后是同一函数）；② 外部数据（API 响应、localStorage、URL 参数）必须在入口做运行时校验，类型系统帮不上忙；③ as 断言零成本也零保护，它只影响编译期。","fu":["既然类型不存在，as 到底做了什么？","为什么 JSON.parse 返回 any 而不是 unknown？"],"tag":"通用"},{"q":"结构类型和名义类型各有什么问题？实际项目里怎么补救结构类型的不足？","a":"结构类型比形状，开放但会「意外的兼容」——{ id: string } 既能当 UserId 也能当 OrderId。名义类型比名字，安全但需要显式继承，跨库时常常被迫适配。补救结构类型的三个手段：① 品牌类型（string & { __brand: 'UserId' }）给同形状不同类型打标签；② 可辨识联合用 kind 字段区分语义；③ 边界处 schema 校验（Zod/Valibot），同…","fu":["品牌类型在运行时有什么痕迹？","为什么说 TS 是 unsound 的？举两个绕过检查的例子。"],"tag":"通用"},{"q":"any、unknown、never 三者分别用在什么场景？","a":"any 关闭检查，能双向赋值，是会传染的逃生舱——只应出现在从 JS 迁移的过渡代码里并加 TODO。unknown 是安全顶，任何值都能赋给它但不能直接使用，必须先收窄；外部输入一律用它。never 是空集，任何值都不能赋给它（除 never 本身），用途有三：表示不可达的 default 分支做穷尽检查、表示永不返回的函数（如 throwError(): never）、在条件类型里作过滤结果。","fu":["never 和 void 有什么区别？","为什么 never 能赋值给所有类型，反过来不行？"],"tag":"通用"},{"q":"泛型约束（extends）和条件类型里的 extends 是同一个东西吗？","a":"不是，同一个关键字两种角色。出现在类型参数位置 <T extends X> 是约束：限制 T 必须是 X 的子类型，不满足直接报错。出现在类型表达式 T extends X ? A : B 是判断：在类型层面做条件分派，配合 infer 可以从输入类型里提取片段（如 ReturnType）。读签名时要先看位置再判断含义。","fu":["infer 能用在哪些位置？举一个从函数的参数类型提取的例子。","分布条件类型（naked type parameter）为什么对联合类型会展开？"],"tag":"通用"}]},{"id":"fs-ch10","subj":"fullstack","title":"Vue 3 + TypeScript + Pinia：响应式原理与 ref/reactive 边界","summary":"Vue 3 的响应式是「用 Proxy 在对象与读取方之间插一层依赖收集」：effect 运行时会记下自己读过哪些字段（track），字段被改写时再通知这些 effect 重跑（trigger）。这套机制决定了 ref 为什么必须读 .va…","concepts":[{"id":"fs-ch10/01-reactivity-and-dependency-tracking","file":"01-reactivity-and-dependency-tracking.md","title":"响应式原理与依赖追踪","kind":"compare","secs":[{"h":"一、机制：Proxy 与依赖收集","s":"Object.defineProperty 只能给「已经存在的某个属性」装 getter/setter，所以 Vue 2 必须在一开始","c":{"lang":"text","code":"   reactive(obj.x)          effect(fn)\n        │                        │\n        ▼                        ▼\n   ┌─────────┐   track()   ┌──────────┐\n   │  dep: x  │◀───────────│  active   │  读 obj.x 时把 effect 登记为依赖\n   └─────────┘             │  effect   │\n        ▲                   └──────────┘\n        │   trigger()               │\n        └────── obj.x = new ────────┘  写时反向通知 effect 重跑"}},{"h":"二、失效场景、派发时机与 computed","s":"理解了上面几点，「响应性丢失」就不再是玄学，而是可枚举的几种情况：","c":null},{"h":"三、调试、对照与取舍","s":"排查顺序是：① 确认读的是不是代理——console.log 出来若是原始值或普通对象，就说明已经脱钩；② 确认 effect 确实「读」了那个字段（只写没读不会收集依赖）；③ 确认改的是不是同一个代理（整体替换会换对象）；④ 数组/M…","c":null}]},{"id":"fs-ch10/02-ref-vs-reactive-boundary","file":"02-ref-vs-reactive-boundary.md","title":"ref 与 reactive 的边界","kind":"compare","secs":[{"h":"一、选型与两个高频坑","s":"函数返回值/参数独立流动的状态；以及「这个状态未来可能被整体替换但你还想保持引用」的情况。","c":{"lang":"js","code":"import { reactive, toRefs } from 'vue'\n\nconst state = reactive({ count: 0, name: 'a' })\n\n// ❌ 直接解构：count 变成普通数字，后续 state.count++ 不会同步到它\nconst { count } = state\n\n// ✅ toRefs：解构出来仍是 ref，读写原路回到 state\nconst { count: countRef } = toRefs(state)\n…"}},{"h":"二、shallow 边界与拆包规则","s":"默认 reactive 是「深层」的——任何一层子对象都被代理。但有时候你不想要深层，典型是：这个","c":null},{"h":"三、设计取舍与跨框架对照","s":"社区曾有过 <script setup> 里的 $ref 语法糖（$ref 让你写 count++ 而非 count.value++），通过编译期转换隐去 .value。但它在 3.3 被官方标记为不再推荐，原因是：语法糖让 ref 和…","c":null}]},{"id":"fs-ch10/03-pinia-store","file":"03-pinia-store.md","title":"Pinia 状态管理与组合式 store","kind":"compare","secs":[{"h":"一、写法、依赖与 Vuex 对照","s":"Pinia 提供两种定义 store 的风格：","c":null},{"h":"二、四个高频陷阱与组织方式","s":"defineStore('id', { state: () => ({...}) }) 里 state 是函数，不是对象字面量。原因和 React 的 useState 初始化函数一样：如果写成对象，所有 store 实例会共享同一份引…","c":null},{"h":"三、跨框架对照、边界与反模式","s":"把 Pinia 和 React 生态对照很有启发：Zustand 也是「create 一个 store、组件里 hook 取用、默认浅比较订阅」，思想上和 Pinia Setup 写法几乎一致；Redux 则强制单一 store + r…","c":null},{"h":"四、拆分策略与收口","s":"当单个 store 膨胀到几百行的时候，就该拆了。拆分的维度建议按业务域来拆，比如用户、订单、商品、界面，这比按数据类型拆（所有列表放一起、所有表单放一起）更利于维护，因为需求变更通常是按业务域发生的。拆分之后要注意依赖方向：底层域不应…","c":null}]},{"id":"fs-ch10/04-snippets","file":"04-snippets.md","title":"fs-ch10 · 响应式实战代码片段","kind":"flow","secs":[{"h":"ref 与 reactive 的基本形态","s":"","c":{"lang":"ts","code":"import { ref, reactive } from 'vue'\nconst count = ref(0)          // 原始值用 ref\nconst state = reactive({ n: 0, list: [] as number[] }) // 对象用 reactive\ncount.value++                 // 逻辑里必须 .value\nstate.n++                     // reactive 直接读写"}},{"h":"computed 派生","s":"","c":{"lang":"ts","code":"import { computed } from 'vue'\nconst double = computed(() => count.value * 2)\n// 只读派生；要可写用 computed({ get, set })"}},{"h":"watch 精确监听某个字段","s":"","c":{"lang":"ts","code":"import { watch } from 'vue'\nwatch(() => state.n, (nv, ov) => {\n  console.log(`n: ${ov} -> ${nv}`)\n})\n// 不要传整个 reactive 对象又不 deep，否则深层变更不触发"}},{"h":"watchEffect 自动追踪","s":"","c":{"lang":"ts","code":"import { watchEffect } from 'vue'\nwatchEffect(() => {\n  // 这里读到的响应式依赖会被自动收集\n  document.title = `count=${count.value}`\n})"}},{"h":"解构保持响应性：storeToRefs","s":"","c":{"lang":"ts","code":"import { storeToRefs } from 'pinia'\nconst store = useUserStore()\nconst { name, avatar } = storeToRefs(store) // 仍是 ref，保响应\n// 不要 const { name } = store —— 会丢响应性"}},{"h":"Pinia setup store","s":"","c":{"lang":"ts","code":"import { defineStore } from 'pinia'\nimport { ref, computed } from 'vue'\nexport const useUserStore = defineStore('user', () => {\n  const name = ref('')\n  const isLogin = computed(() => name.value.length > 0)\n  function login(n: string) { name.value = n }\n  return { name, isLogin, login }\n})"}},{"h":"Pinia options store（对照）","s":"","c":{"lang":"ts","code":"import { defineStore } from 'pinia'\nexport const useCartStore = defineStore('cart', {\n  state: () => ({ items: [] as string[] }),\n  getters: { count: (s) => s.items.length },\n  actions: { add(i: string) { this.items.push(i) } },\n})"}},{"h":"列表渲染与 key","s":"","c":{"lang":"vue","code":"<template>\n  <li v-for=\"item in state.list\" :key=\"item.id\">{{ item.name }}</li>\n</template>"}},{"h":"异步 setup 配合 Suspense","s":"","c":{"lang":"ts","code":"// 组件 <script setup> 内\nconst { data } = await useFetch('/api/user')\n// 父组件需用 <Suspense> 包裹，否则渲染时 data 还是空"}},{"h":"🧑‍💻 程序员视角","s":"ref 适合基本类型、reactive 适合对象，但 reactive 解构会丢响应性——解构出来的是普通值。computed 有缓存、watchEffect 没有，前者适合派生状态、后者适合副作用。watch 默认浅监听，监听对象内部…","c":null},{"h":"🎓 博士生视角","s":"Vue 3 的响应式基于 Proxy：读取时 track 收集依赖、写入时 trigger 派发更新，相比 Vue 2 的 Object.defineProperty 能拦截新增/删除属性与数组索引。ref 与 reactive 的差异…","c":null},{"h":"📚 考研者视角","s":"前端面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"关于 Vue 3 响应式的依赖收集，正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"依赖关系在组件创建时一次性固定，之后不再变化"},{"k":"B","t":"effect 运行时会把读过的字段登记到 (对象, 字段) -> effect 集合 的索引里（track），字段改写时…"},{"k":"C","t":"Vue 3 仍用 Object.defineProperty，只是做了性能优化"},{"k":"D","t":"只有模板渲染函数会被收集为依赖，watch 和 computed 不受影响"}],"ans":"B","why":"Vue 3 用 Proxy + 全局 activeEffect：effect 运行时读字段触发 get 拦截执行 track，把 activeEffect 登记进 (target,key)->Set(effects) 的 WeakMap；字段改写触发 set 拦截执行 trigger 通知。依赖是随控制流动态重收集的（每次重跑先 cleanup 再收集），故 A 错。Vue 3…"},{"kind":"output","q":"读代码写输出（ref 必须 .value）","stem":"js const count = ref(1); console.log(\"initial value:\", count.value); count.value = count.value + 4; console.log(\"after +4:\", count.value); let seen = []; effect(() => { seen.push(count.value); }); cou…","opts":[],"ans":"initial value: 1 after +4: 5 effect saw: 5 -> 100","why":"ref 是容器对象，读必须 count.value：初始 1；自增后是 5。effect 第一次运行把当前值 5 推入 seen；随后 count.value=100 触发 trigger，effect 重跑推入 100，所以 seen 是 5 -> 100。"},{"kind":"fix","q":"改错：为什么解构后视图不更新","stem":"下面的组件逻辑期望「点击按钮计数 +1 并刷新」，但 count 永远停在 0。指出问题并改正。 js const store = reactive({ count: 0 }); const { count } = store; // 局部变量 function inc() { count++; } // 改的是局部值快照 console.log(count);","opts":[],"ans":"const store = reactive({ count: 0 }); // 用 toRefs 把字段转成 ref，保持响应性 const { count } = toRefs(store); function inc() { count.value++; } // 注意 ref 要 .value console.…","why":"解构 const { count } = store 取出的是 store.count 当时的原始值 0（一个数字），和 proxy 脱钩；count++ 只是改局部变量，原对象没动、effect 也没订阅局部变量。正确做法是用 toRefs(store) 生成 ref 再解构，写 count.value++，读写都回到原对象。"},{"kind":"choice","q":"shallowRef 与 ref 的差别","stem":"关于 shallowRef，正确的是","opts":[{"k":"A","t":"shallowRef 完全不能触发，等于普通变量"},{"k":"B","t":"shallowRef 只对 .value 的整体替换做响应，内部对象的字段改动不触发"},{"k":"C","t":"shallowRef 比 ref 更深，会递归代理内部所有层级"},{"k":"D","t":"shallowRef 是 ref 的语法糖，二者运行时完全一致"}],"ans":"B","why":"shallowRef 只对 .value 被整体替换（x.value = newObj）做响应，内部对象不被递归代理，所以 x.value.field = 1 不会触发更新。它是用来明确「只关心引用替换、不关心内部」的边界声明，不是语法糖也不是完全无效。需要强制派发可用 triggerRef。"},{"kind":"coding","q":"实现一个迷你响应式：reactive + effect","stem":"用 Proxy 实现一个极简响应式：支持 reactive(obj)（深层代理）、effect(fn)（首次运行并收集依赖，依赖变化时重跑）、对象字段改写自动触发。要求：① 用 WeakMap(target) -> Map(key) -> Set(effects) 存依赖；② 数组 push 也要能触发（提示：拦截数组方法）；③ effect 重跑前先清理旧依赖再重收集。写出并在 main 中自测…","opts":[],"ans":"const targetMap = new WeakMap(); let activeEffect = null; const effectStack = []; function track(t, k){ if(!activeEffect) return; let dm=targetMap.get(t); if(!d…","why":"核心是 track/trigger 与 Proxy 拦截：get 时 track 记录 (t,k)->effect；set 时若值变化 trigger 通知。深层靠 get 返回时惰性 reactive(res)。数组方法需 instrument（push 后手动 trigger length）以绕过 V8 快速路径。effect.run 先 cleanup 旧依赖再重收集，保…"},{"kind":"fix","q":"改错：Pinia store 持久化泄露敏感信息","stem":"下面的 Pinia 配置把整个用户 store 持久化到 localStorage，包含 token。改为只持久化非敏感字段（theme、lang），并解释为什么。 js defineStore('user', { state: () => ({ name: '', token: '', theme: 'dark', lang: 'zh' }), persist: true, })","opts":[],"ans":"defineStore('user', { state: () => ({ name: '', token: '', theme: 'dark', lang: 'zh' }), // 只持久化非敏感偏好，token/name 不落盘 persist: { paths: ['theme', 'lang'] }, })","why":"persist: true 会把 state 整体序列化进 localStorage，而 localStorage 任意脚本可读、易遭 XSS 窃取，把 token 存进去等于明文暴露凭据。应当用 paths 白名单只挑 theme/lang 这类偏好字段，token 放内存 ref 或 httpOnly cookie，刷新后由后端重新下发。"},{"kind":"output","q":"读代码写输出（深层代理触发）","stem":"js const s = reactive({ user: { age: 18 } }); let log = []; effect(() => { log.push(\"age=\" + s.user.age); }); console.log(\"init:\", log.join(\" | \")); s.user.age = 20; console.log(\"after deep set:\", log…","opts":[],"ans":"init: age=18 after deep set: age=18 | age=20","why":"effect 读取 s.user.age 时，get 拦截对 user（对象）惰性地也套了 Proxy，所以改 s.user.age 会触发。init 打印 age=18；深层改写后 effect 重跑打印 age=20，日志为 age=18 | age=20。"},{"kind":"choice","q":"Pinia Setup 写法的描述，正确的是","stem":"关于 Pinia 的 Setup 写法，正确的是","opts":[{"k":"A","t":"必须在 store 里写 mutations 才能改状态"},{"k":"B","t":"store 内部直接用 ref/computed/function 定义状态、派生与行为，返回要暴露的成员即可"},{"k":"C","t":"Setup 写法无法在一个 store 里调用另一个 store"},{"k":"D","t":"Setup 写法不支持 TypeScript 类型推导"}],"ans":"B","why":"Setup 写法复用 Vue 组合式 API：用 ref 定义状态、computed 定义派生、function 定义 action，return 出要暴露的成员，没有 mutation 概念（A 错）。store 间可相互 useOtherStore() 调用（C 错），且基于 TS 原生推断、类型推导很好（D 错）。"}],"works":[{"h":"解构 reactive 对象导致响应性丢失","d":"错在：const { count } = useStore() 或 const { name } = reactive(form)，之后改 state.count 视图不更新。 为什么：解构出来的 count/name 只是那一刻的值（原始值或普通引用），和原 Proxy 断了联系。后续对原对象的修改不会再反映到这个局部变量上，eff…"},{"h":"在响应式对象上整体替换却指望旧引用更新","d":"错在：let state = reactive({ a: 1 }); state = reactive({ a: 2 })，然后发现旧的订阅没反应。 为什么：你把变量指到了一个全新的代理对象，旧代理上的 effect 依赖仍然挂在旧对象上，新对象没人订阅。这是「重新赋值变量」与「更新对象内容」混淆。"},{"h":"忘记 ref 要写 .value","d":"错在：if (count > 0)、count++、emit(count) 直接拿 ref 当值用，得到的是 ref 对象。 为什么：ref 是个容器对象，count 本身不是数字。模板里编译器帮你拆了 .value，但 <script setup> 逻辑里不会，于是比较、自增、传参都作用在对象上，结果恒为 NaN 或 [object…"},{"h":"对 Proxy 手写的玩具响应式发现 push 不触发","d":"错在：自己用 new Proxy 写了 reactive，数组 list.push(1) 后 effect 不重跑。 为什么：V8 里 Array.prototype.push 对 length 的改写走快速路径，会绕过 Proxy 的 set 拦截。真正的 Vue 在 get 拦截里对 push/splice 等方法做了 instr…"},{"h":"shallowRef 内部改字段不触发","d":"错在：const big = shallowRef({ items: [] }); big.value.items.push(1)，视图没更新。 为什么：shallowRef 只对 .value 的整体替换做响应，它不会递归代理内部对象，所以 big.value.items.push 改的是内部普通数组，没经过任何拦截。"},{"h":"把响应式对象直接当 Map 的 key","d":"错在：const m = new Map(); m.set(reactiveObj, 'x')，之后用另一个看起来一样的对象去查却查不到。 为什么：Map 用 SameValueZero 比较 key，两个「内容相同但引用不同」的代理对象不相等。而且普通 Map 对 key 的存取不经过 Vue 的 instrument，无法触发响应…"},{"h":"在 store 的 state 之外放模块级可变变量","d":"错在：store 文件里写了 let cache = {}，在 action 里改它，以为它是「全局状态」。 为什么：这个 cache 脱离了 Pinia 的响应式与单例管理：它不受 devtools 追踪、刷新不重置、多个测试间会串味，和「藏在组件外的全局变量」没区别。"},{"h":"Pinia 持久化把 token/敏感信息落盘","d":"错在：persist: true 把整个 user store（含 token、权限）写进 localStorage。 为什么：localStorage 任何脚本可读、易被 XSS 窃取，把认证凭据持久化等于把钥匙放门口。而且刷新后 hydrate 可能读到过期/被篡改的权限。"}],"asks":[{"q":"Vue 3 的响应式是怎么实现的？track 和 trigger 分别做什么？","a":"建立在 Proxy 之上。每个被 reactive 的对象罩一层 Proxy；读取字段时 get 拦截器执行 track，把『当前正在跑的 effect（全局 activeEffect）』登记进 WeakMap(target)->Map(key)->Set(effect) 这张反向索引；改写字段时 set 拦截器执行 trigger，找到对应 Set 里的 effect 逐个重跑。effect 重…","fu":["为什么用 WeakMap 而不是普通 Map？","effect 重跑前为什么要先 cleanup？不 cleanup 会怎样？"],"tag":"通用"},{"q":"为什么 ref 要写 .value，而 reactive 不用？","a":"因为 JS 的原始类型（number/string/boolean）不是对象，无法被 Proxy 包裹、无法装拦截器。ref 把原始值装进一个带 value 属性的容器对象，对这个容器做访问器/Proxy 拦截，于是读 ref.value、写 ref.value=... 都能走 track/trigger。reactive 只作用于对象，它直接代理对象本身，所以访问属性时天然经过拦截，不需要再套一…","fu":["ref 能不能装对象？装了之后深层还响应吗？","那为什么不全用 ref 而还要有 reactive？"],"tag":"通用"},{"q":"为什么解构 reactive 对象会丢响应性？toRefs 怎么解决？","a":"解构 const { x } = reactiveObj 取出的是 x 当时的原始值/引用，和原 Proxy 脱离了关系，后续对原对象的修改不会再反映到这个局部变量上，effect 也不订阅它。toRefs 遍历对象每个属性，为每个属性生成一个 ref，这个 ref 的 getter/setter 直接读写原对象的对应字段，于是解构后仍是 ref，读写 .value 会原路回到原对象，链路不断。","fu":["toRefs 和 toRef 有什么区别？","storeToRefs 为什么在 Pinia 里需要？"],"tag":"通用"},{"q":"数组和 Map 在响应式里有什么坑？Vue 怎么处理的？","a":"数组：push/pop/splice 等内建方法在 V8 有快速路径，对 length 的改写可能绕过 Proxy 的 set 拦截，导致 effect 不触发。Vue 在 get 拦截里对这些方法做 instrument，返回一个包了一层、执行原方法后手动 trigger(length) 的版本。Map/Set：它们的 get/set/has/delete 是方法而非属性访问，Proxy 的 g…","fu":["如果我自己用 Proxy 写响应式，最容易漏掉哪一步？","为什么 Vue 不干脆每次都递归代理整棵树？"],"tag":"通用"}]},{"id":"fs-ch11","subj":"fullstack","title":"Spring Boot 3 工程骨架：分层边界、异常与校验收口","summary":"Spring Boot 让「能跑起来」很容易，但「跑得对、改得动」依赖骨架纪律。本章讲清三条边界：一是分层边界——controller 只接 HTTP、service 只放业务、repository 只管持久化，依赖方向单向、禁止跨层调用…","concepts":[{"id":"fs-ch11/01-layered-boundaries","file":"01-layered-boundaries.md","title":"分层边界与依赖方向","kind":"flow","secs":[{"h":"一、三层结构与依赖方向","s":"响应、处理状态码。它不该写业务规则，也不该碰数据库。它的输入是 HTTP 请求，输出是 HTTP 响应","c":{"lang":"text","code":"   请求 ─▶ Controller ── 只做收口(参数/DTO) ─▶ Service ── 业务 & 事务 ─▶ Repository ──▶ DB\n             │                                      │                     │\n             └──── DTO ⇄ Entity 转换边界 ────────────┘                Entity/Model\n   禁止：Controller 直连 DB / Repository 反向调 Service / 跨层穿透"}},{"h":"二、把职责钉死在具体位置","s":"Controller 的职责边界是「HTTP 协议与业务的翻译层」：解析路径/查询/请求体、做最轻量的入参格式校验、调用一个 service 方法、把结果包成 HTTP 响应并选好状态码。它不该包含 if (user == null)…","c":null},{"h":"三、回报、事故与反思","s":"分层最直接的好处是「能分层测」：测 repository 用真实或内存数据库；测 service 用 @MockBean 把 repository 换成 mock，只验证业务规则；测 controller 用 MockMvc 直接打 H…","c":null}]},{"id":"fs-ch11/02-unified-exception","file":"02-unified-exception.md","title":"统一异常处理与错误码","kind":"flow","secs":[{"h":"一、收口机制与异常分类","s":"Spring 提供 @RestControllerAdvice（=@ControllerAdvice + @ResponseBody），它能在一个类里","c":{"lang":"java","code":"@RestControllerAdvice\npublic class GlobalExceptionHandler {\n    @ExceptionHandler(BizException.class)\n    public ResponseEntity<ApiError> handleBiz(BizException e) {\n        return ResponseEntity.status(e.getHttpStatus())\n               .body(new ApiError(e.getCode(), e.getMessage()));\n    }\n    @ExceptionHandler(Exception.class)\n    public ResponseEntity<ApiError> handleOther(Exception e) {\n…"}},{"h":"二、匹配顺序与作用域","s":"advice 里可以有多个 @ExceptionHandler 方法，Spring 按「最具体（most specific）优先」匹配：抛 BizException，既匹配 BizException 又匹配其父类的 Exception…","c":null},{"h":"三、可观测性与错误码治理","s":"系统异常「不返前端」不代表「不处理」。正确姿势：advice 捕获系统异常后 log.error(\"unexpected\", e)（带堆栈、落服务端），必要时再上报到集中式日志或告警平台（如 Sentry、ELK）。错误要有「可观测性」…","c":null},{"h":"四、事故复盘与协作边界","s":"曾经有团队为了「方便前端排查」，把异常堆栈直接塞进响应体。结果一次未捕获的数据库异常把表结构、字段名、框架版本全都返了出去，攻击者据此精准构造了注入，造成数据泄露。这件事的教训不是「别用某个框架」，而是「任何内部实现细节都不该越过边界」…","c":null}]},{"id":"fs-ch11/03-validation-and-boundary","file":"03-validation-and-boundary.md","title":"校验与边界收口","kind":"flow","secs":[{"h":"一、声明式约束与自定义","s":"Spring Boot 3 用 Jakarta Validation（规范，jakarta.validation.，实现常用 Hibernate Validator）。","c":{"lang":"java","code":"public class CreateUserDTO {\n    @NotNull @Size(min = 2, max = 10, message = \"用户名长度需 2-10\")\n    private String name;\n\n    @NotNull @Pattern(regexp = \"^1[3-9]\\\\d{9}$\", message = \"手机号格式不正确\")\n    private String phone;\n\n    @Min(18) @Max(120)\n    private Integer age;\n…"}},{"h":"二、边界、性能与文档","s":"声明式校验挡的是「格式错误」，挡不住「逻辑越权」。例如「年龄 18-120」能拦非法输入，但拦不住「用别人的 userId 改了别人的数据」——那是授权（authorization）问题，要在 service 用「当前登录用户 == 资…","c":null},{"h":"三、落地与反思","s":"把校验纪律落成清单：每个入站数据传输对象都有校验注解，且覆盖必填、长度、格式；控制器用声明式触发，不在业务里手写格式判断；业务规则（余额是否足够、状态机是否允许）在服务层抛业务异常，与格式校验分层；同一对象多场景用分组，不复制类；跨字段…","c":null}]},{"id":"fs-ch11/04-snippets","file":"04-snippets.md","title":"fs-ch11 · 工程骨架实战代码片段","kind":"flow","secs":[{"h":"分层调用：Controller → Service → Repository","s":"","c":{"lang":"java","code":"@RestController\n@RequestMapping(\"/users\")\npublic class UserController {\n    private final UserService svc;          // 只注入 Service\n    public UserController(UserService svc) { this.svc = svc; }\n    @PostMapping\n    public UserVO create(@Valid @RequestBody CreateUserDTO dto) {\n        return svc.create(dto);             // 写库编排在 Service\n    }\n…"}},{"h":"业务异常 + 错误码枚举","s":"","c":{"lang":"java","code":"public class BizException extends RuntimeException {\n    private final ErrorCode code;\n    public BizException(ErrorCode code) {\n        super(code.userMessage()); this.code = code;\n    }\n    public ErrorCode getCode() { return code; }\n}\npublic enum ErrorCode {\n    USER_NOT_FOUND(40401, \"用户不存在\");\n…"}},{"h":"统一异常处理 @ControllerAdvice","s":"","c":{"lang":"java","code":"@RestControllerAdvice\npublic class GlobalAdvice {\n    @ExceptionHandler(BizException.class)\n    public ApiError handleBiz(BizException e) {\n        return new ApiError(e.getCode().http(), e.getCode().userMessage());\n    }\n    @ExceptionHandler(Exception.class)\n    public ApiError handleSys(Exception e) {\n        log.error(\"sys err\", e);            // 系统异常只记日志\n…"}},{"h":"入站 DTO + Jakarta 校验","s":"","c":{"lang":"java","code":"public class CreateUserDTO {\n    @NotNull @Size(min = 2, max = 20)\n    private String name;\n    @Email\n    private String email;\n    // getter / setter\n}"}},{"h":"分组校验","s":"","c":{"lang":"java","code":"public interface Update {}        // 分组标记\npublic class UpdateUserDTO {\n    @NotNull(groups = Update.class)\n    private Long id;\n    private String name;\n}\n// controller: public UserVO update(@Validated(Update.class) @RequestBody UpdateUserDTO dto)"}},{"h":"出站 VO 转换（避免实体直出）","s":"","c":{"lang":"java","code":"public record UserVO(Long id, String name, String email) {}\npublic UserVO toVO(User u) {\n    return new UserVO(u.getId(), u.getName(), u.getEmail()); // 不含 password\n}"}},{"h":"声明式事务边界","s":"","c":{"lang":"java","code":"@Service\npublic class UserService {\n    @Transactional                      // 在 Service 用例方法上\n    public UserVO create(CreateUserDTO dto) {\n        User u = repo.save(toEntity(dto));\n        eventPublisher.publish(...);    // 保存后发消息\n        return toVO(u);\n    }\n}"}},{"h":"自定义校验器只做格式级","s":"","c":{"lang":"java","code":"@Target({FIELD})\n@Retention(RUNTIME)\n@Constraint(validatedBy = PhoneValidator.class)\npublic @interface Phone {\n    String message() default \"手机号格式错误\";\n    Class<?>[] groups() default {};\n    Class<? extends Payload>[] payload() default {};\n}\n// PhoneValidator 只校验格式，不查库（查重放 Service）"}},{"h":"🧑‍💻 程序员视角","s":"Controller 只做「参数校验 + 调用 Service + 组装响应」，业务逻辑一律下沉到 Service——Controller 里写 SQL 是分层腐化的第一步。异常要分「业务异常」（可预期，带错误码）与「系统异常」（不可预…","c":null},{"h":"🎓 博士生视角","s":"分层的价值在于「依赖方向单一」：Controller → Service → Repository，反向依赖通过接口（依赖倒置）实现。这一结构让「业务逻辑可测试、基础设施可替换」。DTO/VO/Entity 的区分不是形式主义——Ent…","c":null},{"h":"📚 考研者视角","s":"后端面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"关于 Spring Boot 的分层依赖方向","stem":"正确的是","opts":[{"k":"A","t":"Repository 可以依赖 Service，以便复用业务逻辑"},{"k":"B","t":"依赖方向应单向向下：Controller -> Service -> Repository，反向禁止"},{"k":"C","t":"Controller 直接调 Repository 没关系，只要能跑通"},{"k":"D","t":"Service 应当依赖 Controller，因为请求是从 Controller 进来的"}],"ans":"B","why":"分层依赖必须单向向下：controller 依赖 service，service 依赖 repository，反向/跨层会破坏抽象、让事务与测试失控。A/C/D 都颠倒了方向，是典型的腐化起点。"},{"kind":"output","q":"读代码写输出（统一异常拦截）","stem":"js const handlers = []; function ControllerAdvice(fn){ handlers.push(fn); } function handle(err){ for (const h of handlers){ const r = h(err); if (r) return r; } return { code: 500, message: \"系统错误\", d…","opts":[],"ans":"{\"code\":1001,\"message\":\"用户不存在\",\"data\":null}","why":"BizException 携带 biz=true 且 code=1001，第一个 advice 命中返回 {code:1001,message:'用户不存在',data:null}。注意这里没有把堆栈/异常类名返给前端，符合「业务异常给码给提示」的收口原则。"},{"kind":"fix","q":"改错：系统异常把堆栈返给了前端","stem":"下面的全局异常处理，把系统异常的堆栈直接序列化进了响应体。改正它。 java @RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(Exception.class) public ApiError handleOther(Exception e) { return new ApiError(500…","opts":[],"ans":"@RestControllerAdvice public class GlobalExceptionHandler { private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class); @ExceptionH…","why":"系统异常绝对不能把 e.toString() 或 getStackTrace() 返前端——那等于泄露类名/行号/SQL 给攻击者。正确做法是 log.error 把堆栈写到服务端，响应体只给错误码 + 一句中性提示，detail 置 null。业务异常（BizException）才给具体 message。"},{"kind":"choice","q":"Jakarta 校验应放在哪一层","stem":"「用户名长度 2-10、手机号符合正则」这类格式约束，最合理的落点是","opts":[{"k":"A","t":"写在 Service 方法开头的一堆 if 里"},{"k":"B","t":"写在 Repository 的 SQL 里"},{"k":"C","t":"写在入站 DTO 的 Jakarta 注解上，由 Controller 的 @Validated 触发"},{"k":"D","t":"写在 Vue 前端，后端不用管"}],"ans":"C","why":"格式类约束是「边界问题」，应声明式地写在入站 DTO 的注解（@NotNull/@Size/@Pattern）上，controller 用 @Validated 触发，框架在进方法体前统一校验并收集 fieldErrors。写在 service 的 if 会重复且绕过统一错误结构；只放前端则后端失去防护。"},{"kind":"coding","q":"实现分层调用 + 统一异常 + 校验的串联","stem":"用 JS 模拟一个最小 Spring Boot 风格请求流：① repository 返回数据；② service 做业务（如登录校验，失败抛 Error）；③ controller 先跑入参校验（username 至少3位、password 必填），再调 service，最后用统一 advice 收口——业务/系统异常都包成 {code,message,data} 且系统异常不暴露内部信息。要求…","opts":[],"ans":"function validateLogin(dto){ if(!dto.username) return 'username 必填'; if(!/^\\w{3,}$/.test(dto.username)) return 'username 至少3位'; if(!dto.password) return 'passwo…","why":"三层职责清晰：validateLogin 是边界格式校验（声明式思想的命令式版）；loginService 是业务层，条件不满足抛 Error；controller 先校验再调 service，并用 try/catch 兜底成统一响应。关键点是系统异常只返「系统繁忙」、绝不把 e.stack/e.message 给前端，对应 @ControllerAdvice 的兜底分支。"},{"kind":"fix","q":"改错：把 Entity 当 DTO 序列化泄露密码","stem":"下面的接口直接把 User 实体返回，包含密码字段。改为只暴露安全字段。 java @GetMapping(\"/{id}\") public User getUser(@PathVariable Long id) { return userRepository.findById(id).orElseThrow(); // User 含 password/salt }","opts":[],"ans":"public record UserVO(Long id, String name, String email) {} @GetMapping(\"/{id}\") public UserVO getUser(@PathVariable Long id) { User u = userRepository.findById…","why":"直接序列化 Entity 会把 password/salt 等敏感字段泄露给前端，还可能在延迟加载/循环引用时序列化失败。应定义专门的出站 VO，在 controller 或 converter 里做显式映射，只含前端该看的字段；敏感字段再用 @JsonIgnore 兜底。"},{"kind":"output","q":"读代码写输出（分组校验）","stem":"js function validateGroup(dto, group, rules){ const errors = []; for (const [field, rule] of Object.entries(rules)){ if (rule.groups && !rule.groups.includes(group)) continue; const v = dto[field]; if…","opts":[],"ans":"[] [\"id 必填(update)\"]","why":"insert 场景只启用标注了 insert 分组的约束：id 只在 update 分组，故 insert 不校验 id，只 name 必填且已提供，结果为空数组。update 场景启用 update 分组：id 必填但 dto 没给，所以报 id 必填(update)。这演示了「同一 DTO 多场景用分组」避免复制 DTO。"},{"kind":"choice","q":"业务异常 vs 系统异常的处理","stem":"关于二者在统一异常里的处理，正确的是","opts":[{"k":"A","t":"都直接把 e.getMessage() 返给前端，方便排查"},{"k":"B","t":"业务异常给业务码+友好提示（可展示），系统异常只返中性提示并记日志（藏堆栈）"},{"k":"C","t":"系统异常比业务异常严重，所以也不该记录日志"},{"k":"D","t":"二者应该合并成一个异常类，用布尔字段区分"}],"ans":"B","why":"业务异常是「请求在业务上不成立」，可预期、要给用户友好提示+业务码；系统异常是故障，用户看不懂也不该看，前端只收「系统繁忙」，真实原因写服务端日志供排查。A 泄露敏感信息；C 说反了（系统异常更要记日志告警）；D 把两类语义混在一起，不利分类处理。"}],"works":[{"h":"在 Controller 里直接写 SQL / 调 Repository","d":"错在：@RestController 的方法里直接 @Autowired JpaRepository 然后 repo.save(...)，跳过了 service。 为什么：这破坏了分层：事务边界、业务规则、缓存都失控；Repository 不知道自己在不在事务里，异常也绕过了 service 的统一处理。以后要加「保存前发消息」「保存…"},{"h":"业务异常被当系统异常处理、堆栈返前端","d":"错在：advice 里 return ApiError(500, e.getMessage())，把 e.toString() 甚至堆栈写进响应体。 为什么：业务异常（如「用户不存在」）本是产品体验的一部分，应给明确业务码+友好提示；而系统异常若把堆栈返前端，等于泄露类名/行号/SQL，给攻击者指纹信息。二者都错：前者让用户看不懂，后…"},{"h":"把 Entity 直接当 DTO 序列化返前端","d":"错在：return userRepository.findById(id) 把整个 User 实体（含 password、salt）转 JSON 返给前端。 为什么：实体对应表结构，常含敏感字段（密码、盐、内部标记）。直接序列化会把这些字段泄露出去，还可能因延迟加载（LazyInitializationException）或循环引用（…"},{"h":"校验写在 service 里而非边界 DTO","d":"错在：if (dto.getName() == null || dto.getName().length() < 2) throw ... 散落在各个 service 方法开头。 为什么：格式类约束（必填、长度、正则）是「边界问题」，写在 service 会重复（多处调用同一 DTO 各写一遍）、且绕过了框架的声明式校验与统一错误结构…"},{"h":"分组校验用错导致约束不生效或误生效","d":"错在：DTO 上写了 @NotNull(groups = Update.class) private Long id，但 controller 用 @Validated 没指定分组，结果更新时 id 为 null 也没拦住。 为什么：不指定分组时，只有「没标注任何 group」的约束会生效；标注了 groups 的约束在该场景被跳过…"},{"h":"自定义校验器里打全表查询导致性能崩","d":"错在：写了 @UniqueUsername 校验器，每次请求都对用户表做 SELECT COUNT() 查重，且没加索引。 为什么：注册/保存接口本就高频，每次都触发一次全表扫描式查重，数据库压力随请求线性上升，高峰期直接拖垮整库。而且并发下还有竞态（查完到插入之间别人可能插入相同值）。"},{"h":"事务边界放在 Controller 上","d":"错在：在 @RestController 方法上加 @Transactional，以为这样就能保证原子性。 为什么：HTTP 层不该决定事务：controller 还要做参数解析、响应序列化，这些非业务操作也被包进事务，拉长事务持有连接的时间；而且异常在序列化阶段抛出时事务已提交/回滚行为难控。事务应属于业务用例，归属 service…"},{"h":"Service 间形成循环依赖","d":"错在：A service 构造器注入 B service，B service 又注入 A service，启动时报 BeanCurrentlyInCreationException。 为什么：循环依赖破坏「依赖图无环」原则，Spring 虽然能解一部分（字段注入/setter），但会让初始化顺序脆弱、行为难推理，且常掩盖「职责划分不清…"}],"asks":[{"q":"Spring Boot 项目为什么要分层？依赖方向应该是什么样的？","a":"分层是为了隔离变化、便于测试与替换：controller 只处理 HTTP 语义（收参、调 service、包响应），service 承载业务规则与事务边界，repository 只管持久化。依赖方向必须单向向下：controller -> service -> repository，反向和跨层调用都禁止。这样每层可独立测试（用 mock 替换下一层），改动也被限制在一定范围内。破坏分层（如 co…","fu":["如果业务很简单，还要不要严格分层？","Service 之间互相调用要注意什么？怎么避免循环依赖？"],"tag":"通用"},{"q":"@ControllerAdvice 是怎么把异常收口的？为什么不要返堆栈？","a":"它是一个集中式的 AOP 拦截器：用 @ExceptionHandler(异常类型) 标注方法，Spring 在 controller 抛出异常后、返回响应前，按「最具体优先」匹配对应的处理方法，把异常转成统一结构的响应。这样业务代码只管抛自定义异常、不用写 try/catch。绝不返堆栈的原因是：堆栈含类名、行号、SQL、依赖版本，等于给攻击者指纹信息，且对用户毫无意义；系统异常应该 log.e…","fu":["@ControllerAdvice 和 @ExceptionHandler 的匹配顺序是怎样的？","如果想按业务域返回不同结构怎么办？"],"tag":"通用"},{"q":"业务异常和系统异常该怎么区分处理？","a":"业务异常（如余额不足、用户不存在）是可预期的、用户能理解的错误，应该携带业务错误码和友好提示，可以安全展示，属于产品体验一部分；系统异常（NPE、DB 断连、第三方超时）是不可预期的故障，用户看不懂，前端只收到一句『系统繁忙』，真实堆栈写进服务端日志供研发排查。分流的意义是：业务异常要可枚举、可文档化，系统异常要可观测、可告警。把两者混在一起返 e.getMessage() 既坑用户又坑安全。","fu":["错误码和 HTTP 状态码为什么要解耦？","业务异常该继承 checked 还是 RuntimeException？为什么？"],"tag":"通用"},{"q":"入参校验应该放在哪一层？Jakarta Validation 怎么用？","a":"格式类约束（必填、长度、正则、范围）是边界问题，用 Jakarta Validation 声明式地写在入站 DTO 上（@NotNull/@Size/@Pattern 等），controller 参数加 @Validated 触发，框架在进方法体前自动校验、不通过抛异常由 advice 收口成统一错误。业务规则（余额够不够、状态能否转换）依赖领域知识与当前数据，注解表达不了，写在 service…","fu":["@Valid 和 @Validated 有什么区别？","分组校验怎么解决「同一个 DTO 新增不填 id、更新必填 id」？"],"tag":"通用"}]},{"id":"fs-ch12","subj":"fullstack","title":"服务拆分与网关：拆分判断、网关职责、配置中心","summary":"单体不是原罪，微服务也不是银弹。本章讲清一条主线：什么时候该把单体拆开、拆的边界按什么划（限界上下文与康威定律）、拆完之后入口处放什么（API 网关的鉴权/限流/路由/BFF 边界）、以及配置如何外置、隔离、热更新与保密。重点不在背概念，而…","concepts":[{"id":"fs-ch12/01-when-to-split","file":"01-when-to-split.md","title":"什么时候该拆：单体到微服务的触发条件与代价","kind":"flow","secs":[{"h":"一、先想清楚：为什么拆、按什么切","s":"创业早期、团队只有一两个人、业务领域还在快速探索时，单体是最快的选择。所有代码在一处，","c":{"lang":"text","code":"// 单体内，模块只是目录与包的边界，跨模块调用是普通函数调用\nimport { createOrder } from \"./order\";\nimport { charge } from \"./payment\";\nconst order = createOrder(cart);   // 同步、同进程、可单测\ncharge(order.total);"}},{"h":"二、决策框架与误拆后果","s":"以下情况说明你还不适合拆：","c":null},{"h":"三、论证、粒度与落地","s":"不要凭架构师的直觉。把触发信号列成一张清单逐条打勾：部署耦合有几条成立？团队是否跨过两个","c":null}]},{"id":"fs-ch12/02-gateway-boundary","file":"02-gateway-boundary.md","title":"网关的职责边界：该管什么、不该管什么","kind":"flow","secs":[{"h":"一、职责边界：该管与不该管","s":"网关的价值在于「横切关注点统一处理」，以下几件事天然适合放在网关：","c":{"lang":"text","code":"   client ─▶ Gateway ──┬─ 路由     ─▶ service A\n                       ├─ 鉴权     ─▶ service B\n                       ├─ 限流     ─▶ (超阈值则拒绝 429)\n                       └─ 聚合(BFF)─▶ 多服务扇出后合并\n   网关不管：具体业务校验、DB 连接、领域计算（那是服务的事）"}},{"h":"二、四项核心能力与反模式","s":"路由匹配最经典的坑是顺序。如果先匹配了宽泛的前缀，后面的精确路径就永远到不了：","c":{"lang":"text","code":"// 错误：/api/orders 会先被 /api 吃掉，后面的精确路由形同虚设\nroutes = [ { match: \"/api\", svc: \"catch-all\" }, { match: \"/api/orders\", svc: \"order\" } ]\n// 正确：精确/更长的前缀优先，或用优先级字段显式声明\nroutes = [ { match: \"/api/orders\", svc: \"order\", priority: 10 }, { match: \"/api\", svc: \"catch-all\", priority: 1 } ]"}},{"h":"三、排障与概念辨析","s":"某次大促，订单接口偶发 504。查了半天发现是网关的限流把正常流量也误杀了——因为限流的 key 用了","c":null},{"h":"四、灰度、测试与拓扑","s":"网关天生适合做灰度：按 Header / 用户比例把一部分流量导到新版本服务，观察指标没问题再全量。","c":null}]},{"id":"fs-ch12/03-config-center","file":"03-config-center.md","title":"配置中心与动态配置：外置、隔离、热更新、密钥","kind":"flow","secs":[{"h":"一、外置、隔离、热更新与密钥","s":"外置的第一步，是停止在代码里写 const timeout = 3000 这种「看似常量、实则因环境而异」的东西。","c":{"lang":"text","code":"function makeService(config) {\n  return {\n    timeout: config.timeoutMs ?? 3000,   // 没传就用默认值，不报错\n    retries: config.retries ?? 0,\n    endpoint: config.endpoint,\n  };\n}"}},{"h":"二、陷阱、事故与回滚","s":"配置与代码分离的终极目标只有一个：让「部署什么代码」和「在什么环境下运行」成为两个可以","c":null},{"h":"三、开关、前端配置与边界","s":"功能开关是配置热更新的高频场景：新功能先对 1% 用户开放，没问题再放量。但开关会腐烂——功能","c":null},{"h":"四、治理与本地开发","s":"配置漂移指「我以为 A 环境和 B 环境一致，其实早就不一样了」。治理手段：用同一份配置模板按环境","c":null}]},{"id":"fs-ch12/04-snippets","file":"04-snippets.md","title":"fs-ch12 · 关键实现片段：网关路由与配置中心","kind":"flow","secs":[{"h":"1. 本节定位","s":"原则和代码之间是同一件事的两面。下面两段是 §2、§3 里反复提到的「路由匹配顺序」「配置默认值兜底」的最小可运行写法。","c":{"lang":"yaml","code":"spring:\n  cloud:\n    gateway:\n      routes:\n        - id: orders-specific\n          uri: lb://order-service\n          predicates:\n            - Path=/api/orders/**\n          filters:\n…"}}]}],"exams":[{"kind":"choice","q":"关于「什么时候该拆」，正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"只要团队技术上「想用微服务」，就应该立刻从单体拆开"},{"k":"B","t":"微服务能消灭系统复杂度，是单体演进的必然终态"},{"k":"C","t":"拆分的真实触发信号多来自组织与演进层面（部署耦合、多团队、伸缩不一致），而非技术潮流"},{"k":"D","t":"按技术分层（controller/service/dao）拆分，能得到清晰的微服务边界"}],"ans":"C","why":"拆分的回报来自部署耦合、团队踩脚、伸缩诉求不一致等组织/演进信号被满足；微服务把复杂度从代码内部搬到基础设施与协作上，并不消灭它。按技术层拆分只会得到「分布式单体」。所以 A、B、D 都错，C 正确。"},{"kind":"output","q":"读代码写输出（网关路由匹配）","stem":"js const routes = [ { prefix: \"/api/orders\", upstream: \"order-svc:8080\" }, { prefix: \"/api/pay\", upstream: \"payment-svc:8080\" }, { prefix: \"/api/users\", upstream: \"user-svc:8080\" }, ]; function route(…","opts":[],"ans":"order-svc:8080 payment-svc:8080 user-svc:8080 404-no-route","why":"路由按路径前缀匹配第一个命中的上游；都不命中返回 404-no-route。注意这里用 find 顺序匹配，因此前提路由表里没有「更宽泛的前缀写在前面」这种顺序 bug。"},{"kind":"fix","q":"改错：固定窗口限流的临界突变","stem":"下面的限流用「每分钟清零」的固定窗口，攻击者在两个窗口交界处可以瞬间突破限额。说明问题并改成令牌桶思路（允许平滑突发但限制总量）。 js class Limiter { constructor(limit) { this.limit = limit; this.count = 0; } allow() { if (this.count >= this.limit) return false; th…","opts":[],"ans":"class TokenBucket { constructor(capacity, refillPerSec) { this.capacity = capacity; // 桶容量（允许的最大突发） this.tokens = capacity; // 当前令牌数 this.refill = refillPerSec;…","why":"固定窗口在「窗口清零」瞬间会让「前一秒末 + 后一秒初」两个请求都通过，等于限额翻倍。令牌桶按时间平滑补充令牌，既允许一定突发（桶容量内），又把长时间速率限制在 refill 内，没有临界突变。生产中常用令牌桶/漏桶替代裸固定窗口。"},{"kind":"choice","q":"网关不应该承担的职责是","stem":"下列工作中，哪一项不该放在 API 网关？","opts":[{"k":"A","t":"统一校验请求身份（鉴权）并注入可信声明"},{"k":"B","t":"按路径把请求路由到对应上游服务"},{"k":"C","t":"具体的下单优惠计算与风控规则"},{"k":"D","t":"入口处统一打 traceId 与限流"}],"ans":"C","why":"网关应保持「薄」，只管横切且稳定的关注点（路由、鉴权身份、限流、traceId）。优惠计算、风控是易变的领域逻辑，放网关会让它变成无人敢改的胖单点，且每次业务变更都要动入口。所以 C 是不该放的。"},{"kind":"coding","q":"实现一个带优先级的网关路由匹配","stem":"实现 route(routes, path)，其中 routes 是 [{ match, svc, priority }] 数组。规则：精确路径（不以 / 结尾且无子路径）优先；否则取前缀匹配中 priority 最大的；都不命中返回 null。要求不用 any，并用三组数据自测：① /api/orders 在 [{match:'/api',svc:'a',priority:1},{match:'…","opts":[],"ans":"function route(routes, path) { let best = null; for (const r of routes) { const exact = r.match === path; const prefix = r.match !== '/' && path.startsWith(r.ma…","why":"要点：① 精确匹配（完全相等）优先级最高；② 前缀匹配要保证是「路径段边界」，即 path 在 match 长度处要么是结尾、要么是 /，避免 /api 误吞 /apix；③ 多个前缀命中时取 priority 最大。实现里用 best 跟踪最优，覆盖题目三组用例。"},{"kind":"output","q":"读代码写输出（配置热更新）","stem":"js class ConfigStore { constructor(initial) { this.data = { ...initial }; this.listeners = new Set(); } get(key) { return this.data[key]; } subscribe(fn) { this.listeners.add(fn); return () => this.li…","opts":[],"ans":"初始: false 热更新: {\"featureX\":true,\"rate\":10} 热更新: {\"featureX\":true,\"rate\":20} 最终: false","why":"初始 featureX 为 false；订阅者在每次 update 时收到合并后的完整 data 并打印；第二次 update 只改 rate，featureX 仍为 true；退订后第三次 update 不再触发打印；最终读取到 featureX=false。注意热更新不重启进程即可生效。"},{"kind":"coding","q":"实现 BFF 聚合：并发拉取并裁剪","stem":"实现 bffCart(userId, fetchers)，其中 fetchers 为 { user(id), cart(id), reco(id) }，每个返回 Promise。要求：用 Promise.all 并发拉取三个上游，把结果聚合为 { profile, items, suggest } 返回（仍为 Promise），并在 main 里用内存 fake fetchers 自测一组用户。强…","opts":[],"ans":"async function bffCart(userId, fetchers) { const [user, cart, recommendations] = await Promise.all([ fetchers.user(userId), fetchers.cart(userId), fetchers.reco…","why":"BFF 的价值是「前端一次请求拿全」：原本要并发拉三个服务，现在在 BFF 层用 Promise.all 聚合，返回前端友好的单一 payload。注意它只做编排与裁剪（profile/items/suggest 是字段挑选），不下单、不算优惠——那是订单服务的职责。"},{"kind":"choice","q":"关于密钥管理，正确的是","stem":"选择正确的做法。","opts":[{"k":"A","t":"为了方便，把 API Key 写在源码里并提交到 Git"},{"k":"B","t":"密钥经环境变量/密钥管理服务在运行时注入，日志中掩码，启动缺失则 fail-fast"},{"k":"C","t":"把密钥写进前端 bundle，前端直接调用第三方接口最方便"},{"k":"D","t":"密钥即使提交到 Git，事后删除提交记录即可彻底清除"}],"ans":"B","why":"Git 历史不可篡改，删除提交无法清除已泄露的密钥，补救只能旋转（rotate）。前端包任何人可反编译，绝不放密钥。正确做法是运行时注入、日志掩码、缺失即 fail-fast。A、C、D 都是典型事故来源。"}],"works":[{"h":"微服务炫技：还没到触发条件就拆","d":"错在：团队只有 3 个人、领域还在探索，就照着网上的架构图把系统拆成 8 个服务。 为什么：拆分的真实收益来自「组织/演进信号」被满足。在没有部署耦合、没有多团队踩脚、伸缩诉求一致时硬拆，只是把单体的复杂度搬到网络、一致性和运维上，开发效率反而下降。"},{"h":"按技术层拆而不是按限界上下文拆","d":"错在：拆出「用户-controller 服务」「用户-service 服务」「用户-dao 服务」，以为这就是微服务。 为什么：按技术分层拆只会产生「分布式单体」：跨层调用变成跨网络调用，事务和一致性全崩，却得不到任何独立性。拆分的单位是业务语义闭环，不是代码分层的物理位置。"},{"h":"把业务逻辑塞进网关","d":"错在：把优惠计算、风控规则、订单编排全写进 API 网关，理由是「都在入口统一处理方便」。 为什么：网关一旦承载业务逻辑，就变成没人敢改的胖单点，且每次业务变更都要动网关、重新发布入口。网关应当是薄的、稳定的横切层，业务规则是易变的纵向逻辑，二者耦合后系统退化为更难演进的形态。"},{"h":"网关限流用裸固定窗口导致临界突变","d":"错在：用「每分钟计数、到点清零」的固定窗口限流，以为这样就安全了。 为什么：在窗口边界处，两个相邻窗口各放一个请求，可以在瞬间突破限额（前一秒末 + 后一秒初），等于限流失效。这是固定窗口的经典缺陷，攻击者懂这个就能绕过。"},{"h":"路由匹配顺序错，宽泛前缀吞掉精确路径","d":"错在：路由表里 /api 写在 /api/orders 前面，结果所有订单请求都被 catch-all 接走。 为什么：前缀匹配一旦顺序不对，更具体的路由永远不会命中。这种 bug 在单测里很难发现，因为「大部分请求确实匹配到了某个上游」，只是不是你想要的那一个。"},{"h":"配置硬编码进镜像，环境切换靠改代码","d":"错在：把数据库地址、超时、密钥写成 const X = \"...\" 直接打进构建产物。 为什么：硬编码让同一份产物不能跨环境运行，每次换环境都要重新打包；更危险的是密钥被打进镜像后随仓库/制品分发，泄露面极大。这直接违反 12-Factor 的配置外置原则。"},{"h":"配置热更新没有默认值兜底，配置中心一抖全挂","d":"错在：实例启动时如果拿不到配置就直接抛错退出，没有任何默认值。 为什么：配置中心不是 100% 可用的。没有默认值兜底时，一次配置中心的短暂抖动就会让整批实例起不来，把「配置故障」放大成「全站不可用」。热更新本应提升韧性，反而成了单点。"},{"h":"密钥明文提交到 Git / 打进前端包","d":"错在：把 DB_PASSWORD、API_KEY 写在源码里提交，或写进前端 bundle 供「方便调用」。 为什么：Git 历史不可篡改，即使后来删除，历史提交里依然有明文；前端包更是任何人都能反编译拿到。这类泄露几乎必然导致真实的安全事件，且补救只能靠旋转密钥。"}],"asks":[{"q":"微服务到底解决了什么问题？它又引入了哪些新问题？","a":"它解决的是「组织与演进」层面的问题：独立部署、独立扩缩、团队自治、技术栈异构。但它把复杂度从代码内部搬到了基础设施和协作上——网络不可靠、分布式事务、数据一致性、可观测性、运维面扩大都是新增成本。所以拆分的净收益取决于你的组织是否真的被那些信号逼到了。","fu":["如果我告诉你「我们的单体没有任何部署耦合，也能独立扩缩」，你还建议拆吗？","分布式事务在微服务里一般怎么处理？两阶段提交为什么不流行？"],"tag":"通用"},{"q":"怎么划服务边界？限界上下文到底是什么？","a":"最小拆分单位是限界上下文：一段在语义上自洽、数据自己闭环、概念不跨边界泄漏的业务范围。识别判据是「哪些概念总是一起变」「哪些数据自己闭环」「同一个词在不同地方含义是否不同」。不要按技术分层（controller/service/dao）拆，那只会得到分布式单体。","fu":["康威定律在这里怎么起作用？","限界上下文之间怎么通信最稳？事件还是同步调用？"],"tag":"通用"},{"q":"API 网关应该管什么、不该管什么？","a":"该管横切且稳定的关注点：路由、鉴权（身份）、限流、TLS 终止、traceId、日志指标，以及为前端定制的 BFF 聚合。不该管易变的领域逻辑：优惠计算、风控、细粒度授权、数据持久化。判断标准一句话：换个业务需求就需要改网关的东西，就不该在网关里。","fu":["网关做鉴权和后端做授权，边界怎么划？","BFF 变胖了怎么办？它的职责上限在哪？"],"tag":"通用"},{"q":"配置为什么要外置？配置中心解决了什么？","a":"配置是随环境变但不该写死的值。外置让同一份产物跨环境运行、回滚更轻。配置中心进一步提供集中存储、版本化与回滚、监听推送实现热更新、按环境/集群灰度。但热更新必须配默认值兜底——配置中心挂了实例也要能靠默认值起来，绝不能「拿不到配置就启动失败」。","fu":["热更新没有默认值兜底会怎样？举一个真实事故形态。","密钥能不能放进配置中心？放进去要注意什么？"],"tag":"通用"}]},{"id":"fs-ch13","subj":"fullstack","title":"前端测试与质量门禁：测试金字塔、E2E、契约测试","summary":"测试不是写得越多越好，而是「在正确的层、用正确的替身、以正确的稳定性」覆盖正确的东西。本章讲清测试金字塔的分层比例与测试替身（stub/mock/fake/spy）的分工、E2E 与组件测试如何做稳（选择器策略、等待而非 sleep、不依赖…","concepts":[{"id":"fs-ch13/01-test-pyramid","file":"01-test-pyramid.md","title":"测试金字塔：分层策略与测试替身","kind":"compare","secs":[{"h":"一、分层与测试替身","s":"因为快，可以成千上万条，每次保存都跑。","c":{"lang":"text","code":"        /\\\n       /E2E\\        ← 少而慢：验端到端关键路径\n      /----\\\n     / 集成 \\       ← 中：模块协作、外部依赖\n    /------\\\n   / 单元   \\      ← 多而快：基底，占绝大多数\n  /----------\\\n  倒金字塔(反例)：E2E 一堆、单测没几个 → 一改就红、定位慢"}},{"h":"二、为什么会写歪，各层究竟测什么","s":"倒金字塔几乎都是「懒」出来的：E2E 用录制工具一键生成，看起来覆盖广、还贴近用户，于是越写越多；","c":null},{"h":"三、取舍、选型与门禁","s":"算法库、纯函数库几乎全是单测，没有 E2E 的必要；而一个强依赖第三方 UI 的表单应用，组件测试","c":null}]},{"id":"fs-ch13/02-e2e-and-component","file":"02-e2e-and-component.md","title":"E2E 与组件测试：稳定性与选择器策略","kind":"flow","secs":[{"h":"一、稳定的两条铁律","s":"最经典的 flaky 来源是 sleep(2000)：慢一点就超时，快一点又白等。正确做法是用「等待某个","c":{"lang":"text","code":"async function waitFor(predicate, { timeoutMs = 1000, intervalMs = 50 } = {}) {\n  const start = Date.now();\n  while (Date.now() - start < timeoutMs) {\n    if (predicate()) return true;\n    await new Promise((r) => setTimeout(r, intervalMs));\n  }\n  return false;\n}\n// 用法：等元素出现，而不是固定等 2 秒"}},{"h":"二、组件测试与测试卫生","s":"组件测试（Component Testing）在隔离的渲染环境里测单个组件，比 E2E 快一个量级（不用起整站、","c":null},{"h":"三、flaky 归因、工具差异与可观测","s":"某 E2E 偶发失败，CI 重跑就过，开发者习以为常。根因是测试里 await page.click('.btn') 在按钮","c":null},{"h":"四、环境、并行与可访问性","s":"移动端网络更差、设备碎片化，一次拉十个接口不现实，所以 BFF 聚合加少量 E2E 更关键。移动端 E2E","c":null}]},{"id":"fs-ch13/03-contract-and-gates","file":"03-contract-and-gates.md","title":"契约测试与质量门禁：消费者驱动契约与 CI 门禁","kind":"flow","secs":[{"h":"一、契约是什么、值在哪","s":"传统做法是「提供者定义接口，消费者被动适应」。CDC 反过来：消费者先写「我期望提供者返回什么」，","c":{"lang":"text","code":"// 消费者侧：声明我对 order-svc 的期望\nconst contract = {\n  consumer: \"web-frontend\",\n  provider: \"order-svc\",\n  interactions: [{\n    uponReceiving: \"获取订单\",\n    withRequest: { method: \"GET\", path: \"/orders/1\" },\n    willRespondWith: { status: 200, body: { id: 1, total: 99 } },\n  }],\n…"}},{"h":"二、门禁设计","s":"质量门禁是合并前的最后一道闸，把一组自动检查串起来，任一不过就红灯、禁止合并：","c":{"lang":"text","code":"function runGate(checks) {\n  const failed = checks.filter((c) => !c.run()).map((c) => c.name);\n  return failed.length === 0 ? \"GREEN\" : `RED: ${failed.join(\",\")}`;\n}"}},{"h":"三、Pact 工作流与契约演进","s":"消费者写测试，运行时 Pact 同时做两件事：验证消费者调用符合契约，并生成契约文件（JSON）。契约","c":null},{"h":"四、门禁落地与文化","s":"把契约验证放在门禁的靠后位置（在单测、构建之后），因为它依赖本地起提供者服务。提供者侧门禁","c":null}]},{"id":"fs-ch13/04-snippets","file":"04-snippets.md","title":"fs-ch13 · 关键实现片段：E2E、组件、契约与门禁","kind":"flow","secs":[{"h":"1. 本节定位","s":"测试的原则容易讲、难落地。下面四段是 §1~§3 各自最容易写错处的对照实现。","c":{"lang":"ts","code":"// 错误：await page.waitForTimeout(2000);\n// 正确：断言针对不变量自动重试\nawait expect(page.getByRole('button', { name: '提交' })).toBeEnabled();\nawait page.getByTestId('order-total').waitFor({ state: 'visible' });\nconst total = await page.getByTestId('order-total').textContent();\nexpect(Number(total)).toBeGreaterThan(0);"}}]}],"exams":[{"kind":"choice","q":"测试金字塔的健康比例是","stem":"关于测试分层比例，最符合「金字塔」原则的是","opts":[{"k":"A","t":"单元测试最少，E2E 最多（冰淇淋锥）"},{"k":"B","t":"单元:集成:E2E 大致 70:20:10"},{"k":"C","t":"三层各占三分之一，均匀用力"},{"k":"D","t":"只写 E2E，因为最贴近用户最可靠"}],"ans":"B","why":"金字塔强调底层单测多而快、顶层 E2E 少而关键，经验比例约 70/20/10。A 是反模式（慢且 flaky），C 没有体现反馈速度差异，D 忽视单测的速度与隔离价值。"},{"kind":"output","q":"读代码写输出（四类测试替身行为）","stem":"js // Stub：返回预设值 function getUser(id, db) { const row = db.query('users', [id]); return row ? { id, name: row.name.toUpperCase() } : null; } const stubDb = { query(_s, [id]) { return id === 1 ? { name…","opts":[],"ans":"{\"id\":1,\"name\":\"MIMI\"} null 5 9 [[2,3],[4,5]]","why":"Stub 给 getUser 预设了数据库查询结果，id=1 返回 name、id=2 返回 null；Spy 包裹 add 后如实放行计算（5、9）并记录每次调用的参数 [[2,3],[4,5]]。注意 Stub 是假的、Spy 是透明的。"},{"kind":"fix","q":"改错：固定 sleep 导致的偶发失败","stem":"下面的 E2E 用 sleep(2000) 等元素出现，经常偶发超时。改成「等待条件成立」的稳定写法。 js async function checkLoaded(page) { await sleep(2000); return page.isVisible('.submit-btn'); }","opts":[],"ans":"async function waitFor(predicate, { timeoutMs = 1000, intervalMs = 50 } = {}) { const start = Date.now(); while (Date.now() - start < timeoutMs) { if (predicate…","why":"固定 sleep 假设了确定时序，慢一点就超时、快一点又白等。改成轮询 waitFor：在超时窗口内反复检查条件是否成立，对异步渲染的非确定性有容忍度，既不误判也不空等。这是消除 E2E flaky 的第一招。"},{"kind":"choice","q":"关于消费者驱动契约（CDC），正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"由提供者定义接口，消费者被动适应，提供者改了消费者自然跟上"},{"k":"B","t":"消费者先写「我期望提供者返回什么」生成契约，提供者在自己 CI 重放验证"},{"k":"C","t":"契约测试需要拉起所有微服务做全链路联调才能跑"},{"k":"D","t":"契约只校验状态码即可，字段细节不重要"}],"ans":"B","why":"CDC 反转了传统方向：消费者声明期望并生成契约，提供者在自身 CI 重放，破坏性改动当场红，不用等联调/生产。契约测试各自独立跑、不需拉起全部依赖（C 错）；契约必须校验关键字段类型与存在性，只认状态码会漏掉字段级破坏（D 错）。"},{"kind":"coding","q":"实现一个 Spy：包裹真实函数并记录调用","stem":"实现 makeSpy(target, method)，返回同一个 target，但 target[method] 被包裹：调用时如实放行原逻辑并把参数记录到 target[method].calls。要求：① 不破坏原返回值；② calls 是数组，记录每次调用的参数数组；③ 不用 any。用 calc.add 自测两组调用并打印 calls。","opts":[],"ans":"function makeSpy(target, method) { const orig = target[method]; const calls = []; target[method] = function (...args) { calls.push(args); return orig.apply(this…","why":"Spy 与 Stub/Mock 的关键区别是「透明」：它调用真实 orig 并 apply 原 this，不篡改行为，只额外记账。calls 记录每次参数数组，便于事后统计调用次数与入参。断言里 orig.apply(this, args) 保证返回值与副作用都不变。"},{"kind":"output","q":"读代码写输出（质量门禁）","stem":"js function runGate(checks) { const failed = checks.filter((c) => !c.run()).map((c) => c.name); return failed.length === 0 ? 'GREEN' : RED: ${failed.join(',')}; } const gate = runGate([ { name: 'lint'…","opts":[],"ans":"GREEN RED: lint,coverage","why":"第一个门禁四项全过，返回 GREEN；第二个门禁里 lint 返回 false、coverage 的 70>=80 为 false，二者进入失败列表，返回 RED: lint,coverage。门禁的本质就是把一组自动检查串起来，任一不过即红灯禁合并。"},{"kind":"coding","q":"实现契约验证：提供者重放消费者契约","stem":"实现 verifyProvider(contract, handler)：对契约里每个 interaction，用 handler(it.withRequest) 取得真实响应，校验 actual.status === it.willRespondWith.status 且 actual.body.id === it.willRespondWith.body.id，返回 [{ path, ok }…","opts":[],"ans":"function verifyProvider(contract, handler) { return contract.interactions.map((it) => { const actual = handler(it.withRequest); const ok = actual.status === it.…","why":"契约验证的核心是「用真实 handler 重放契约请求，比对关键字段」。good 提供者 id 类型与值都匹配，ok 为 true；broken 把 id 从数字改成字符串，类型不一致，ok 为 false——这正是 CDC 要在提供者 CI 里拦下的「字段级破坏」。注意校验的是 body.id 而非整个 body，避免把无关字段变化误判为破坏。"},{"kind":"choice","q":"E2E 选择器策略，最稳定的是","stem":"为了降低测试对 UI 变更的敏感度，定位元素应优先使用","opts":[{"k":"A","t":"深层 CSS 路径如 #app > div:nth-child(2) .btn"},{"k":"B","t":"基于视觉位置的 class 与嵌套层级"},{"k":"C","t":"专门为测试打的 data-testid 标记"},{"k":"D","t":"随文案变化的文本精确匹配"}],"ans":"C","why":"data-testid 与样式、文案、DOM 层级完全解耦，UI 怎么改只要测试标记不动测试就不红，最稳。CSS 路径与层级（A、B）绑死实现细节，文案（D）易变，都不如 data-testid 稳定。"}],"works":[{"h":"倒金字塔：E2E 写得比单测还多","d":"错在：项目里 E2E 上百条，单测寥寥，每次 CI 跑半小时还经常红。 为什么：E2E 慢且易 flaky，占比过高会拖垮反馈速度，开发者开始忽略红灯，门禁形同虚设。金字塔失衡是测试效能崩塌的起点。"},{"h":"用固定 sleep 等待异步","d":"错在：测试里写 await sleep(2000) 再断言，理由是「等它渲染完」。 为什么：sleep 假设了确定的时序，而真实系统异步非确定：慢一点就超时失败，快一点又白等，产生偶发红。这是 E2E flaky 的头号来源。"},{"h":"选择器绑死 DOM 细节","d":"错在：用 #app > div:nth-child(2) .btn-primary 这种层级/CSS 选择器定位元素。 为什么：这类选择器与样式、嵌套、class 命名强耦合，设计师改一处结构测试就全红。测试维护成本被转嫁成了「UI 一动就修测试」。"},{"h":"过度 Mock：测试绑死了实现细节","d":"错在：Mock 了「这个方法被调用了 3 次、传了这些参数」，一旦重构内部实现测试就红。 为什么：Mock 验证的是「调用方式」而非「行为结果」。当实现合理重构（方法拆分、调用顺序调整）时，测试红但功能没坏——测试反而阻碍了演进。"},{"h":"只写单测、忽略集成","d":"错在：单测覆盖率高高在上，但没人写跨组件协作的集成测试。 为什么：单测彼此隔离，恰恰会漏掉「A 的输出格式 B 接不住」「字段名对不上」这类协作错误。单测全绿线上照样炸。"},{"h":"测实现细节而非用户行为","d":"错在：组件测试里直接读 component.state.xxx 或调用私有方法断言。 为什么：实现细节测试在重构内部时必红，而功能没变。测试本应保护行为，结果变成了「禁止改内部」的枷锁，开发体验极差。"},{"h":"契约只测 happy path，破坏字段被漏掉","d":"错在：契约只声明「返回 200 且有个 id」，提供者把 total 字段删了也没人发现。 为什么：契约如果只校验状态码和最粗的字段，提供者的字段级破坏性改动（改类型、删字段）不会被捕获，等到消费者真正用到那个字段才在生产爆。"},{"h":"覆盖率门禁设太高逼出无意义测试","d":"错在：覆盖率要求 100%，开发者为了达标写 expect(true).toBe(true) 这类空断言。 为什么：把覆盖率当唯一 KPI，会诱发「为覆盖而覆盖」的表演式测试：行被执行但没有任何断言价值，反而给「质量很好」的虚假安全感。"}],"asks":[{"q":"测试金字塔为什么是那个形状？比例失衡会怎样？","a":"金字塔是「反馈速度 vs 覆盖保真度」的折中：底层单测快但用替身保真低，顶层 E2E 慢但真环境保真高。比例失衡最典型是倒金字塔——E2E 写太多，CI 跑半小时还 flaky，开发者开始忽略红灯，门禁形同虚设。所以单测要多而快，E2E 少而关键。","fu":["如果项目几乎没有 E2E，只靠单测+集成，风险在哪？","组件测试在金字塔里算哪一层？它解决了什么？"],"tag":"通用"},{"q":"Stub、Mock、Fake、Spy 到底怎么区分？","a":"Stub 返回预设数据，是假的；Mock 在替掉行为的同时断言「有没有被按预期调用」，也是假的；Fake 是一个轻量但真实的实现（内存数据库），能跑完整链路；Spy 包裹真实对象，如实放行并记账（记录调用）。选型核心：我只想给数据用 Stub，想验调用用 Mock，想跑全链路不连真库用 Fake，想统计真实调用用 Spy。","fu":["过度使用 Mock 有什么代价？","Fake 和真实实现会不会行为不一致？怎么控制？"],"tag":"通用"},{"q":"前端 E2E 怎么做到不 flaky？","a":"三件事：① 等待条件成立（web-first 断言自动重试 / 自己写 waitFor），绝不用固定 sleep 假设时序；② 选择器绑契约不绑 DOM（data-testid / role / text），拒绝 CSS 路径；③ 测试数据自立自灭，每个用例建自己的数据并清理，不依赖上一条用例的状态。再给测试用独立环境，避免共享状态飘结果。","fu":["sleep 为什么比 waitFor 更糟？给一个时序反例。","data-testid 会不会污染生产 DOM？怎么取舍？"],"tag":"通用"},{"q":"微服务之间怎么保证接口不被单方面破坏？","a":"用消费者驱动契约（CDC，如 Pact）：消费者先声明「我期望提供者返回什么」生成契约，提供者在自己 CI 重放这份契约，任何破坏性改动（字段类型变、字段删）当场红灯，不用等联调或生产才爆。它补上的是金字塔里 E2E 太贵、单测看不见的「跨服务接口」那段空白，且不需要拉起全部依赖。","fu":["契约只校验状态码够吗？为什么关键字段也要验？","CDC 和 schema 演进（版本化 API）是什么关系？"],"tag":"通用"}]},{"id":"fs-ch14","subj":"fullstack","title":"Agent × 全栈工程接缝：流式、长任务、幂等与成本","summary":"Agent 不是一段函数调用，而是一条横跨网关、后端、模型与工具的长链路。本章把「工程接缝」讲透：流式响应如何安全地穿过网关（SSE/WebSocket、透传而非缓冲、背压、超时与取消）；长任务如何用任务 id 实现断线重连与幂等恢复；工具…","concepts":[{"id":"fs-ch14/01-streaming-through-gateway","file":"01-streaming-through-gateway.md","title":"流式响应穿过网关：透传、背压与取消","kind":"flow","secs":[{"h":"SSE 与 WebSocket 在协","s":"议层的本质差异","c":{"lang":"text","code":"   Agent ──SSE 分块──▶ Gateway ──SSE 分块──▶ 浏览器\n     ▲   (cancel)         ▲   (cancel)\n     └─────────────────────┘   断线重连用 last-event-id 续传\n   网关只透传流，不缓冲整段；背压从下游往上游反压"}},{"h":"网关透传流式的三种实现路径","s":"第一种，也是生产里最推荐的一种：让网关做「字节级透传」。网关不解析 body，只把上游的","c":null},{"h":"背压：流式系统最容易被忽视的失效模式","s":"背压（backpressure）指的是「消费者处理得比生产者慢」时，数据往哪里堆的问题。在一段流式链路里，","c":null},{"h":"超时分级与取消传播","s":"流式请求必须有分级超时：连接超时（多久没连上上游）、首字节超时（多久没收到第一块，","c":null},{"h":"一段最小可运行的透传骨架","s":"下面的示例用 fetch 的 ReadableStream 模拟「后端逐块产生、网关逐块转发、客户端逐块拼接」","c":null},{"h":"工程落地时的几个决策点","s":"把流式接进真实网关，还要回答几个具体问题。第一，网关软件本身要支持流式：用 Nginx 做反向代理时，必须确保没有开启响应缓冲（应把 proxy_buffering 设为 off），否则响应会被攒齐再发；用 Node 自研网关时，res…","c":{"lang":"js","code":"async function* backend() {\n  for (const t of [\"思考中…\", \"检索知识库\", \"生成：你好\", \"，我是助手\"]) {\n    await new Promise(r => setTimeout(r, 5));\n    yield `data: ${t}\\n\\n`;\n  }\n}\nasync function gateway(src, sink) {\n  for await (const chunk of src) sink.push(chunk); // 收到一块立刻转发一块\n}"}}]},{"id":"fs-ch14/02-long-task-state-and-reconnect","file":"02-long-task-state-and-reconnect.md","title":"长任务状态与断线重连：任务 id、幂等与进度持久化","kind":"timeline","secs":[{"h":"为什么不能一直占着连接","s":"任何一跳的超时都会让「挂起式」请求前功尽弃：用户看到的是白屏或报错，而服务端可能还在跑，","c":null},{"h":"任务 id 与状态机","s":"每个长任务都要有一个全局唯一、可排序、且不泄露业务信息的 id。工程上常用 ULID 或带前缀的","c":{"lang":"js","code":"// 只允许这几条迁移，其余一律拒绝\nconst NEXT = {\n  queued:    [\"running\", \"failed\"],\n  running:   [\"succeeded\", \"failed\"],\n  succeeded: [],\n  failed:    [],\n};\n\nasync function advance(db, taskId, to) {\n…"}},{"h":"轮询还是订阅","s":"客户端想知道进度，有两种主流方式。轮询（polling） 最简单：客户端每隔几秒 GET /task/:id，","c":null},{"h":"断线重连用 last-event-id / cursor","s":"无论轮询还是订阅，客户端都可能中途掉线。重连的关键是「记住自己上次到哪了」：订阅场景里是","c":null},{"h":"幂等恢复：同一个 id 可以重入","s":"「幂等恢复」指：用同一个任务 id 重新发起「查询/续跑」，结果一致且不会产生第二个任务。实现上，","c":null},{"h":"进度持久化","s":"进度不能只在内存里 progress = 50 这样飘着。每个可恢复的检查点都要写库（或 Redis），","c":null},{"h":"工程落地时的几个决策点","s":"把长任务做成可恢复，最常见的新手错误是「用一个内存里的 Map 存任务」。它能在单机开发期跑通，但一上生产就暴露三个问题：进程重启（发布、OOM、崩溃）会让所有进行中的任务消失；水平扩容后请求被负载均衡到另一个实例，那个实例根本不知道这…","c":null}]},{"id":"fs-ch14/03-tool-call-idempotency-and-audit","file":"03-tool-call-idempotency-and-audit.md","title":"工具调用的幂等与审计：唯一 id、重试幂等与不可篡改日志","kind":"timeline","secs":[{"h":"每次工具调用都要有唯一 id","s":"每个工具调用在被发起时就应该分配一个 callId（而不是等返回了才编号）。这个 id 跟着这次调用","c":{"lang":"text","code":"   tool call ──callId=abc──▶ 去重表 ──首次──▶ 真正执行 → 结果\n      (重试)   callId=abc ──▶ 去重表 ──命中──▶ 直接返回已存结果\n   审计日志：callId + 输入哈希 + 输出哈希 → 哈希链，篡改即可检出"}},{"h":"重试幂等：同一个 callId 只执行一次","s":"网络是不可靠的，重试不可避免。但盲目重试会让「发邮件」「扣库存」这类有副作用的操作被执行多次。","c":null},{"h":"审计日志为什么必须不可篡改","s":"审计日志要回答四个问题：谁（who）、何时（when）、调了什么（what）、参数与结果是什么","c":null},{"h":"用哈希链实现 tamper-evident","s":"最轻量的不可篡改方案是哈希链（hash chain）：每条审计记录除了自身内容，还记下「上一条","c":null},{"h":"审计与合规的边界","s":"审计日志本身也可能含敏感信息（参数里可能有手机号、身份证）。所以「不可篡改」要和「最小可见」","c":null},{"h":"工程落地时的几个决策点","s":"工具幂等在工程上最容易被低估的，是「重试到底来自哪里」。一个工具调用被重复执行，往往不是你主动重试，而是系统自动：网关的超时重试、消息队列的 at-least-once 投递、前端的「重复点击」、以及补偿任务（scheduler）的重新…","c":null}]},{"id":"fs-ch14/04-cost-and-rate-limiting","file":"04-cost-and-rate-limiting.md","title":"成本与限流：token 计量、租户限流与降级预算","kind":"flow","secs":[{"h":"token 计量：输入与输出分开算","s":"一次模型调用的花费 = 输入 token 数 × 输入单价 + 输出 token 数 × 输出单价。计量要做到「每次","c":null},{"h":"按用户 / 租户限流的维度","s":"限流要分维度：单用户（防单人刷）、单租户（多租户 SaaS 里隔离彼此）、全局（保护上游模型配额）。","c":null},{"h":"三种经典限流算法","s":"（桶里有存量）。漏桶（leaky bucket）：请求进桶、以固定速率漏出，强制平滑输出、不允许突发。","c":{"lang":"js","code":"// 容量 capacity，每秒补 refillPerSec 个令牌\nclass TokenBucket {\n  constructor(capacity, refillPerSec) {\n    this.capacity = capacity;\n    this.rate = refillPerSec;\n    this.tokens = capacity;\n    this.last = Date.now();\n  }\n\n…"}},{"h":"降级与预算：把「省钱的开关」做成显式的","s":"当预算快超支，或上游模型变慢/报错，要有明确的降级（degradation）策略，而不是硬扛到失败：","c":null},{"h":"成本可见性也是产品能力","s":"把「本次调用花费」「本月已用额度」返给开发者和终端用户，能反向促使大家写更省的 prompt、做更","c":null},{"h":"工程落地时的几个决策点","s":"限流放在哪一层，决定了它有多省。最外层（入口网关/CDN）做限流，能在流量还没进后端时就拦下，省的是「后端算力 + 模型配额」；最内层（具体工具调用前）做限流，只能保护那一个环节，但能做到「按具体动作维度」。实务上要分层：网关层做「粗粒…","c":null}]},{"id":"fs-ch14/05-agent-snippets","file":"05-agent-snippets.md","title":"fs-ch14 · Agent × 全栈接缝实战片段","kind":"flow","secs":[{"h":"流式响应（SSE 透传）","s":"","c":{"lang":"ts","code":"app.get('/chat/stream', async (req, res) => {\n  res.setHeader('Content-Type', 'text/event-stream')\n  const stream = await llm.chat(req.body, { stream: true })\n  for await (const chunk of stream) {\n    res.write(`data: ${JSON.stringify(chunk)}\\n\\n`)\n  }\n  res.end()\n})"}},{"h":"长任务状态机与重连","s":"","c":{"lang":"ts","code":"type TaskState = 'queued' | 'running' | 'done' | 'failed'\nconst states: Record<string, TaskState> = {}\n// 客户端断线重连用 taskId 拉取最新 state，而非重启任务\napp.get('/task/:id', (req, res) => res.json({ state: states[req.params.id] }))"}},{"h":"tool_call 幂等键","s":"","c":{"lang":"ts","code":"async function callTool(name: string, args: any, idempotencyKey: string) {\n  const cached = await kv.get(idempotencyKey)\n  if (cached) return cached            // 同一 key 直接返回，防重复执行\n  const r = await tools[name](args)\n  await kv.set(idempotencyKey, r, { ttl: 3600 })\n  return r\n}"}},{"h":"审计日志落库","s":"","c":{"lang":"ts","code":"await audit.insert({\n  tool: name, args, result: r, userId, ts: Date.now(), key: idempotencyKey,\n})\n// 审计与业务结果分离存储，便于事后对账与追责"}},{"h":"成本与限流中间件","s":"","c":{"lang":"ts","code":"app.use(async (req, res, next) => {\n  const cost = estimateTokens(req.body)\n  if (await budget.exceeded(req.user, cost)) return res.status(429).json({ error: 'budget' })\n  await budget.consume(req.user, cost)\n  next()\n})"}},{"h":"降级开关热更新","s":"","c":{"lang":"ts","code":"const flags = { queue: true, cacheFallback: false, reject: false }\nconfig.watch('agent.flags', (v) => Object.assign(flags, v))  // 阈值可热更新，免发版"}},{"h":"背压与排队","s":"当并发任务超过 worker 数，用有界队列 + 信号量限流，避免内存被无限堆积的流式缓冲撑爆。","c":null},{"h":"断点续传 chunk 恢复","s":"长任务分段落盘，客户端用 fromChunk 续传；中断后从最后成功段继续，而非从头。","c":null},{"h":"多租户隔离","s":"每个租户独立预算、独立 idempotency 命名空间、独立审计表；跨租户共享 worker 但数据不串。","c":null},{"h":"错误分类与重试预算","s":"区分「可重试」（超时/5xx/限流）与「不可重试」（4xx 参数错）；每次调用消耗重试预算，预算耗尽走降级而非无限重试。","c":null},{"h":"🧑‍💻 程序员视角","s":"SSE 透传 LLM 流式响应时，要注意「逐块转发而非缓冲」：中间层若开了 compression 或缓冲，用户会看到「卡很久然后一次性出完」。长任务要设计状态机 + 断线重连：客户端带 task_id 重连，服务端从断点续推，而不是从…","c":null},{"h":"🎓 博士生视角","s":"Agent 与前端的接缝本质是「不确定性的后端 + 有状态的前端」，其核心挑战是「可观测性与可恢复性」。流式协议（SSE）天然单向，双向交互需 WebSocket 或「SSE + 独立 POST」，后者更易穿过代理与网关。工具调用的幂等…","c":null},{"h":"📚 考研者视角","s":"AI 应用/全栈面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"关于流式穿过网关，正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"网关应在中间件里 await response.text() 把流读光再返回，这样最稳定"},{"k":"B","t":"网关应做字节级透传，收到一块立刻转发一块，避免缓冲整条响应"},{"k":"C","t":"SSE 需要像 WebSocket 一样独立握手一条全双工长连接"},{"k":"D","t":"流式请求只要设一个整体超时即可，不需要首字节超时"}],"ans":"B","why":"流式网关的核心是「透传而非缓冲」：用 for await (chunk) 逐块转发，否则首字节延迟极高且内存随流增长。A 正是反面教材；SSE 复用普通 HTTP、无需独立握手（C 错）；首字节超时用于快速暴露上游无产出，不能省（D 错）。"},{"kind":"output","q":"读代码写输出（流式透传块数）","stem":"下面这段模拟「后端逐块产生、网关透传、客户端拼接」的代码，输出是什么？ js async function backend() { for (const t of [\"思考中…\", \"检索知识库\", \"生成：你好\", \"，我是助手\"]) { await new Promise(r => setTimeout(r, 5)); yield data: ${t}\\n\\n; } } async funct…","opts":[],"ans":"转发块数: 4 客户端拼接: 思考中…检索知识库生成：你好，我是助手","why":"后端 yield 出 4 块，网关逐块 push 不聚合，所以 out.length 为 4。SSE 以空行 \\n\\n 分隔，split 后每块去掉 data: 前缀再拼接，得到完整文本。注意 events.join(\"\") 是把四段直接连起来，没有分隔符。"},{"kind":"fix","q":"改错：为什么这个长任务断线后会重复执行","stem":"下面的「创建任务」实现，在客户端断网重连时会新建第二个任务，导致同一个业务被跑两遍。指出问题并改正。 js async function createTask(userId, docId) { // 每次请求都新建一个 task，没有幂等键 const id = \"task_\" + Math.random().toString(36).slice(2); await db.insert({ id,…","opts":[],"ans":"async function createTask(userId, docId) { const idemKey = ${userId}:${docId}; // 业务幂等键 const existing = await db.findByKey(idemKey); if (existing) return exist…","why":"问题在「每次请求都新建任务」，断线重连等于再提交一次，于是同一份文档被两个任务各跑一遍。修法是用 (userId, docId) 这类业务键做幂等键：重复创建时先查，命中就返回已有任务 id，从而保证「同一业务只有一个任务、可重入」。"},{"kind":"coding","q":"实现工具调用的重试幂等","stem":"实现 callTool(callId, op)：用全局 Map 以 callId 为键缓存执行结果；同一 callId 第二次调用直接返回首次结果（标记 retried:true），不重复执行。要求：① 用一个计数器记录「真实执行次数」；② 不同 callId 各自独立执行；③ 在 main 里自测：同 id 调两次、不同 id 调一次，打印执行次数应为 2。","opts":[],"ans":"const log = new Map(); let execCount = 0; function callTool(callId, op) { if (log.has(callId)) return { out: log.get(callId), retried: true }; execCount++; cons…","why":"幂等的核心是「以 callId 为键去重」。第一次见到该 id 才真正执行并把结果存入 Map；之后见到同一 id 直接返回缓存结果，并把 retried 标 true。计数器只在「真正执行」分支自增，因此同 id 重试不会让它增长——这正是「至少一次投递变精确一次效果」的最小实现。"},{"kind":"choice","q":"令牌桶与漏桶的区别","stem":"关于令牌桶（token bucket）与漏桶（leaky bucket），正确的是","opts":[{"k":"A","t":"两者都强制恒定输出速率，不允许任何突发"},{"k":"B","t":"令牌桶允许短时突发（桶内有存量时），漏桶强制平滑输出"},{"k":"C","t":"漏桶允许短时突发，令牌桶强制平滑"},{"k":"D","t":"两者没有区别，只是名字不同"}],"ans":"B","why":"令牌桶以固定速率加令牌，请求取令牌，桶里有存量时允许短时突发；漏桶以固定速率漏出，强制输出平滑、不允许突发。API 限流通常选令牌桶（容忍突发），保护下游数据库时才用漏桶（强制平滑）。"},{"kind":"output","q":"读代码写输出（租户令牌桶限流）","stem":"js function makeBucket(rate, cap) { let tokens = cap; return { tick(seconds) { tokens = Math.min(cap, tokens + rate seconds); }, allow(n = 1) { if (tokens >= n) { tokens -= n; return true; } return fa…","opts":[],"ans":"初始允许3? true 再允许4? false tick1s后允许4? true tick10s后剩余(上限5): 5","why":"初始令牌 5，allow(3) 成功剩 2；allow(4) 不够失败；tick(1) 补 2 → 4，allow(4) 成功剩 0；tick(10) 补 20 但受 cap=5 限制，剩余 5。这演示了令牌桶「允许突发 + 上限封顶」的特性。"},{"kind":"coding","q":"实现断线重连的事件补发","stem":"服务端有一串有序事件 [\"e1\",\"e2\",\"e3\",\"e4\",\"e5\"]。实现 serve(fromIdx)，只返回 events.slice(fromIdx)（即「上次游标之后」的事件）。模拟：客户端首次收到前 3 条后在 e3 断开（idx=2），重连时调用 serve(idx+1) 续传。打印首次收到、重连续传、去重后的总条数（应为 5）。","opts":[],"ans":"const events = [\"e1\", \"e2\", \"e3\", \"e4\", \"e5\"]; function serve(fromIdx) { return events.slice(fromIdx); } let idx = 0; const first = serve(idx); idx = 2; // 只处理到…","why":"断线重连的关键是「记住游标并从游标之后补发」。首次拿到前 3 条后把游标记为 2（e3 的下标），重连传 idx+1=3，slice(3) 只返回 e4、e5。客户端把首批与续传做去重合并，总条数不变仍是 5——既不少（漏）也不多（重）。"},{"kind":"fix","q":"改错：审计日志为什么能被偷偷篡改","stem":"下面的审计记录方式，事后无法发现某条记录被改过。指出问题并改正。 js function appendAudit(entry) { fs.appendFileSync(\"audit.log\", JSON.stringify(entry) + \"\\n\"); // 明文追加，无完整性校验 }","opts":[],"ans":"const crypto = require(\"crypto\"); function h(s) { return crypto.createHash(\"sha256\").update(s).digest(\"hex\"); } const chain = []; function appendAudit(entry) {…","why":"明文追加的日志，谁都能改且改完看不出来。改用哈希链：每条记录除自身内容外，还存「上一条记录的哈希」，本记录哈希 = hash(上一条哈希 || 本记录)。任何一条被改，它的哈希就对不上，且后续每条都引用前一条，篡改会向后传播，定时 verify() 即可检出。"}],"works":[{"h":"网关把流读光再返回，流式体验消失","d":"错在：在网关/中间件里写了 const body = await response.text() 或类似 collect()，再一次性转发。 为什么：流式接口被中途「收齐」，用户看到的是「长时间白屏后全文瞬间出现」，首字节延迟极高；同时网关要缓存整条响应的内存，长流直接 OOM。"},{"h":"流式请求没有首字节超时，上游挂了前端一直转","d":"错在：只设了整体超时（如 60s），没设首字节（TTFB）超时。 为什么：模型服务起不来或卡死时，第一条数据迟迟不到，用户面对无限转圈；整体超时太长，资源被空占。"},{"h":"用户关页面后还在烧 token（取消没传播）","d":"错在：前端断开后，后端和模型推理没收到取消信号，继续把整段回答生成完。 为什么：为「已经没人看」的请求持续付费，且占用模型并发配额，挤占真实请求；成本审计里出现大量「无人消费」的调用。"},{"h":"长任务占着连接跑几分钟，任一超时即前功尽弃","d":"错在：把需要几分钟的任务做成「同步挂起」接口，指望网关/浏览器/LB 都不超时。 为什么：任意一跳的空闲超时都会断掉连接，用户看到报错，但服务端可能还在跑，形成「双盲」；发布重启直接丢失进度。"},{"h":"断线重连用全量重发，造成重复与浪费","d":"错在：客户端掉线后不记游标，重连就从头订阅/重新拉取全部历史事件。 为什么：用户看到重复内容、重复通知；服务端白白重算一遍，长任务场景尤其浪费。"},{"h":"工具调用重试不做幂等，副作用被执行多次","d":"错在：网络抖动后对「发邮件 / 扣库存 / 改订单」这类调用直接重试，没带幂等键。 为什么：重试十次可能真的发了十封邮件、扣了十次库存；这是资损级 bug，且往往在压测/弱网下才暴露。"},{"h":"把审计日志当普通日志，可被悄悄篡改","d":"错在：审计信息写进和业务日志同一个、可被运维随意改写的文件/表，且没有完整性校验。 为什么：出事后查不清责任，甚至日志被涂改导致无法追责；合规审计直接不通过。"},{"h":"成本只在月底看总账单，没有单次计量","d":"错在：只在调用入口记「调了一次模型」，不记录 model / 输入输出 token / 单次花费。 为什么：无法定位「哪类请求最贵」「哪个租户超支」，预算烧穿才发现；也没法给用户展示花费。"}],"asks":[{"q":"Agent 的流式响应要怎么安全地穿过你们的网关？","a":"网关必须做字节级透传，而不是把流读光再返回：用 fetch 的 ReadableStream 或反向代理的 chunked 转发，收到一块立刻往下写。同时要配三级超时（连接/首字节/整体），并用 AbortController 把客户端的取消信号一路传到模型调用，避免为无人观看的请求持续烧 token。背压也要向上游传播，别手写无界缓冲。","fu":["如果网关是 Nginx，需要改哪些配置才能透传 SSE？","首字节超时应设多少，依据是什么？"],"tag":"通用"},{"q":"长任务为什么不能一直占着连接？断线重连怎么做？","a":"任何一跳的空闲超时都会让挂起式请求前功尽弃，且进程重启会丢进度。正确做法是「创建任务返回 id → 轮询/SSE 查状态 → 取结果」三段式，状态机（queued/running/succeeded/failed）落库、进度写检查点。断线重连用 Last-Event-ID 或进度游标，服务端只补发游标之后的事件，客户端按事件 id 去重合并。","fu":["任务 id 为什么不用自增整形而用 ULID/UUID？","轮询和 SSE 订阅怎么共存而不维护两套真相？"],"tag":"通用"},{"q":"工具调用的重试怎么保证不重复执行副作用？","a":"每次工具调用发起时就分配 callId，把它作为幂等键。执行前先查这个 id 是否已执行过，执行过直接返回那次结果，没执行过才真正跑并把结果按 id 缓存。这样网络抖动导致的十次重试，实际只执行一次——这是「至少一次投递」通过幂等键变成「精确一次效果」的标准做法。","fu":["幂等键应该落在哪个维度，为什么不能只靠请求去重？","如果执行到一半进程崩了，callId 缓存还没写怎么办？"],"tag":"通用"},{"q":"审计日志为什么必须不可篡改？怎么做到？","a":"审计日志要能事后追责，普通业务日志丢了能补，审计日志被改就失去证据价值。不可篡改指「任何改动都能被检出」，不是「谁都改不了」。最轻量是哈希链：每条记录引用上一条的哈希，本记录哈希 = hash(上一条哈希 || 本记录)，改动会向后传播、定时校验即可发现。再严肃可上 WORM 或区块链锚定。同时注意高敏参数脱敏，完整性 ≠ 机密性。","fu":["哈希链如果被改了中间一条，校验能定位到第几条吗？","WORM 存储和哈希链各自的代价是什么？"],"tag":"通用"}]},{"id":"fs-ch15","subj":"fullstack","title":"Go + Gin 后端：并发模型、接口契约与 Java 路线对照","summary":"Go 是后端 Agent 服务的常见底座。本章用「和 Java 对照」的线索讲清：Goroutine 与 Channel 的并发模型（GMP 调度、channel 作为同步原语、「不要通过共享内存通信」）；Gin 的路由树、中间件链与 Co…","concepts":[{"id":"fs-ch15/01-goroutine-and-channel","file":"01-goroutine-and-channel.md","title":"Goroutine 与 Channel：轻量并发与「不要通过共享内存通信」","kind":"stack","secs":[{"h":"一、模型本体：goroutine 与 channel","s":"操作系统线程（如 Java 的 Thread）默认栈就有 1MB 左右，开几万个就内存爆炸；Goroutine 初始","c":{"lang":"text","code":"   G(goroutine) ─▶ P(逻辑处理器, 数量≈CPU) ─▶ M(系统线程) ─▶ 核\n        │                │\n        └──── channel 通信 ──── 代替「共享内存 + 锁」\n   「不要通过共享内存来通信，而要通过通信来共享内存」"}},{"h":"二、与其他运行时对照","s":"公民」，启动成本低到可以「来一个请求开一个」。","c":null},{"h":"工程落地时的几个决策点","s":"goroutine 的「轻」是有代价的：它太便宜了，便宜到你会忘记它也需要被管理。最常见的事故是 goroutine 泄漏——一个 goroutine 因为「永远等不到的 channel / 永远不会关闭的 ticker / 忘了 ca…","c":{"lang":"js","code":"// 见 EXAMPLES[fs-ch15]：goroutine 并发 + channel 汇总、unbuffered rendezvous 等"}}]},{"id":"fs-ch15/02-gin-routing-and-middleware","file":"02-gin-routing-and-middleware.md","title":"Gin 路由与中间件：路由树、洋葱链与 Context","kind":"compare","secs":[{"h":"一、路由与中间件机制","s":"Gin 的路由不是「正则挨个匹配」，而是基于 radix tree（基数树/压缩前缀树）。把 /api/users/:id","c":null},{"h":"二、与其他框架对照","s":"在 Next() 前后的两段；语义几乎一一对应。","c":null},{"h":"工程落地时的几个决策点","s":"中间件的「顺序即安全」是 Gin 里最容易被写错、也最致命的一点。一个真实事故链是：限流中间件被注册在认证中间件之前，攻击者于是可以用未认证请求把限流配额打满，导致正常已认证用户被全部拒之门外——限流本应保护系统，却成了 DoS 的入口…","c":{"lang":"js","code":"// 见 EXAMPLES[fs-ch15]：中间件洋葱链、c.Abort 中断链"}}]},{"id":"fs-ch15/03-error-as-value-and-contract","file":"03-error-as-value-and-contract.md","title":"接口契约与错误处理：error 作为值与「消费者定义接口」","kind":"compare","secs":[{"h":"一、error 作为值","s":"在 Java 里，错误常常以「异常」形态出现：要么受检异常逼你 try/catch 或 throws，要么运行时","c":null},{"h":"二、接口契约与跨语言对照","s":"Java 的接口多由「提供方」定义（interface UserService {...} 放在库里，实现类去 implements）。","c":null},{"h":"工程落地时的几个决策点","s":"把「error 作为值」落到工程里，第一件要改的是心态：在 Go 里，if err != nil 不是样板代码，而是「这个操作可能失败」的显式声明。新手常犯两个错：一是「为了编译清爽把 err 赋值给 _ 忽略掉」，等于关掉了警报；二是…","c":{"lang":"js","code":"// 见 EXAMPLES[fs-ch15]：error 作为值、interface 消费者定义"}}]},{"id":"fs-ch15/04-snippets","file":"04-snippets.md","title":"fs-ch15 · Go 并发与 Gin 实战代码片段","kind":"flow","secs":[{"h":"goroutine + channel 汇总","s":"","c":{"lang":"go","code":"func sum(nums []int) int {\n    ch := make(chan int, len(nums))\n    for _, n := range nums {\n        go func(v int) { ch <- v * v }(n) // 每个 goroutine 捕获副本\n    }\n    total := 0\n    for range nums { total += <-ch }\n    return total\n}"}},{"h":"context 取消信号","s":"","c":{"lang":"go","code":"func worker(ctx context.Context) {\n    for {\n        select {\n        case <-ctx.Done():\n            return // 收到取消，退出 goroutine\n        default:\n            // 做点事\n        }\n    }\n…"}},{"h":"用 WaitGroup 等全部完成","s":"","c":{"lang":"go","code":"var wg sync.WaitGroup\nfor _, url := range urls {\n    wg.Add(1)\n    go func(u string) {\n        defer wg.Done()\n        fetch(u)\n    }(url)\n}\nwg.Wait() // 启动前已 Add 完"}},{"h":"Gin 中间件（洋葱链）","s":"","c":{"lang":"go","code":"func AuthMiddleware() gin.HandlerFunc {\n    return func(c *gin.Context) {\n        if !authorized(c) {\n            c.AbortWithStatusJSON(401, gin.H{\"error\": \"unauthorized\"})\n            return // Abort 后直接 return，不要 Next()\n        }\n        c.Next()\n    }\n}\n…"}},{"h":"error 作为值：包装与判断","s":"","c":{"lang":"go","code":"func load(id string) (*User, error) {\n    u, err := repo.Find(id)\n    if err != nil {\n        return nil, fmt.Errorf(\"load user %s: %w\", id, err) // 保留链条\n    }\n    return u, nil\n}\n// 上层：if errors.Is(err, ErrNotFound) { ... }"}},{"h":"消费者定义小接口","s":"","c":{"lang":"go","code":"type Fetcher interface { Fetch(ctx context.Context, id string) ([]byte, error) }\n// 任何满足 Fetch 方法的类型自动可用，无需 implements 声明\ntype HTTPFetcher struct{ client *http.Client }\nfunc (h *HTTPFetcher) Fetch(ctx context.Context, id string) ([]byte, error) { /* ... */ }"}},{"h":"select + 超时避免永久阻塞","s":"","c":{"lang":"go","code":"select {\ncase res := <-ch:\n    handle(res)\ncase <-time.After(2 * time.Second):\n    log.Println(\"timeout\")\n}"}},{"h":"🧑‍💻 程序员视角","s":"goroutine 泄漏是 Go 服务最常见的内存问题：向无缓冲 channel 发送但没人接收，协程永远阻塞——必须用 context 或 select + done 兜底。WaitGroup 的 Add 要在启动协程前调用，写在协程…","c":null},{"h":"🎓 博士生视角","s":"Go 的并发模型是「CSP：通过通信共享内存」，channel 是「带类型的同步队列」，其阻塞语义由容量决定。context 是「取消与超时的传播机制」，它沿调用树向下传递，使「一个请求的所有子任务」能被统一取消。GMP 调度器把 go…","c":null},{"h":"📚 考研者视角","s":"Go 面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"关于 Goroutine 与 Channel，正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"goroutine 初始栈约 1MB，和 Java 线程一样重"},{"k":"B","t":"无缓冲 channel 的 send 会一直阻塞，直到有 receive 接住（会合语义）"},{"k":"C","t":"多个 goroutine 直接共享变量 count++ 是安全的，不需要任何同步"},{"k":"D","t":"channel 只能传数据，不能用作同步原语"}],"ans":"B","why":"goroutine 初始栈仅约 2KB（A 错）；无缓冲 channel 的 send 必须等 receive 接住才返回，这是会合语义（B 对）。共享变量 count++ 在 Go 里仍是数据竞争（C 错）；channel 本身就是语言内建的同步原语（D 错）。"},{"kind":"output","q":"读代码写输出（Go 风格的 channel 汇总，JS 模拟）","stem":"下面用 JS 模拟「N 个 goroutine 各自通过 channel 汇报完成、单一收集者汇总」。输出是什么？ js class Chan { constructor(cap = 0) { this.cap = cap; this.buf = []; this.putQ = []; this.takeQ = []; } put(v) { return new Promise(res => {…","opts":[],"ans":"并发 goroutine 完成数: 200","why":"200 个 goroutine 各往无缓冲 channel put(1)，单一收集者 take 200 次汇总。channel 保证每个「完成信号」被安全传递而非共享计数器，最终 done 必然等于 200，全程无锁——这正是「通过通信共享内存」的落地。"},{"kind":"fix","q":"改错：为什么这个计数在 Go 里是数据竞争","stem":"下面这段（Go 思路、用 JS 表达）想统计完成的 goroutine 数，但在 Go 里会是数据竞争。指出问题并改正。 js let shared = 0; for (let i = 0; i < 1000; i++) { (async () => { shared++; })(); } （在 Go 中对应的是 N 个 goroutine 直接对包级变量 shared++。）","opts":[],"ans":"class Chan { constructor(cap = 0) { this.cap = cap; this.buf = []; this.putQ = []; this.takeQ = []; } put(v) { return new Promise(res => { if (this.takeQ.length…","why":"N 个并发体直接改同一个 shared 在 Go 里是数据竞争（go run -race 会报）。正确做法是把「+1」作为事件发到 channel，由单一收集者汇总——数据只在那一个 goroutine 手里，根本不需要锁。JS 单线程下 shared++ 碰巧正确，但那是语言特性，不是模型正确。"},{"kind":"coding","q":"实现 Gin 风格中间件洋葱链与 Abort 中断","stem":"用 JS 模拟 Gin 的中间件机制：实现 runMiddleware(handlers, ctx)，ctx 提供 logs 数组、abort()、isAborted()；next() 在未被 abort 时调用下一个 handler。要求：① 中间件在 next() 前后的代码分别作为「进/出」日志，形成洋葱顺序；② 某个中间件调 abort() 后，后续 handler 不再执行。自测两条链：…","opts":[],"ans":"function runMiddleware(handlers, ctx) { let i = 0; function next() { if (ctx.isAborted()) return; if (i >= handlers.length) return; const h = handlers[i++]; h(c…","why":"洋葱模型的核心是 next() 把控制交还给框架执行链上下一个；next() 之前的代码在「进」时跑，next() 返回后跑「出」。abort() 置标记后，next() 开头检查 isAborted() 直接返回，后续 handler 不再执行——但注意 abort 后本函数内不应再调 next()，否则那一次仍会放行（模拟里那次 next 因标记被拦，但下个本该跳过的也因没…"},{"kind":"choice","q":"Go 的 error 与 Java 异常对照，正确的是","stem":"关于 Go 的错误处理，正确的是","opts":[{"k":"A","t":"Go 用异常机制捕获错误，和 Java try/catch 一样"},{"k":"B","t":"Go 把错误作为普通返回值，调用方需显式 if err != nil 检查"},{"k":"C","t":"可预期的失败（网络超时）应该用 panic 抛出让 recover 兜住"},{"k":"D","t":"Go 接口必须由实现方声明 implements 才算实现"}],"ans":"B","why":"Go 没有异常（panic 只给不可恢复状态），错误是普通返回值，调用点必须显式检查（B 对）。可预期失败要用 error 返回而非 panic（C 错）；Go 接口是结构化的、由消费者定义、满足方法集即实现，无需 implements（D 错）。"},{"kind":"output","q":"读代码写输出（error 作为值 + 消费者定义接口）","stem":"js function divide(a, b) { if (b === 0) return [null, \"division by zero\"]; return [a / b, null]; } function useQuotient(x, y) { const [q, err] = divide(x, y); if (err !== null) return \"错误:\" + err; ret…","opts":[],"ans":"商=5 错误:division by zero Woof 不是 Greetable","why":"divide 返回 [result, error] 元组，调用方显式判断 err；useQuotient(10,0) 命中错误分支。greetable 模拟「消费者定义接口」：只要有 Greet 方法的对象就满足，空对象不满足返回提示。这对应 Go 的结构化接口与显式错误检查。"},{"kind":"coding","q":"用 worker pool（缓冲 channel）并发处理任务","stem":"用 JS 模拟 Go 的 worker pool：一个任务 channel（缓冲 3）、结果 channel（缓冲 3）、3 个 worker 从任务 channel 取任务算 t2 再投结果 channel。主协程投 5 个任务、再投 3 个 null 作为各 worker 终止信号，最后取 5 个结果按任务 id 排序输出（t1->2,t2->4,...,t5->10）。","opts":[],"ans":"class Chan { constructor(cap = 0) { this.cap = cap; this.buf = []; this.putQ = []; this.takeQ = []; } put(v) { return new Promise(res => { if (this.takeQ.length…","why":"这是 Go 里最经典的「用缓冲 channel 做 worker pool」模式：任务进 channel、worker 抢着取、结果回 channel、用 null 当终止信号让每个 worker 优雅退出。关键是 worker 数量与终止信号数量要匹配（3 个 worker 发 3 个 null），否则会有 worker 永远阻塞在 take 上。按 task id 排序保证…"},{"kind":"fix","q":"改错：Gin 中间件 Abort 后仍放行","stem":"下面这个 Gin 风格鉴权中间件，期望「超限就拦截」，但实际仍会把请求放给 handler。指出问题并改正。 js function ratelimit(ctx, next) { if (overLimit(ctx)) { ctx.abort(); } next(); // 无论是否 abort 都继续 }","opts":[],"ans":"function ratelimit(ctx, next) { if (overLimit(ctx)) { ctx.abort(); return; // abort 后不要再 next()，否则本次仍会放行链上下一个 } next(); }","why":"问题在 abort() 之后无条件调了 next()。abort() 只是置「后续不再执行」标记，但本次 next() 调用本身会触发链上下一个 handler，于是本应被拦的请求仍被放行。修法是 abort 后直接 return，不再 next()。"}],"works":[{"h":"goroutine 泄漏：开了没退出条件","d":"错在：go handle(req) 里有个 for {} 或阻塞的 channel 操作，但没有任何退出信号。 为什么：goroutine 不会自己消失，泄漏的 goroutine 会一直占内存、占调度，时间长了对齐到 GMP 的 M 也会堆积，最终 OOM 或调度变慢。"},{"h":"多个 goroutine 共享变量却不上锁","d":"错在：N 个 goroutine 直接 count++ 一个包级变量，以为「反正单进程」。 为什么：Go 里这依然是数据竞争，go run -race 直接报警；在真实多核调度下 count 结果会小于预期且不可复现。"},{"h":"无缓冲 channel 没人接收导致永久阻塞","d":"错在：往一个无缓冲 channel send，但接收方永远没启动或提前退出了。 为什么：无缓冲 channel 的 send 会一直阻塞等待会合，发送方 goroutine 卡死（也是一种泄漏）；若接收方已退出，发送方永远等不到。"},{"h":"A Tour of Go 式误用：向已关闭的 channel 发送","d":"错在：多个生产者往同一个 channel 发，其中一个 close 了，另一个还在 send。 为什么：向已关闭的 channel 发送会 panic（send on closed channel），且这个 panic 会炸掉整个 goroutine 甚至进程（若没 recover）。"},{"h":"Gin 中间件 Abort 后还写 Next，请求仍被放行","d":"错在：鉴权失败调了 c.Abort()，后面又调了 c.Next()，期望「已经中断」。 为什么：Abort 只是置「后续不再执行」标记，但本次 Next() 仍会触发链上下一个，导致本应被拦的请求继续走到 handler。"},{"h":"Gin 中间件顺序排错造成安全漏洞","d":"错在：把限流中间件注册在认证中间件之前。 为什么：未认证请求会先打到限流，攻击者可用大量未认证请求把限流配额打满，使正常用户也被拒；也可能绕过某些依赖认证上下文的逻辑。"},{"h":"把 error 当异常忽略：if err != nil { return } 吞掉","d":"错在：拿到 err 后只 return 不包装、不记录，调用方拿到 nil 以为成功。 为什么：错误在中间层被静默吞掉，上游无法感知失败，最终表现为「偶发无结果」且无法定位根因。"},{"h":"用 panic 处理可预期的失败","d":"错在：网络超时、下游返回错误码时也 panic，指望 recover 中间件兜住。 为什么：panic/recover 本用于不可恢复状态，滥用会让控制流混乱、性能差，且一个漏兜的 panic 直接 500 甚至崩进程；也无法像 error 那样被精细地 errors.Is 判断。"}],"asks":[{"q":"Go 的 Goroutine 和 Java 的线程有什么区别？为什么能开那么多？","a":"Goroutine 初始栈只有约 2KB、按需增长，而 Java 线程默认栈约 1MB；更重要的是 Go 在用户态用 GMP 做 M:N 调度——少量 OS 线程（M）驱动海量 goroutine（G），阻塞系统调用时 M 与 P 解绑让别的 M 顶上，所以开几十万 goroutine 也不至于拖垮进程。Java 一个任务占一个线程、阻塞就空转一个线程，数量上不去。","fu":["GMP 里 P 的作用到底是什么？","goroutine 阻塞在 channel 和阻塞在系统调用，对调度的影响有何不同？"],"tag":"通用"},{"q":"为什么说「不要通过共享内存通信」？Go 推荐怎么做？","a":"共享内存加锁容易写出数据竞争和死锁，且「谁锁了哪块」很难审查。Go 推荐开 channel，让 goroutine 之间只通过 channel 传数据——发送和接收的会合本身就完成了同步，不需要锁。比如 N 个 goroutine 要累加，不要都去 count++，而是各自把「+1」事件发到 channel，由一个汇总 goroutine 收。","fu":["什么场景反而适合用 sync.Mutex 而不是 channel？","无缓冲和有缓冲 channel 的语义差别是什么？"],"tag":"通用"},{"q":"Gin 的中间件链是怎么工作的？Next 和 Abort 各干什么？","a":"中间件是 func(c gin.Context)，多个中间件和 handler 串成洋葱：在 c.Next() 之前的代码请求「进」时执行，之后「出」时执行。Next() 把控制交还给框架执行链上下一个。某中间件要拦截请求时调 c.Abort()，它置上「后续不再执行」标记；注意 Abort 后不要再 Next()，否则那一次仍会放行。中间件注册顺序就是执行顺序，安全相关中间件要排最前。","fu":["Gin 的 Context 和 Go 的 context.Context 是一回事吗？","中间件顺序排错会有什么具体的安全后果？"],"tag":"通用"},{"q":"Go 把 error 当值返回，和 Java 异常比有什么优劣？","a":"Go 没有异常（panic 只给不可恢复状态），错误是普通返回值，调用方必须显式 if err != nil，把「可能出错」写在签名里、逼你在调用点处理，错误传播路径一目了然。代价是代码啰嗦。Java 受检异常也强制处理但更侵入，运行时异常常被吞。Go 推荐用 fmt.Errorf(\"...: %w\", err) 包装、errors.Is/As 判断，而不是字符串匹配。","fu":["什么时候 Go 才该用 panic？","为什么 error 包装要用 %w 而不是 %v？"],"tag":"通用"}]},{"id":"fs-ch04","subj":"fullstack","title":"Node.js 与后端 API","summary":"Node 运行时与事件循环；CommonJS/ESM 模块；HTTP 服务；Express/Koa 路由与中间件；错误处理；环境变量与配置。","concepts":[{"id":"fs-ch04/01-node-runtime-eventloop","file":"01-node-runtime-eventloop.md","title":"fs-ch04 · Node 运行时与事件循环","kind":"timeline","secs":[{"h":"一、Node 单线程模型与 libuv 事件循环（六阶段）","s":"Node 的 JavaScript 在主线程的单一调用栈上执行，靠 libuv 提供的事件循环调度异步任务；文件 I/O、DNS、crypto、zlib 等由 libuv 线程池（默认 4 线程）并行完成后，回调进入对应阶段。","c":null},{"h":"二、process.nextTick / Promise.then / setImmedia…","s":"三者都用于「延迟执行」，但进入的队列与优先级不同：process.nextTick 进 nextTick 队列（优先级最高，独立于微任务），Promise.then 进微任务（PromiseJobs）队列，setImmediate 进事…","c":null},{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"js","code":"const fs = require('fs');\n\nconst order = [];\nconst mark = (s) => {\n  order.push(s);\n  console.log(s);\n};\n\n// ---- 第一段：同步代码 + nextTick + Promise ----\n…"}}]},{"id":"fs-ch04/02-http-server-middleware","file":"02-http-server-middleware.md","title":"fs-ch04 · HTTP 服务与中间件","kind":"flow","secs":[{"h":"一、从零手写 HTTP 服务器（路由 / 路径变量 / JSON body / 状态码）","s":"Node 内置 http 模块把 socket 字节流按 RFC 7230 解析为 req/res 对象；服务器 = 一个 createServer 回调，需在回调内做路由匹配、请求体解析与响应。状态码是三位数字，首位表类别。","c":null},{"h":"可运行代码：compose 的洋葱模型","s":"中间件的「进去一圈、出来一圈」由 next() 返回 Promise 保证——await next() 之后才继续，","c":{"lang":"js","code":"function compose(middlewares) {\n  return function (ctx) {\n    let last = -1;                       // 防止同一个中间件里 next() 被调两次\n    function dispatch(i) {\n      if (i <= last) return Promise.reject(new Error(\"next() called multiple times\"));\n      last = i;\n      const fn = middlewares[i];\n      if (!fn) return Promise.resolve();\n      try {\n…"}},{"h":"二、中间件模型与 compose（next 传递、错误处理中间件四参数）","s":"中间件是 fn(ctx, next)（Koa）或 fn(req, res, next)（Express）；compose 把数组规约为单函数，靠 next() 串成「洋葱模型」：进入时从外到内，返回时从内到外。错误中间件通过 4 个参数…","c":null}]},{"id":"fs-ch04/03-streams-buffer","file":"03-streams-buffer.md","title":"fs-ch04 · 流、背压与 Buffer 编码","kind":"stack","secs":[{"h":"一、Stream 流控与背压（highWaterMark / write 返回值 / dra…","s":"流是处理「连续数据」的抽象：Readable 生产数据、Writable 消费数据、Transform 既是又是。背压是有界缓冲下的反馈机制：消费者慢于生产者时，靠 write() 的布尔返回值 + drain 事件形成负反馈，使内存占…","c":null},{"h":"二、Buffer 与编码（UTF-8 多字节切片坑）","s":"Buffer 是字节视图（Uint8Array 子类），与字符串不同：字符串按码点索引，Buffer 按字节索引。UTF-8 用 1–4 字节变长编码一个码点，按字节切片可能在码点中间切断，产生替换符（U+FFFD）乱码。","c":null}]},{"id":"fs-ch04/04-modules-workers","file":"04-modules-workers.md","title":"fs-ch04 · 模块系统与并发","kind":"timeline","secs":[{"h":"一、CommonJS vs ESM（模块封装、循环依赖、require 缓存）","s":"CommonJS（require / module.exports）同步加载、有缓存；ESM（import / export）静态可分析、异步加载、严格模式。二者在循环依赖、缓存、语法上差异显著，Node 用 .cjs/.mjs 或 p…","c":null},{"h":"二、worker_threads 与多核（CPU 密集 vs I/O 密集、事件循环边界）","s":"Node 的 JS 在主线程单调用栈执行；CPU 密集任务若在主线程同步执行会占满调用栈、饿死事件循环。worker_threads 在独立 V8 实例/线程上并行执行 JS，突破「单线程」对 CPU 的限制；cluster 则 for…","c":null}]},{"id":"fs-ch04/05-node-practical-recipes","file":"05-node-practical-recipes.md","title":"凯喵实战手记 · Node.js 运行时：那些「单线程」的误解与现场","kind":"flow","secs":[{"h":"现场 1：JS 是单线程，但 Node 不是","s":"JS 代码在单调用栈上跑，同一时刻只执行一段；但底层 libuv 有线程池处理文件、DNS、加密等操作，还有 worker_threads 能跑并行 JS。凯喵：理解「JS 单线程 + 底层线程池」这个分工，你才知道为什么 CPU 密集…","c":null},{"h":"现场 2：事件循环的六个阶段要有个整体印象","s":"定时器、待处理回调、轮询、检查、关闭回调，加上微任务队列，构成了事件循环的骨架。凯喵：不需要背每个阶段的细节，但要记住「微任务（Promise 回调）在当前操作结束后立刻清空，宏任务（定时器、IO）要等下一轮」，这决定了你的代码执行顺序…","c":{"lang":"js","code":"Promise.resolve().then(() => console.log('micro'));\nsetTimeout(() => console.log('macro'), 0);\nconsole.log('sync');\n// 输出：sync → micro → macro"}},{"h":"现场 3：CPU 密集任务会阻塞整个服务","s":"在主线程里跑一个大循环或复杂计算，事件循环被占住，所有请求都得排队。凯喵：图片处理、加解密、大 JSON 解析这类任务，要么放进 worker_threads，要么拆成小块用 setImmediate 让出控制权，绝不能在主线程硬跑。","c":{"lang":"js","code":"const { Worker } = require('worker_threads');\nnew Worker('./heavy.js');   // 重活丢给子线程"}},{"h":"现场 4：await 不等于「并行」","s":"连续 await 是串行等待，要并行就得先发起再统一等。凯喵：const [a, b] = await Promise.all([fa(), fb()]) 才是并行；写成两个独立 await 会一个接一个，耗时相加。","c":{"lang":"js","code":"// 串行：耗时 = t1 + t2\nconst a = await fa(); const b = await fb();\n// 并行：耗时 = max(t1, t2)\nconst [a2, b2] = await Promise.all([fa(), fb()]);"}},{"h":"现场 5：未捕获的 Promise 拒绝会拖垮进程","s":"一个没 .catch 的 Promise 拒绝，在较新版本 Node 里会触发 unhandledRejection，默认可能直接退出进程。凯喵：所有异步入口都要有错误处理，进程级挂 process.on('unhandledRejec…","c":null},{"h":"现场 6：中间件顺序决定行为","s":"Express/Koa 的中间件按注册顺序执行，鉴权放错位置、错误处理没放最后，都会导致「明明写了却不生效」。凯喵：顺序原则是「日志 → 解析 → 鉴权 → 业务 → 404 → 错误处理」，错误处理中间件必须最后注册。","c":{"lang":"js","code":"app.use(logger);\napp.use(auth);\napp.use(router);\napp.use(errorHandler);   // 必须最后"}},{"h":"现场 7：错误处理中间件要四个参数","s":"Express 靠参数个数识别错误处理中间件，写成 (req, res) 就变成普通中间件，next(err) 不会进它。凯喵：错误处理必须是 (err, req, res, next) 四个参数，少一个都不行，这个坑几乎每个 Expr…","c":{"lang":"js","code":"app.use((err, req, res, next) => { res.status(500).json({ error: err.message }); });"}},{"h":"现场 8：请求体要限流，JSON 要 try-catch","s":"不限制 body 大小，一个大请求就能耗尽内存；JSON.parse 遇到非法内容会抛异常，不捕获就 500。凯喵：express.json({ limit: '1mb' }) 限制大小，解析失败返回 400 而不是让异常冒泡。","c":null},{"h":"现场 9：Stream 处理大文件，别 readFile 全读进内存","s":"fs.readFile 把整个文件读进内存，大文件直接 OOM。凯喵：用 createReadStream 配合管道，边读边处理，内存占用恒定。文件上传、日志分析、大 CSV 解析都该用流。","c":{"lang":"js","code":"fs.createReadStream('big.log')\n  .pipe(transform)\n  .pipe(fs.createWriteStream('out.log'));"}},{"h":"现场 10：Buffer 是二进制，不是字符串","s":"Buffer 存的是字节，toString() 才转字符串，默认按 UTF-8。凯喵：处理二进制协议、图片、加密数据时全程用 Buffer，别在中途转成字符串再转回来，编码转换会损坏数据。","c":null},{"h":"现场 11：背压（backpressure）不处理会撑爆内存","s":"可读流产生数据的速度超过可写流消费的速度，中间缓冲区无限增长。凯喵：用 pipe 它会自动处理背压；手写 data 事件时要注意 write() 返回 false 就暂停读取，等 drain 再继续。","c":null},{"h":"现场 12：模块缓存的副作用","s":"require 同一个模块多次，拿到的是同一个实例，模块顶层代码只执行一次。凯喵：这既是性能优势，也是坑——模块级的可变状态会被所有引用方共享，测试之间还可能互相污染。","c":null},{"h":"现场 13：ESM 与 CommonJS 混用的边界","s":"import 与 require 的解析规则不同，混用时可能出现「默认导出拿到的是整个模块对象」这类问题。凯喵：新项目统一用 ESM，老项目迁移时用动态 import() 过渡，别在同一文件里混着写。","c":null},{"h":"现场 14：用 process.env 管理配置，但要有默认值","s":"环境变量是字符串，缺了就是 undefined。凯喵：启动时集中校验必需的环境变量，缺了就快速失败，别让它带着 undefined 跑进业务逻辑，最后在奇怪的地方报错。","c":null},{"h":"凯喵叮嘱：把错误处理当成一等公民","s":"最后叮嘱一句：Node 的异步模型让错误「到处乱飞」，回调、Promise、事件、流各有各的报错方式。凯喵的原则是：每一个异步入口都必须有明确的错误归宿，要么当场处理，要么显式传递，绝不「发出去就不管」。","c":null},{"h":"🧑‍💻 程序员视角","s":"「JS 单线程」指的是「执行 JS 的线程只有一个」，Node 本身还有 libuv 线程池、网络 IO 线程——所以文件读写与 DNS 查询是真并行。事件循环的六个阶段里，timers 与 poll 最常被误解：setTimeout(…","c":null},{"h":"🎓 博士生视角","s":"Node 的并发模型是「单线程事件循环 + 非阻塞 IO + 线程池」，其优势在 IO 密集、劣势在 CPU 密集。事件循环的阶段顺序（timers → pending → poll → check → close）与微任务队列（pro…","c":null},{"h":"📚 考研者视角","s":"Node 面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"Node.js 最适合哪类场景？","stem":"基于 Node 的单线程事件循环模型，下列哪一项是它的典型优势场景？","opts":[{"k":"A","t":"CPU 密集型科学计算"},{"k":"B","t":"高并发 I/O 密集型网络服务"},{"k":"C","t":"海量内存图计算"},{"k":"D","t":"GPU 模型训练"}],"ans":"B","why":"Node 单线程事件循环擅长非阻塞 I/O，适合高并发网络服务；CPU 密集任务会饿死事件循环，应放 worker_threads。"},{"kind":"choice","q":"关于 CommonJS 与 ESM，正确的是？","stem":"下列关于 Node 模块系统的说法，哪一项正确？","opts":[{"k":"A","t":"require 是异步加载"},{"k":"B","t":"ESM 的 import 是静态可分析的、支持 tree-shaking"},{"k":"C","t":"module.exports 与 exports 是两个互相独立的对象"},{"k":"D","t":"CommonJS 循环依赖下永远拿到完整 exports"}],"ans":"B","why":"ESM 的 import/export 在编译期可静态分析，支持 tree-shaking；require 同步；exports 是 module.exports 的别名；CJS 循环依赖可能拿到半截（undefined）exports。"},{"kind":"output","q":"预测事件循环打印顺序","stem":"下面代码依次打印什么（按行写出输出）？ js console.log('1'); process.nextTick(() => console.log('2')); Promise.resolve().then(() => console.log('3')); setImmediate(() => console.log('5')); setTimeout(() => console.log('4…","opts":[],"ans":"1 6 2 3 5 4","why":"同步先跑（1,6）；然后清空 nextTick 队列（2）、微任务（3）；进入事件循环后 check 阶段 setImmediate（5）先于 timers 阶段 setTimeout（4）。"},{"kind":"fix_error","q":"修复 async 错误未传给错误中间件","stem":"下面代码 async 抛出的错误进不了四参数错误中间件，请修复（保留中间件链结构）： js use(async (c, n) => { await risky(); }); use((err, c, req, n) => { c.log.push('status=500'); });","opts":[],"ans":"async function risky() { throw new Error('db fail'); } const stack = []; function use(fn) { stack.push(fn); } function run(ctx, final) { let i = 0; function nex…","why":"async 函数 reject 不会自动冒泡到 next；用 try/catch 捕获后调用 next(err)（或捕获 Promise rejection 调 next(err)），错误中间件才能收到。"},{"kind":"coding","q":"手写中间件 compose","stem":"实现一个 compose(middlewares)：返回一个 (ctx, final) 函数，按注册顺序串起中间件（fn(ctx, next)），支持四参数错误中间件 (err, ctx, req, next) 在 next(err) 时收口；要求可运行并演示洋葱顺序。","opts":[],"ans":"function compose(middlewares) { return function (ctx, final) { let i = 0; function next(err) { while (i < middlewares.length) { const mw = middlewares[i]; if (e…","why":"用递归 next 推进；遇到 err 时跳过普通中间件、找形参长 4 的错误中间件；async 中间件的 reject 需 .catch 转 next(err)。"},{"kind":"coding","q":"手写路径匹配 /items/:id","stem":"实现一个 matchRoute(method, path, routes)：支持 :name 路径变量提取（如 /items/:id 匹配 /items/42 得到 {id:'42'}），方法不匹配或路径不符返回 null。要求可运行。","opts":[],"ans":"function matchRoute(method, path, routes) { for (const r of routes) { if (r.method !== method) continue; const keys = []; const rx = new RegExp('^' + r.pattern.…","why":"把 :name 段替换为正则捕获组 ([^/]+)，匹配后按 keys 顺序回填 params；方法先筛再匹配路径。"},{"kind":"coding","q":"LeetCode 1 · 两数之和（算法素养补充）","stem":"给定整数数组 nums 与目标值 target，返回两数之和等于 target 的下标（可假设恰有一组解）。题面与约束以官方为准，详见 external_url，此处不复述题面。","opts":[],"ans":"function twoSum(nums, target) { const seen = new Map(); for (let i = 0; i < nums.length; i++) { const need = target - nums[i]; if (seen.has(need)) return [seen.…","why":"哈希表一次遍历：存「值→下标」，对当前数查 target-num 是否已在表中，O(n) 时间 O(n) 空间。"},{"kind":"choice","q":"Buffer 按字节切片会怎样？","stem":"对于 const buf = Buffer.from('你好', 'utf8'); buf.subarray(1).toString('utf8')，结果特征是？","opts":[{"k":"A","t":"正常得到「好」，无影响"},{"k":"B","t":"在码点中间切断，产生替换符（U+FFFD）乱码"},{"k":"C","t":"抛出 RangeError"},{"k":"D","t":"返回空字符串"}],"ans":"B","why":"UTF-8 变长编码，subarray(1) 从字节 1 切断「你」（3 字节）得到非法序列，解码替换为 U+FFFD；应按字符（string.slice）或 StringDecoder 处理。"}],"works":[{"h":"在顶层脚本里认为 setTimeout(0) 一定先于 setImmediate","d":"实测顶层脚本中 setImmediate 反而先执行（0ms 被钳制为 ~1ms，循环先到 check 阶段）。 需要「下一轮 check 阶段立即执行」用 setImmediate；只在 I/O 回调内顺序才稳定为 setImmediate 先。"},{"h":"process.nextTick 里无限递归导致微任务饥饿","d":"nextTick 队列优先级高于微任务与 I/O，递归推入会饿死事件循环、所有 I/O 永久延迟。 让出事件循环改用 setImmediate，避免无限递归推入 nextTick。"},{"h":"用 fs.readFileSync 等同步 API 阻塞主线程","d":"大文件会卡死所有并发请求。 用异步 API，或把重 I/O 放 worker_threads / 改用流分块读取。"},{"h":"HTTP 响应忘了 res.end()","d":"连接一直挂起、客户端超时、连接泄漏。 任何分支都必须 res.end()（或 write 后 end），错误分支也要 end。"},{"h":"手写路由把查询串当路径匹配","d":"req.url 含 ? 之后的查询串，直接拿它做路径匹配会失败。 用 new URL(req.url, base).searchParams 取查询，或 req.url.split('?')[0] 取纯路径。"},{"h":"Buffer 按字节切片截断多字节字符产生乱码","d":"中文等 UTF-8 变长编码在字节中间切断得到替换符（U+FFFD）。 用字符串 slice / StringDecoder 累积解码，显式指定编码。"},{"h":"中间件里 async 抛错却没传给 next(err)","d":"async 函数 reject 不会自动进四参数错误中间件，进程可能 unhandledRejection。 await 包 try/catch 调 next(err)，或捕获 Promise rejection 后 next(err)。"},{"h":"错误处理中间件参数少于 4 个","d":"框架靠 (err, req, res, next) 四参数识别错误中间件，少参数会被当普通中间件从而收不到错误。 错误中间件签名必须是四参数。"}],"asks":[{"q":"讲讲 Node 的事件循环，和浏览器事件循环有什么区别？有哪些阶段？","a":"Node 靠 libuv 事件循环调度，固定六阶段：timers → pending callbacks → idle/prepare → poll → check → close。每阶段有独立 FIFO 队列，阶段间切换时先清空 nextTick 队列再清空微任务（PromiseJobs）。浏览器只有宏任务/微任务两轮，没有六阶段细分。结论顺序：sync → nextTick → Promise…","fu":["setImmediate 和 setTimeout(0) 谁先？","pending callbacks 阶段是什么？"],"tag":"通用/字节"},{"q":"Node 为什么适合 I/O 密集、不适合 CPU 密集？怎么解决 CPU 密集？","a":"单线程事件循环一次只执行一个调用栈；I/O 用非阻塞 + 回调，期间事件循环可处理别请求，所以高并发 I/O 很省。但 CPU 密集任务同步执行会占满调用栈、饿死事件循环，所有 I/O 延迟。解决：CPU 密集放 worker_threads（独立线程并行 JS），或用 cluster 多进程利用多核；I/O 密集本身不用额外线程。","fu":["worker_threads 和 cluster 区别？","libuv 线程池干什么？"],"tag":"通用/阿里"},{"q":"CommonJS 和 ESM 有什么区别？循环依赖下表现如何？","a":"CJS 用 require/module.exports，同步加载、有缓存（同路径只执行一次），模块被包进 (function(exports,require,module,...){})；ESM 用 import/export，静态可分析、异步、严格模式、live binding。循环依赖：CJS 在 a 未填充完就 require b、b 又 require a 时，a 拿到半截 export…","fu":["exports 和 module.exports 什么关系？","require 缓存机制？"],"tag":"通用/美团"},{"q":"中间件（Koa/Express）的洋葱模型是什么？错误处理中间件为什么是四参数？","a":"中间件 fn(ctx, next)；compose 用递归 next 串成洋葱：进入从外到内、返回从内到外（A in → B in → B out → A out）。错误处理中间件签名 (err, req, res, next) 四参数，框架靠形参长度 4 识别它；普通中间件是 2/3 参数。next(err) 时框架跳过普通中间件、直接找四参数错误中间件收口。async 中间件抛错不会自动进错误…","fu":["async 错误为什么收不到？","Koa 和 Express 中间件签名区别？"],"tag":"通用/字节"}]},{"id":"fs-ch05","subj":"fullstack","title":"数据库与 REST API 设计","summary":"关系型与文档型数据库选型；SQL 基础与索引；ORM/ODM；RESTful 资源设计；请求校验与分页；API 文档（OpenAPI）。","concepts":[{"id":"fs-ch05/01-database-selection-sql-index","file":"01-database-selection-sql-index.md","title":"fs-ch05 · 一、数据库选型与 SQL 索引","kind":"compare","secs":[{"h":"一、关系型（PostgreSQL/MySQL）与文档型（MongoDB）的选型判据","s":"关系型以「表 + 行 + 强 schema + 多表事务」为契约；文档型以「集合 + BSON 文档 + 灵活 schema + 单文档原子」为契约。选型不是比谁更好，而是判断哪一组约束更贴合业务的写入模式、读取模式与一致性要求。","c":null},{"h":"二、索引：B+ 树、最左前缀与覆盖索引","s":"索引是用「额外存储 + 写入放大」换「按值定位从 O(n) 降到 O(log n)」的结构。B+ 树是被最多数据库选为默认索引结构的有序多路平衡树。","c":{"lang":"text","code":"before index :  SELECT id, payload FROM events WHERE tenant_id=? AND kind=?\n                plan = SCAN events                       full_table_scan=True\nafter index  :  plan = SEARCH events USING INDEX idx_tenant_kind (tenant_id=? AND kind=?)\n                plan = SEARCH events USING COVERING INDEX idx_tenant_kind (tenant_id=? AND kind=?)   # 只 select id 时\nprefix fail  :  SELECT id, payload FROM events WHERE kind=?\n                plan = SCAN events     \n…"}}]},{"id":"fs-ch05/02-orm-odm-and-n-plus-1","file":"02-orm-odm-and-n-plus-1.md","title":"fs-ch05 · 二、ORM/ODM 的取舍与 N+1 查询","kind":"compare","secs":[{"h":"一、ORM / ODM：用类型安全换控制力","s":"ORM 把「表/行」映射为「类/对象」，ODM 把「集合/文档」映射为「对象」。主流谱系与各自的定位：","c":null},{"h":"二、N+1：用操作计数发现，用批量合并修复","s":"N+1 指：取「1」个列表后，对列表里的 N 个元素各发一次查询去取关联数据，总查询数为 1 + N。它不会报错、在测试数据量小时也很快，因此是典型的「规模一上来才爆」的性能债。","c":{"lang":"text","code":"authors=5 posts=11\nnested_queries=6 joined_queries=1\nnested_is_1_plus_N=true\njoined_is_single_query=true\nsame_result=true\nquery_reduction_ratio_int=6"}}]},{"id":"fs-ch05/03-restful-design-pagination-errors","file":"03-restful-design-pagination-errors.md","title":"fs-ch05 · 三、RESTful 资源设计、分页与错误契约","kind":"timeline","secs":[{"h":"一、资源设计：名词复数、方法语义与幂等性","s":"REST 的核心约束是：用 URI 标识资源、用 HTTP 方法表达对资源的动作，而方法语义由 RFC 9110 定义，不由开发者自由发挥。","c":{"lang":"text","code":"GET    /articles          集合读取      -> 200 (2xx)\nPOST   /articles          创建成功      -> 201 (2xx)\nDELETE /articles/42       删除成功      -> 204 (2xx)\nPOST   /articles          非法 JSON     -> 400 (4xx)\nGET    /articles/999      资源不存在    -> 404 (4xx)\nPATCH  /articles/42       唯一键冲突    -> 409 (4xx)\nPOST   /articles          schema 不过   -> 422 (4xx)\nPOST   /articles          媒体类型不对  -> 415 (4xx)\nGET    /articles          超过配额      -> 429 (4xx)\n…"}},{"h":"二、分页、过滤与排序","s":"三种分页口径：","c":{"lang":"text","code":"offset_page1=[8, 7, 6]                 cursor_page1=[8, 7, 6]\noffset_page2_before_insert=[5, 4, 3]   cursor_page2_before_insert=[5, 4, 3]\noffset_page2_after_insert=[6, 5, 4]    cursor_page2_after_insert=[5, 4, 3]\noffset_stable_across_insert=False      cursor_stable_across_insert=True\noffset_repeats_row_from_page1=True     cursor_repeats_row_from_page1=False\noffset_needs_count_query_for_total_pages=True\ncursor_needs_count_query_for_total_pages=False"}},{"h":"三、请求校验与统一错误响应（RFC 9457 Problem Details）","s":"三层防线，顺序不可颠倒：","c":{"lang":"text","code":"invalid#0 errors=[\"$.title: required\"]                            # 缺必填\ninvalid#1 errors=[\"$.title: minLength is 1 (got 0)\"]              # 边界（下界）\ninvalid#3 errors=[\"$.score: maximum is 100\"]                      # 边界（上界）\ninvalid#4 errors=[\"$.score: expected integer\"]                    # 类型（1.5 不是整数）\ninvalid#5 errors=[\"$.tags: maxItems is 3 (got 4)\"]                # 数组长度\ninvalid#6 errors=[\"$.slug: must match ^[a-z0-9-]+$\"]              # 正则\ninvalid#7 err\n…"}}]},{"id":"fs-ch05/04-api-contract-version-throttling","file":"04-api-contract-version-throttling.md","title":"fs-ch05 · 四、API 契约、版本策略与稳定性治理","kind":"compare","secs":[{"h":"一、契约优先（Design-First）与 OpenAPI","s":"OpenAPI 3.1 是一份 JSON/YAML 文档，描述 paths、operations、parameters、requestBody、responses、components.schemas。两种工作流：","c":{"lang":"text","code":"operations=4\n  GET /articles -> listArticles\n  POST /articles -> createArticle\n  GET /articles/{id} -> getArticle\n  DELETE /articles/{id} -> deleteArticle\nunique_operation_ids=true\npath_params_always_required=true\nevery_operation_has_2xx=true\nevery_4xx_uses_problem_json=true\n…"}},{"h":"二、版本策略：URL 版本 vs 媒体类型/Header 版本","s":"三条主流路线及其代价：","c":{"lang":"text","code":"request GET /v3/articles  headers={}\n  url_strategy    version=v3 handler=- note=no such route in v3\n  header_strategy version=v1 handler=v1.listArticles note=matched      # 静默回退到默认 v1\n\nrequest GET /articles     headers={\"accept\":\"application/vnd.articles.v2+json\"}\n  url_strategy    version=- handler=- note=no /vN prefix\n  header_strategy version=v2 handler=v2.listArticles note=matched\n\nrequest GET /articles/9   headers={\"api-version\":\"v9\"}\n…"}},{"h":"三、限流与超时：稳定性治理的两个基本手段","s":"限流算法对比：","c":{"lang":"text","code":"scenario1_burst: capacity=3 refill=1/s, 5 requests at t=0\n  req#1 allowed=true  tokens_left=2\n  req#2 allowed=true  tokens_left=1\n  req#3 allowed=true  tokens_left=0\n  req#4 allowed=false tokens_left=0\n  req#5 allowed=false tokens_left=0\n  allowed=3 refused=2\n\nscenario2_steady: 5 requests spaced 1000ms\n…"}}]}],"exams":[{"kind":"choice","q":"什么场景更适合选文档型（MongoDB）","stem":"按「一次业务操作能否落在同一个聚合根内」这一判据，下列哪种场景最适合选文档型数据库？","opts":[{"k":"A","t":"需要跨多张表保证「扣库存 + 建订单」的原子性"},{"k":"B","t":"读多写少、需要对多表做任意 JOIN 与聚合报表"},{"k":"C","t":"一次读取就把一个聚合根（含嵌套子结构）整体取回，且几乎不跨聚合 JOIN"},{"k":"D","t":"需要严格的外键约束防止脏数据"}],"ans":"C","why":"文档型把聚合边界编码进物理布局，整存整取极快。A 需要跨文档事务（关系型更省心）、B 与 D 都需要关系型的 JOIN 与约束能力。选型判据是「聚合边界是否与写入边界重合」，不是性能数字。"},{"kind":"choice","q":"复合索引 (tenant_id, kind) 上哪条查询无法用索引定位","stem":"表 events 上有复合索引 idx_tenant_kind(tenant_id, kind)。查询需要返回列 tenant_id、kind 以外的 payload 列时，下列哪条 WHERE 无法利用该索引的最左前缀定位行？","opts":[{"k":"A","t":"WHERE tenant_id = ?"},{"k":"B","t":"WHERE tenant_id = ? AND kind = ?"},{"k":"C","t":"WHERE tenant_id = ? AND kind > ?"},{"k":"D","t":"WHERE kind = ?"}],"ans":"D","why":"索引只在 (tenant_id, kind) 这个列序上有序，(kind) 单独不是任何前缀，无法定位起点。本章 ex09 实跑显示该查询的计划退化为 SCAN events（uses_index=False）。"},{"kind":"output","q":"读查询计划判据","stem":"下表是同一张表上两条查询的真实计划串，请写出每条计划对应的判定结论（用 full_table_scan / covering_index / non_covering_index 之一）： plan_a = SCAN events plan_b = SEARCH events USING COVERING INDEX idx_tenant_kind (tenant_id=? AND kind=?)…","opts":[],"ans":"plan_a=full_table_scan plan_b=covering_index plan_c=non_covering_index","why":"SCAN 表示未走索引；SEARCH ... USING COVERING INDEX 表示走了覆盖索引（查询列全在索引内，无需回表）；SEARCH ... USING INDEX 表示走了索引但需回表取非索引列。三者判据在本章 ex09 实跑中均可复现。"},{"kind":"fix_error","q":"消除列表接口的 N+1 查询","stem":"下面的 listNaive 对 5 个作者发出 6 次数据库操作（1+N），请改为常数次操作，并保证返回数据完全一致。要求可运行并打印操作计数。","opts":[],"ans":"// 修复前（N+1）：对每个 author 各查一次 posts function listNaive(db) { const authors = db.findAllAuthors(); // 1 次 return authors.map(a => ({ name: a.name, posts: db.findPo…","why":"把「逐个作者查 posts」换成「一次 IN 批量查 + 内存按外键分组」，操作数从 1+N 降为 2（一次取作者、一次取全部关联）。断言 same_result=true 才能证明优化没有改变语义。"},{"kind":"coding","q":"实现稳定的游标（keyset）分页","stem":"用 Python 内置 sqlite3 实现游标分页：第一页无游标，之后以「上一页最后一行的完整排序键 (score, id)」为游标继续翻页。要求演示：并发插入一条最高分记录后，第二页结果不重复且与插入前一致。","opts":[],"ans":"import sqlite3 conn = sqlite3.connect(':memory:') cur = conn.cursor() cur.execute('CREATE TABLE articles (id INTEGER PRIMARY KEY, score INTEGER NOT NULL)') cur.…","why":"游标谓词用行值比较 score < ? OR (score = ? AND id > ?)，因为排序键 (score, id) 构成全序，所以不会漏行也不会重复；游标编码的是「位置」而非「偏移」，因此不受插入导致的窗口漂移影响。"},{"kind":"coding","q":"排序与过滤参数的白名单校验","stem":"实现 parseQuery(raw)：排序字段必须命中白名单（id / createdAt / score / title），支持 - 前缀表示降序；过滤字段按「字段名 → 类型」映射校验（字符串限字符集与长度、整数整体匹配正则）；limit 越界夹到上限 100。要求对合法与非法两组入参都给出结果，非法值不得进入 SQL。","opts":[],"ans":"const SORTABLE = new Set(['id', 'createdAt', 'score', 'title']); const FILTERABLE = { status: 'string', tag: 'string', score: 'integer' }; const MAX_LIMIT = 100…","why":"字段名进入 SQL 标识符位置，参数化占位符保护不了它，必须白名单映射（先校验命中再拼标识符）；值走类型化正则校验。注意 limit 的越界策略要显式选择：这里夹到上限并保证 limit >= 1。"},{"kind":"choice","q":"Problem Details 的成员与媒体类型","stem":"关于 RFC 9457（Problem Details for HTTP APIs），下列说法哪一项正确？","opts":[{"k":"A","t":"媒体类型是 application/json，错误体与成功资源共用同一结构"},{"k":"B","t":"核心成员为 type / title / status / detail / instance，允许添加不与核心成员冲突…"},{"k":"C","t":"type 必须是绝对 URL，不允许使用 about:blank 作为缺省值"},{"k":"D","t":"字段级校验错误必须直接平铺在顶层，不能用扩展成员承载"}],"ans":"B","why":"RFC 9457 的媒体类型是 application/problem+json，五个核心成员为 type/title/status/detail/instance；type 缺省为 about:blank，且允许相对 URI 引用；扩展成员（如 errors 数组、retryAfterSec）可自由添加但不得与核心成员冲突。本章 ex06 实跑验证了这一点。"},{"kind":"coding","q":"实现令牌桶并用虚拟时钟验证突发与稳态","stem":"实现 createBucket(capacity, refillPerSec)，用显式时间轴（不读墙钟）驱动，返回允许/拒绝序列。要求演示三组：t=0 连打 6 个（容量 3、补 1/s）应只有前 3 个放行；间隔 1s 的 5 个请求（容量 3、补 1/s）应全部放行；容量 2、补 1/s、间隔 500ms 的混合场景应呈现「先放行 2 个，之后每隔一个间隔放行 1 个」。","opts":[],"ans":"function createBucket(capacity, refillPerSec) { let tokens = capacity; let last = 0; let now = 0; return { advance(ms) { now += ms; }, tryConsume() { const adde…","why":"令牌桶状态只有 tokens 与 lastRefillAt：补充量 = 经过秒数 × 补充速率，上限为容量；取用时 tokens ≥ 1 才放行。虚拟时钟（显式 advance）让输出确定、可断言，这是性能/状态机类示例应该采用的写法。"}],"works":[{"h":"用 offset 深分页，还在并发写入下翻页","d":"ex03 实跑：插入一条高分记录后 offset 第 2 页由 [5,4,3] 变成 [6,5,4]，把第 1 页已出现过的 6 又返回一次（offset_repeats_row_from_page1=True）；游标页仍为 [5,4,3]（cursor_stable_across_insert=True）。 翻页用游标（keyset…"},{"h":"复合索引列序按「选择性高到低」排","d":"索引的有序性由列序决定，把低频列放第一位会让「只查高频列」的查询无法定位。 按最左前缀的实际查询组合排：等值条件列在前、范围条件列在后；ex09 的 (tenant_id, kind) 同时支持 tenant_id=? AND kind=? 与 tenant_id=? AND kind>?。"},{"h":"以为「建了索引就一定走索引」","d":"ex09 实跑 SELECT id, payload FROM events WHERE kind = ? 在 (tenant_id, kind) 上仍是 SCAN events（uses_index=False）。 以计划串为唯一判据：出现 SEARCH ... USING INDEX 才是走了索引，SCAN 就是没走；建索引后必须…"},{"h":"以为「只查主键就一定覆盖」或「有索引就一定覆盖」","d":"ex09 中同一索引、同一条 WHERE，SELECT id 报 USING COVERING INDEX，而 SELECT id, payload 退回 USING INDEX（需回表取 payload）。 覆盖的判定是「查询涉及的所有列 ⊆ 索引列 ∪ 主键」，多一个非索引列就需要回表。"},{"h":"把「游标分页」当成「更快的 offset」","d":"两者的差别是语义不是性能：offset 依赖绝对位置会漂移，游标把位置编码进数据。 把游标当 API 契约的一部分设计：编码格式、版本号、签名、TTL 都要定，否则客户端可以伪造游标越权读取。"},{"h":"循环访问 ORM 的关联属性","d":"ex08 实跑：5 个作者的嵌套写法发 6 次查询（1+N），JOIN 写法发 1 次，两者结果完全相同（same_result=true）。 用操作计数（而非代码观感）判定 N+1，修复用 JOIN 或 WHERE fk IN (...) 批量合并，并断言修复后返回数据一致。"},{"h":"用 GET 触发有副作用的操作","d":"GET 是安全方法，会被浏览器预取、代理缓存、爬虫抓取，一个 GET /orders/42/cancel 可能被批量触发。 有副作用用 POST；状态变更优先设计成对资源的 PATCH/PUT（如 {\"status\":\"cancelled\"}）。"},{"h":"POST 用来更新、PUT 用来打补丁","d":"PUT 的语义是整体替换（缺失字段应被清空或整体校验失败），PATCH 才是部分更新。 按 RFC 9110 的方法语义分配：PUT 全量、PATCH 部分、POST 在集合下创建并返回 201 + Location。"}],"asks":[{"q":"关系型（PostgreSQL/MySQL）和文档型（MongoDB）你会怎么选？给出可辩护的判据。","a":"先看四个维度：① 一致性约束强度——需要外键、CHECK、多表事务原子性时关系型更强；② 访问模式——需要任意 JOIN/聚合报表选关系型，一次读一个聚合根（含嵌套结构）选文档型；③ schema 演进——需显式受控迁移选关系型，单文档加字段即可；④ 水平扩展——原生分片选文档型，但 shard key 决定成败。 核心判据是一句话：一次业务操作能否落在同一个聚合根/文档内。能，文档型可行；不能…","fu":["什么情况下你会把已经用了 PostgreSQL 的系统迁到文档型？","MongoDB 的多文档事务代价在哪里？"],"tag":"通用/阿里"},{"q":"为什么数据库索引用 B+ 树，而不是二叉搜索树、哈希表或跳表？","a":"先明确度量：磁盘以页为 IO 单位，衡量的是页读取次数而不是比较次数。 - 二叉搜索树 h = log2(n)，亿级数据要二十多次页读，每次都是随机 IO，不可接受。 - B+ 树的内部节点只存分隔键和子指针，一个页能容纳几百个分支，把 h 压到 3~4；同时叶子层用链表串联，范围查询定位起点后是顺序 IO。 - 哈希索引只支持等值，不支持范围与排序（B+ 树天然支持）。 - 跳表是内存结构，没有…","fu":["B 树和 B+ 树的四点差异是什么？","为什么 B+ 树删除时内部节点的分隔键可以不删？"],"tag":"通用/腾讯"},{"q":"线上一条 SQL 变慢了，你怎么排查？说说最左前缀和覆盖索引。","a":"排查顺序：① 拿到真实 SQL（ORM 项目先打开 SQL 日志，抄出生成语句）；② 跑 EXPLAIN / EXPLAIN QUERY PLAN，看是 SCAN 还是 SEARCH ... USING INDEX；③ 看 select 列表是否涉及索引外列（决定是否回表）；④ 看 WHERE 的列序是否满足最左前缀。 最左前缀：复合索引 (a, b) 只在「先按 a 有序、a 相同才按 b 有序…","fu":["为什么 where 里对索引列做函数运算会让索引失效？","联合索引里加一个范围条件后，后面的列还能用于排序吗？"],"tag":"通用/字节"},{"q":"什么是 N+1 查询？怎么发现、怎么修、怎么验收？","a":"定义：取到「1」个列表后，对列表里 N 个元素各发一次查询取关联数据，总查询数 1+N。 发现：不能靠代码观感，要靠操作计数。本章 ex08 把 db 调用包了计数器：5 个作者的嵌套写法 6 次查询（1+N），JOIN/批量写法 1 次。这个数字可以写成单测断言（列表接口 DB 调用不超过 3 次）在 CI 里挡住回归。线上可看 APM 里同名 SQL 的调用次数是否与返回条数同阶。 修复（按优…","fu":["JOIN 和两段式查询怎么选？","DataLoader 需要处理哪两个边界情况？"],"tag":"通用/字节"}]},{"id":"fs-ch06","subj":"fullstack","title":"用户认证 / JWT / 鉴权","summary":"会话与令牌机制；JWT 结构与签发校验；密码哈希（bcrypt）；中间件鉴权；OAuth2/第三方登录概览；CSRF/XSS 防护基础。","concepts":[{"id":"fs-ch06/01-authn-authz-session-vs-token","file":"01-authn-authz-session-vs-token.md","title":"fs-ch06 · 一、认证 vs 鉴权；会话与令牌机制","kind":"compare","secs":[{"h":"一、认证（Authentication）与鉴权（Authorization）","s":"认证回答「你是谁」（把声称的身份与已验证的凭证绑定）；鉴权回答「你能做什么」（在策略空间里对一次访问请求求值）。一次请求是「先认证、再鉴权、最后落到资源」的三段流水线，任一环节失败都要返回不同的状态码——这是本章所有示例的地基。","c":{"lang":"text","code":"请求 -->[认证中间件]--401--> 拒绝（无/坏凭证）\n              |通过\n              v\n        [授权中间件]--403--> 拒绝（凭证有效但无权）\n              |通过\n              v\n      [资源级校验]--404/403-> 拒绝（不是你的资源）\n              |通过\n              v\n…"}},{"h":"二、会话（Session + Cookie）与令牌（Token）机制","s":"两种把「登录状态」跨越无状态 HTTP 的方案：","c":null}]},{"id":"fs-ch06/02-jwt-structure-and-signing","file":"02-jwt-structure-and-signing.md","title":"fs-ch06 · 二、JWT 三段结构与签名算法","kind":"compare","secs":[{"h":"一、JWT 三段结构与签名算法（HS256 vs RS256）","s":"JWT（RFC 7519）是一串 A.B.C：","c":{"lang":"text","code":"A = base64url( {\"alg\":\"HS256\",\"typ\":\"JWT\"} )      # header：算法与类型\nB = base64url( {\"sub\":\"u1\",\"role\":\"user\",\"exp\":...} )  # payload：claims\nC = base64url( HMAC-SHA256(secret, A + \".\" + B) ) # signature：对 A.B 的签名\n\ntoken = A + \".\" + B + \".\" + C"}},{"h":"二、校验清单与 alg:none / 算法混淆攻击","s":"一段「只验签名」的代码是不够的。上线前的 JWT 校验清单：","c":null}]},{"id":"fs-ch06/03-jwt-defects-password-storage","file":"03-jwt-defects-password-storage.md","title":"fs-ch06 · 三、JWT 固有缺陷与缓解；密码存储","kind":"stack","secs":[{"h":"一、JWT 无法主动失效（固有缺陷）与缓解","s":"无状态凭证的定义性代价：签发之后、过期之前，服务端无法单方面让它失效。用户点「退出登录」，前端删掉 token 只是本地行为；有人把旧 token 复制出来，照样通过验签。","c":{"lang":"text","code":"① 短 TTL access token（5~15 min）  -> 把「失效窗口」压小\n② Refresh token 单次使用 + 轮换     -> 旧 refresh 一旦被重放 -> 整族吊销\n③ jti 黑名单（内存/Redis）+ TTL      -> 需要「立即失效」的高价值 token 才进黑名单"}},{"h":"二、密码存储：bcrypt / scrypt / argon2 的加盐与成本","s":"口令不能「存明文」，也不能「用可逆加密存」——一旦库泄露，可逆即等于明文。正确做法是加盐 + 慢哈希：","c":{"lang":"text","code":"stored = H(password, salt, cost)      # salt 每用户随机、随哈希一起存\nverify : H(input_pw, stored_salt, stored_cost) == stored_hash   # 常量时间比较"}}]},{"id":"fs-ch06/04-middleware-oauth2-csrf-xss","file":"04-middleware-oauth2-csrf-xss.md","title":"fs-ch06 · 四、中间件鉴权与权限模型；OAuth2、CSRF/XSS 与常见漏洞","kind":"flow","secs":[{"h":"一、中间件鉴权链与 RBAC / ABAC","s":"鉴权是一个链式职责：每个中间件要么判定通过（返回空），要么短路返回一个响应（401/403）：","c":{"lang":"text","code":"authenticate(ctx)             -> 无/坏凭证: 401, 并把 ctx.user 挂上\nauthorize(\"article:write\")    -> 已认证但无权: 403\nresourceGuard(ctx, article)   -> 不是你的资源: 404（隐藏存在性）\nhandler(ctx)                  -> 200"}},{"h":"二、OAuth2 授权码 + PKCE，CSRF/XSS 与常见漏洞","s":"OAuth2（RFC 6749）是授权框架，不是认证协议。授权码流程（第三方登录骨架）：","c":{"lang":"text","code":"客户端 --重定向--> 授权服务器  (带 client_id, redirect_uri, state, code_challenge)\n用户登录并授权\n授权服务器 --回调--> 客户端   (带 code, state)\n客户端后端 --POST code + code_verifier--> 授权服务器换取 access_token"}}]},{"id":"fs-ch06/05-jwt-in-practice","file":"05-jwt-in-practice.md","title":"认证实战：签发、校验、撤销与防护","kind":"flow","secs":[{"h":"一、Token 结构与校验流程","s":"","c":{"lang":"text","code":"header.payload.signature\n│      │        └── HMAC-SHA256(base64url(header) + \".\" + base64url(payload), secret)\n│      └─────────── Claims：sub(用户) exp(过期) iat(签发) jti(唯一 id) aud/iss(受众/签发者)\n└────────────────── alg:HS256 / RS256\n\n校验五步：\n1) 取 Authorization: Bearer <token>（或 HttpOnly Cookie）\n2) 拆三段，base64url 解出 header/payload（**不要**在这里信任任何字段）\n3) 验签：用密钥重算签名比对（HS256 用 secret，RS256 用公钥）\n…"}},{"h":"二、签发与校验（HS256 示例）","s":"","c":{"lang":"js","code":"const crypto = require('node:crypto');\n\nconst SECRET = process.env.JWT_SECRET;          // 至少 32 字节随机\nconst TTL = '15m';\n\nconst b64u = (buf) => Buffer.from(buf).toString('base64url');\n\nfunction sign(payload, { expiresIn = TTL, secret = SECRET } = {}) {\n  const now = Math.floor(Date.now() / 1000);\n…"}},{"h":"三、登出即失效：给\"无状态\"补上状态","s":"","c":{"lang":"js","code":"// 令牌版本号：用户改密码/封禁时 +1，旧令牌全部作废（不用逐条存黑名单）\nasync function issueTokens(user, store) {\n  const tokenVersion = await store.getTokenVersion(user.id);\n  const access = sign({ sub: user.id, name: user.nickname, tv: tokenVersion });\n  const refresh = sign({ sub: user.id, kind: 'refresh', tv: tokenVersion }, { expiresIn: '30d' });\n  // 刷新令牌只存哈希，落库/Redis\n  await store.saveRefreshHash(user.id, hash(refresh));\n  return { access, refresh };\n}\n…"}},{"h":"四、Cookie 与 CSRF：状态变更接口的双保险","s":"","c":{"lang":"js","code":"// 写 token 时三个属性齐全：HttpOnly(JS 读不到) + Secure(只走 https) + SameSite\nres.cookie('access', accessToken, {\n  httpOnly: true,\n  secure: true,\n  sameSite: 'strict',        // 同站才带 → 跨站 POST 默认不带 Cookie\n  maxAge: 15 * 60 * 1000,\n  path: '/',\n});\n\n…"}},{"h":"五、XSS 侧的兜底：输出编码与 CSP","s":"","c":{"lang":"js","code":"// 1) 前端渲染一律用文本节点，别拼 HTML\nfunction renderUserName(el, name) {\n  el.textContent = name;          // ✅ 自动转义\n  // el.innerHTML = `<b>${name}</b>`;   // ❌ name 里带 <script> 就出事\n}\n\n// 2) 服务端给严格 CSP：禁止内联脚本、禁止外部源\nconst csp = [\n  \"default-src 'self'\",\n…"}},{"h":"🧑‍💻 程序员视角","s":"JWT 是无状态的，签发后无法单方面作废——「登出即失效」必须补状态：维护一个短 TTL 的黑名单（Redis），或用「短 access token + 长 refresh token + 版本号」。alg: none 攻击是老问题，校…","c":null},{"h":"🎓 博士生视角","s":"JWT 的安全性建立在「签名不可伪造」上，它提供的是「完整性 + 认证」，不提供机密性——payload 是 Base64 编码而非加密，任何人都能解开看。因此敏感信息不能放进去。无状态令牌与「可撤销」本质冲突：要撤销就必须引入服务端状…","c":null},{"h":"📚 考研者视角","s":"全栈面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"401 与 403 的语义边界","stem":"一个已登录用户（token 合法）请求 DELETE /articles/42，但缺少 article:delete 权限。服务端应返回哪个状态码，为什么？","opts":[{"k":"A","t":"401，因为用户无权执行该操作"},{"k":"B","t":"403，因为凭证有效但授权不足"},{"k":"C","t":"400，因为请求非法"},{"k":"D","t":"500，因为服务端无法处理"}],"ans":"B","why":"401 Unauthorized 的真实含义是「未认证」（缺或坏的凭证，须带 WWW-Authenticate）；403 Forbidden 才是「已认证但无权」。本例凭证合法、仅权限不足，故为 403。本章 ex11 实跑 valid_but_no_perm status=403。"},{"kind":"choice","q":"Session 与 JWT 在「主动失效 / 水平扩展」上的取舍","stem":"关于 Session + Cookie 与 JWT 的对比，下列说法正确的是：","opts":[{"k":"A","t":"JWT 天然支持服务端即时撤销，Session 不行"},{"k":"B","t":"Session 可即时撤销但需共享会话存储，JWT 无需共享状态但无法主动失效"},{"k":"C","t":"两者都把状态存在客户端，因此都能水平扩展"},{"k":"D","t":"JWT 的内容是加密的，所以可以安全地存放敏感信息"}],"ans":"B","why":"Session 状态在服务端，撤销即时，但多实例要共享存储（Redis）或粘性会话；JWT 状态在客户端（自包含），验签即可横向扩展，但签发后到 exp 之前无法主动失效（缓解见 concept/03）。C 错在 Session 状态不在客户端；D 错在 JWT 只是 base64url 编码，不是加密。"},{"kind":"output","q":"判读一个 JWT 的结构与可读性","stem":"给定 token： eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiJ1MSIsInJvbGUiOiJ1c2VyIn0.3vJ2hSk9m2Q1w0k1h0d9yQ6m9hK0qz6m4x9y3k2w1q8 请写出：① 段数（segments）；② header 解码后的 alg 值；③ payload 解码后的 role 值；④ payload 是否…","opts":[],"ans":"segments=3 alg=HS256 role=user payload_readable_without_key=yes","why":"JWT 恒定三段 header.payload.signature；前两段是 base64url 编码（不是加密），任意人无需密钥即可解码。本章 ex01 实跑 token_segments=3、payload_is_readable_by_anyone=true。"},{"kind":"fix_error","q":"修复一个只验签名的 JWT 校验函数","stem":"下面的 verify_token 只比较了签名，缺少 alg 白名单、常量时间比较与 exp 校验。请修复它，使其能被 fs-ch06 的校验清单检查通过，并给出被拒用例（过期 / alg 非白名单 / 签名错）。","opts":[],"ans":"import base64, hashlib, hmac, json SECRET = b'ch06-hidden-secret' ALLOWED_ALG = ('HS256',) def _b64url_dec(seg: str) -> bytes: return base64.urlsafe_b64decode(s…","why":"「只验签名」的校验器能被过期 token 与 alg:none token 打穿。补上四件事：段数、alg 白名单（服务端钉死）、常量时间比较、exp 校验。ex06 实跑显示补全后 expired/missing_exp 等用例全部被拒。"},{"kind":"coding","q":"用标准库实现 HS256 签发与验签（含正反用例）","stem":"用 Python 标准库（hmac / hashlib / base64）实现 HS256 的 sign 与 verify：base64url(header).base64url(payload).base64url(HMAC-SHA256)。要求演示四组结果：正例通过；篡改 payload 被拒；alg 改为 none 被拒；换密钥被拒。","opts":[],"ans":"import base64, hashlib, hmac, json SECRET = b'ch06-demo-secret-key' def b64url(data: bytes) -> str: return base64.urlsafe_b64encode(data).rstrip(b'=').decode('a…","why":"HS256 的签名对象是 header.payload 的原始 base64url 串，验证方必须用原串重建 signing input。四种被拒情形分别覆盖：篡改（完整性）、alg:none（算法降级）、错密钥（真实性），加上 exp 的语义校验。"},{"kind":"coding","q":"实现加盐慢哈希并校验（bcrypt 的标准库替代）","stem":"bcrypt 非 Python 标准库，请用 hashlib.pbkdf2_hmac 实现 hash_password 与 verify_password（固定盐以输出确定）。要求：① 同一密码不同盐得到不同哈希；② 正确密码校验通过、错误密码不通过；③ 校验用常量时间比较。","opts":[],"ans":"import hashlib, hmac ITERATIONS = 120000 def hash_password(password: str, salt: bytes, iterations: int = ITERATIONS) -> bytes: return hashlib.pbkdf2_hmac('sha25…","why":"加盐（每用户唯一、可公开）解决预计算与「同密码可见」；迭代成本（此处 12 万次）把每次猜测的代价抬高，抵抗离线暴力。校验用 hmac.compare_digest 防时序侧信道（对应 ex10）。工程里应换成 bcrypt/scrypt/argon2 并让成本可升级。"},{"kind":"coding","q":"LeetCode 146 · LRU 缓存（token 黑名单 / 会话存储的底层结构）","stem":"实现一个满足「容量上限 + O(1) 读取与写入」的 LRU 缓存。它与本章的 token 黑名单、会话存储直接相关：撤销列表需要按容量淘汰最久未用项，避免无限膨胀。题面与约束以官方为准，详见 external_url，此处不复述题面正文。","opts":[],"ans":"# 用 dict（保持插入序）+ move_to_end 实现 O(1) LRU from collections import OrderedDict class LRUCache: def __init__(self, capacity: int): self.cap = capacity self.data =…","why":"哈希表（O(1) 定位）+ 双向链表（O(1) 调整顺序）是 LRU 的标准结构；Python 的 OrderedDict 把两者合并。映射到本章：jti 黑名单与 refresh 存储都需要「有容量上限、按最近使用淘汰」的语义（ex08 用 TTL 做时间维度的淘汰）。"},{"kind":"coding","q":"GitHub 算法补充 · 凯撒密码（古典密码为何不安全）","stem":"实现凯撒密码的加密与解密（按固定位移循环平移字母）。它的意义是反例：密钥空间只有 25，穷举即刻破解——这正是为什么现代密码存储必须用「加盐 + 慢哈希」，而不能依赖任何「可逆位移」。题面与实现参考见 external_url，此处不复述第三方题面正文。","opts":[],"ans":"function caesarCipher(text, shift) { const s = ((shift % 26) + 26) % 26; let out = ''; for (const ch of text) { const code = ch.charCodeAt(0); if (code >= 65 &&…","why":"凯撒密码是双射替换，密钥空间 26（有效 25）。穷举 25 次即可还原明文——这演示了「安全必须来自计算难度，而非算法保密」。对照本章：密码存储靠「加盐 + 可调成本的慢哈希」制造计算难度，JWT 签名靠 HMAC/非对称签名的计算难度。"}],"works":[{"h":"把「认证」和「鉴权」混为一谈，失败码一律 401","d":"无凭证/坏凭证应是 401（并在响应带 WWW-Authenticate），凭证有效但权限不足应是 403。 按 ex11 的链式职责分流：no_token/bad_scheme → 401，valid_but_no_perm → 403，valid_with_perm → 200；前端据此分别「跳登录」与「提示无权限」。"},{"h":"只做接口级鉴权，不做资源级校验（水平越权 / IDOR / BOLA）","d":"「用户有 article:write 权限」不代表「这条 article 是他的」。 在授权中间件之后再加资源级校验：比对 resource.ownerId === actor.id；ex12 中 editor_delete_others=false、editor_delete_own=true 正是这条规则。越权是 OWASP AP…"},{"h":"JWT 校验只验签名，不验 exp/nbf/aud/iss","d":"签名只保证「没被篡改」，不保证「没过期」「不是别家签发的」。 上全清单：段数、alg 白名单、常量时间验签、exp、nbf、aud、iss。ex06 实跑：expired、nbf_future、aud_wrong、iss_wrong、missing_exp 全部被拒。"},{"h":"让 token 头里的 alg 决定验签算法（或接受 alg: none）","d":"等于把安全决策参数交给攻击者。 alg 由服务端写死/白名单；ex05 中朴素实现 alg_none_naive_accepts=true 被打穿，安全实现 alg_none_secure=alg-pinned-reject。"},{"h":"算法混淆：用 RS256 的公钥去验 HS256 的签名","d":"攻击者把「公钥字符串」当 HMAC 密钥自签一个 alg=HS256 的 token，按 token 头选算法的实现会验签通过。 把 alg 钉死为 RS256 并绑定密钥类型；ex05 pinned_alg_blocks_confusion=true。"},{"h":"以为 JWT 是加密的，往 payload 里塞敏感信息","d":"base64url 只是编码，任何人 split('.') 后即可解码前两段。 敏感数据不入 payload，或改用 JWE（加密）；ex01 payload_is_readable_by_anyone=true 就是反证。"},{"h":"明文 / 可逆加密 / MD5 / SHA1 / 单轮 SHA256 存密码","d":"库一泄露就等同明文；快速哈希在 GPU 上每秒数十亿次。 用 bcrypt/scrypt/argon2（或 PBKDF2）加盐 + 可调成本；ex09 演示 PBKDF2 加盐（same_password_diff_salt_same_hash=False）。"},{"h":"密码哈希不加盐，或全站共用一个盐","d":"相同密码产生相同哈希，彩虹表与「撞库可见」双双失效。 每用户随机唯一盐，随哈希一起存（盐不需要保密）；ex09 用两个不同盐演示同密码得到完全不同的哈希。"}],"asks":[{"q":"认证和鉴权有什么区别？Session 和 JWT 你怎么选？","a":"认证回答「你是谁」，鉴权回答「你能做什么」。一次请求是一条链：认证（无/坏凭证 → 401）→ 授权（凭证有效但无权 → 403）→ 资源级校验（不是你的资源 → 403/404）→ handler（200）。注意 401 的真实含义是「未认证」且必须带 WWW-Authenticate，403 才是「已认证但禁止」。 Session vs JWT 看三个维度： - 状态位置：Session 状态…","fu":["多实例部署下 Session 共享有哪些方案，各自的代价是什么？","如果必须用 JWT，你会怎么设计登出？"],"tag":"通用/字节"},{"q":"讲一下 JWT 的结构。HS256 和 RS256 怎么选？","a":"JWT 是 base64url(header).base64url(payload).base64url(signature) 三段，前两段是 base64url 编码（不是加密），任何人解码就能读到内容——所以别往里塞敏感信息，要保密就用 JWE。 签名只对前两段的原始串计算：signature = HMAC-SHA256(secret, A + '.' + B)。验证方必须用原始 base64…","fu":["为什么 JWT 用 base64url 而不是标准 base64？","JWKS 和 kid 是干什么的？"],"tag":"通用/腾讯"},{"q":"JWT 有哪些常见漏洞？alg:none 和算法混淆是怎么回事？","a":"常见漏洞：① alg:none；② 算法混淆（RS256→HS256）；③ 密钥硬编码/弱密钥；④ 未校验 exp/aud/iss；⑤ 把敏感信息放 payload。 alg:none：攻击者把 header 改成 {\"alg\":\"none\"}、签名段留空。任何「按 token 头里的 alg 选算法」或「alg 为 none 就放行」的实现直接被打穿。本章 ex05 实跑：朴素实现 alg_no…","fu":["为什么验签要用常量时间比较？","aud 和 iss 不校验会有什么后果？"],"tag":"通用/字节"},{"q":"JWT 无法主动失效，这个缺点怎么办？","a":"这是无状态凭证的定义性代价：签发之后、过期之前，服务端无法单方面让它失效。用户点登出只是前端删 token，旧 token 复制出来照样能用。 缓解三件套： 1. 短 TTL access token（5~15 分钟）——把「失效窗口」压小，成本为 0。 2. Refresh token 单次使用 + 轮换——每次刷新签发新的 refresh 并作废旧的；一旦检测到旧 refresh 被重放，说明…","fu":["黑名单存 Redis 挂了怎么办？","TTL 设多短合适，怎么权衡？"],"tag":"通用/阿里"}]},{"id":"fs-ch07","subj":"fullstack","title":"全栈项目实战（GitHub 资源驱动）","summary":"综合运用前端框架 + Node 后端 + 数据库，完成一个完整全栈应用；组件/接口联调；状态管理与数据流转；以 GitHub 真实开源项目为参考范式。","concepts":[{"id":"fs-ch07/01-architecture-contract-first","file":"01-architecture-contract-first.md","title":"fs-ch07 · 一、全栈分层、目录组织与契约优先","kind":"stack","secs":[{"h":"一、分层与目录组织：前端 / 后端 / 共享类型","s":"全栈工程的第一性问题不是「用什么框架」，而是依赖方向。一个能长期演进的全栈仓库，目录结构应当把「谁可以 import 谁」编码进物理布局：","c":{"lang":"text","code":"repo/\n├── apps/\n│   ├── web/            前端应用：视图层 + 客户端状态（可依赖 shared / contract）\n│   └── api/            后端服务：路由 + 领域逻辑 + 持久化（可依赖 shared / contract）\n├── packages/\n│   ├── shared/         共享纯逻辑：类型、校验函数、领域常量（零 IO、零框架）\n│   └── contract/       OpenAPI 文档 + 由它生成的前端类型与服务端校验器\n├── pnpm-workspace.yaml\n└── README.md"}},{"h":"二、契约优先：OpenAPI 驱动、类型生成与边界校验","s":"契约优先（contract-first / design-first）把顺序倒过来：先定义接口，再各自实现。一个最小可用的契约包含四件事：","c":{"lang":"text","code":"req_ok_all_pass=true (2)                       # 合法请求体全部通过\nreq_bad_all_rejected=true (6/6)                # 非法请求体全部被拒\nreq_missing_title=$.title: required\nreq_bad_pattern=$.status: must match ^(draft|published)$\nreq_bad_float=$.score: expected integer\nreq_bad_max=$.score: maximum is 100\nreq_bad_extra=$.extra: additional property not allowed\nres_ok_all_pass=true (1)                       # 合法响应体通过\nres_bad_all_rejected=true (2/2)                # 非法响应体被拒（服务端自\n…"}}]},{"id":"fs-ch07/02-state-management-data-flow","file":"02-state-management-data-flow.md","title":"fs-ch07 · 二、状态管理与数据流转","kind":"compare","secs":[{"h":"一、服务端状态 vs 客户端状态","s":"把所有状态一锅端进全局 store，是全栈应用最常见的架构错误。正确的第一步是分类：","c":{"lang":"text","code":"renders_after_3_actions=3          # 3 次 dispatch -> 3 次订阅通知\nunknown_action_keeps_identity=true # default 分支返回同一引用 -> 不触发重渲染\nrenders_after_noop_action=3        # 因为 identity 未变，订阅者没有被通知"}},{"h":"二、数据流转：缓存失效、乐观更新与列表合并","s":"服务端状态进入前端后的三段式生命周期：获取 → 变更 → 合并回缓存。每一步都有对应的正确性难点。","c":{"lang":"text","code":"sent_while_inflight=1          # 3 个并发请求同一 key，只发了 1 次\ndeduped_flags=false,true,true  # 第 1 个真实发出，后两个复用\ndelivered=data:u:1             # 结算后正确投递\ninflight_after_settle=0        # 结算后从表中移除，允许下次重新获取\nsent_after_settle=2            # 结算后再请求 -> 重新发（这是正确的，缓存已失效）\ncancel_ok=true\ncancelled_settled=true         # 取消的请求仍会结算，但\ncancelled_result=null          # 不投递任何结果\ncancel_twice=false             # 重复取消无副作用"}}]},{"id":"fs-ch07/03-components-forms-errors","file":"03-components-forms-errors.md","title":"fs-ch07 · 三、组件化与组合、表单校验与错误处理","kind":"flow","secs":[{"h":"一、组件化与组合：受控/非受控、状态提升、Context 与 props drilling","s":"组件之间传递状态有四种手段，选错会分别带来「行为诡异」「prop 地狱」「无谓重渲染」三类问题：","c":null},{"h":"二、表单与校验：前后端双重防线","s":"表单校验必须两处都做，且它们的职责完全不同：","c":{"lang":"text","code":"validate(schema, value) -> errors[]        # 每个 error 带字段路径（$.field）"}},{"h":"三、错误处理与三态呈现：loading / empty / error / success","s":"数据驱动视图有四种状态，缺一个都是 bug：","c":{"lang":"text","code":"happy=loading->success\nempty=loading->empty                                    # 成功但 items 为空 -> empty\nerror_then_retry=loading->error->loading->success        # 错误可重试回到 loading\nretry_ignored_when_ok=loading->success->success          # 非错误态下 RETRY 不改变状态\nerror_message_kept=boom                                  # 错误信息随状态保留，供 UI 展示"}}]},{"id":"fs-ch07/04-performance-a11y-reading-oss","file":"04-performance-a11y-reading-oss.md","title":"fs-ch07 · 四、性能、可访问性与「读得懂大厂源码」","kind":"timeline","secs":[{"h":"一、性能：懒加载与代码分割、列表虚拟化、请求去重与取消","s":"前端性能优化分两类：少做事（少渲染、少请求、少字节）与晚做事（延迟到需要时）。四把常用刀：","c":{"lang":"text","code":"lazy_chunks=PostList,CommentBox    # props.defer=true 的组件是分割点\ntotal_nodes=9"}},{"h":"二、可访问性基础：把语义做成默认","s":"可访问性（a11y）不是「给残障用户的附加功能」，而是结构化语义的副产品。基础四件事，覆盖 80% 的常见问题：","c":{"lang":"text","code":"a11y_violations=2\nrules=img-alt,button-name\nimg_alt_violation=true        # <img> 缺 alt\nbutton_name_violation=true    # 图标按钮既无 aria-label 又无文本内容"}},{"h":"三、读得懂大厂源码：入口 → 路由 → 数据层 → 组件树","s":"拿到一个陌生的开源全栈仓库，高效的阅读顺序是沿着数据流走一遍，而不是从文件树里随机点开：","c":{"lang":"text","code":"① 入口（entry）        看 app 如何启动、注册了什么全局能力（路由、状态、请求客户端、错误边界）\n      ↓\n② 路由（routes）       看有哪些页面、路径与组件的映射、有无布局嵌套与鉴权守卫\n      ↓\n③ 数据层（data）       看请求客户端封装、缓存 key 设计、鉴权注入、错误映射\n      ↓\n④ 组件树（components） 看状态如何在组件间流动、哪些是受控、哪些用 Context\n      ↓\n⑤ 契约与类型（types/contract） 回头用类型反查「这个字段从哪来、到哪去」"}}]}],"exams":[{"kind":"choice","q":"下列哪一项属于「服务端状态」而非「客户端状态」","stem":"按本章「刷新页面后是否还需要从服务器重新获取」这一判据，下列哪一项最应被建模为服务端状态（交给缓存/数据层）？","opts":[{"k":"A","t":"当前打开的模态框是否可见"},{"k":"B","t":"用户刚在下拉框里选择的筛选条件"},{"k":"C","t":"文章列表（可被其他用户修改、随时可能过期）"},{"k":"D","t":"输入框中尚未提交的草稿文本"}],"ans":"C","why":"服务端状态的特征是「服务端是唯一事实来源、前端只持有可过期的副本」，需要 TTL/失效/去重/重试（本章 ex04/ex02/ex09）。A 弹窗可见性是纯 UI 状态；B 筛选条件与 D 草稿属于客户端状态，本地存活即可，刷新后无需从服务器恢复。"},{"kind":"choice","q":"为什么「空结果」必须是独立状态而不是 success 的分支","stem":"数据驱动视图有四态：loading / success / empty / error。关于 empty 为何要独立成态，下列说法哪一项最准确？","opts":[{"k":"A","t":"empty 与 success 在信息论上等价，只是为了代码好看才拆开"},{"k":"B","t":"empty 对应的用户行为与 success 不同（需引导创建 / 更换筛选条件），合并会丢失这一信息"},{"k":"C","t":"empty 状态一定意味着请求失败，必须显示错误"},{"k":"D","t":"empty 只能在服务端返回 404 时进入"}],"ans":"B","why":"empty 是「请求成功但结果为空」，用户需要的是「创建第一条 / 换个筛选条件 / 换个关键词」等引导，与有数据时的展示行为不同。状态粒度应等于「用户可区分的行为」粒度。本章 ex05 实跑 empty=loading->empty，与 success 是两条不同转移。empty 不是错误（C 错），也不是 404（D 错）。"},{"kind":"output","q":"写出虚拟化渲染窗口的区间","stem":"列表虚拟化配置：rowHeight = 40、viewportHeight = 400、total = 1000、overscan = 2。按公式 first = floor(scrollTop / rowHeight)、visible = ceil(viewportHeight / rowHeight)、start = max(0, first - overscan)、end = min(tot…","opts":[],"ans":"start=98 end=112 count=14 offsetY=3920","why":"first = floor(4000/40) = 100；visible = ceil(400/40) = 10；start = max(0, 100-2) = 98；end = min(1000, 100+10+2) = 112；count = 112-98 = 14；offsetY = 9840 = 3920。本章 ex07 实跑输出 mid=start=98 end=11…"},{"kind":"fix_error","q":"修复 reducer：未知 action 导致的无谓重渲染","stem":"下面的 reducer 在 default 分支返回了新对象，导致任何未知 action 都会让订阅者被通知（多余重渲染）。请修复它，使「未知 action 不触发通知」，并打印修复前后各自的通知次数。","opts":[],"ans":"// 有 bug 的 reducer：default 分支返回新对象 -> 未知 action 也触发重渲染 function badReducer(state, action) { switch (action.type) { case 'ADD': return { ...state, todos: [...sta…","why":"{ ...state } 会创建一个引用不同的新对象，破坏「引用剪枝」——订阅者据此判定「状态变了」而重渲染。修复是在 default 分支原样返回旧引用 return state。对应本章 ex01 的 unknown_action_keeps_identity=true 与 renders_after_noop_action=3。不可变更新只用于真正发生变化的 action…"},{"kind":"coding","q":"实现 TTL + stale-while-revalidate 缓存并输出状态序列","stem":"用整数逻辑时钟（显式 advance，不读墙钟）实现 create_cache(ttl_ms, swr_ms)：read(key) 返回 fresh（age ≤ ttl）、stale（ttl < age ≤ ttl+swr，仍返回旧值）、expired（age > ttl+swr，返回 None）三态。要求打印 t0 / write 后 / t110 / t310 的状态与取值。","opts":[],"ans":"# TTL + stale-while-revalidate：用整数逻辑时钟给出 fresh/stale/expired 状态序列 def create_cache(ttl_ms, swr_ms): store = {} clock = {'now': 0} def advance(ms): clock['now']…","why":"缓存状态是三态而非二态：stale 仍返回旧值以支持「先给用户看、后台刷新」的丝滑体验，expired 才返回空。用整数逻辑时钟而非墙钟，保证输出确定可断言。对应本章 ex04 实跑：t50=fresh、t110=stale（value=v1）、t310=expired（value=null）。"},{"kind":"coding","q":"实现请求调度：优先级队列 + 最大并发上限","stem":"实现 createScheduler(maxConcurrent)：入队时指定优先级，调度时按「优先级降序、同优先级 FIFO」选择；任一时刻在飞任务数不得超过上限；任务完成后立即补位。要求打印峰值并发、完成顺序，并断言峰值不超限、全部完成。","opts":[],"ans":"// 请求调度：优先级队列 + 最大并发限制（峰值并发不超限，完成即补位） function createScheduler(maxConcurrent) { const waiting = []; const active = []; let seq = 0; let peak = 0; function admit…","why":"排序键为 (priority desc, seq asc)；admit() 在启动时与每次 completeOne() 后都被调用，从而把并发始终打满（而非等整批完成）。断言 peak_within_limit=true 是「上限不被突破」的可验证判据。对应本章 ex10：上限 2 时 peak_after_admit=2、完成顺序 b,d,c,e,a、max_concurre…"},{"kind":"coding","q":"GitHub 算法补充 · 二分下界（lower bound）","stem":"实现 lowerBound(nums, target)：在升序数组中返回第一个大于等于 target 的元素下标；不存在则返回数组长度。该变体是「有序集合中定位第一个不小于目标的位置」的通用工具，与虚拟化窗口定位起始行、游标分页定位起点同构。题面与参考实现见 external_url，此处不复述第三方题面正文。","opts":[],"ans":"// 二分下界：返回第一个 >= target 的下标；越界返回数组长度 // 参考实现见 trekhleb/javascript-algorithms 的二分查找章节（本题仅存元数据与链接） function lowerBound(nums, target) { let lo = 0; let hi = nums.l…","why":"区间取左闭右开 [lo, hi)，循环不变式为「答案始终落在 [lo, hi) 内」；mid 命中时收缩右界为 mid（不排除 mid），因此最终 lo 即下界。与标准二分（命中即返回）的区别在于不提前返回。对应本章 ex07 的 first = floor(scrollTop/rowHeight) 在有序行高下可用二分加速定位。"},{"kind":"coding","q":"LeetCode 146 · LRU 缓存（与本章缓存策略同构）","stem":"设计并实现一个 LRU（最近最少使用）缓存：get 与 put 均需 O(1)；容量满时淘汰最久未使用的键。题面与约束以官方为准，详见 external_url，此处不复述题面正文。","opts":[],"ans":"// LRU 缓存（哈希表 + 双向链表）：get/put 均 O(1) // 与本章「服务端状态缓存」同构：容量满时淘汰最久未使用项 class LRUCache { constructor(capacity) { this.capacity = capacity; this.map = new Map(); //…","why":"哈希表提供 O(1) 定位，双向链表提供 O(1) 的「移到最近使用 / 淘汰最久未使用」；命中后必须把节点移到链表头部。这与本章 ex04 的 TTL 缓存是同族但有区别：LRU 按访问时间淘汰、TTL 按写入时间过期；真实缓存常把两者叠加（先过期再按 LRU 淘汰）。"}],"works":[{"h":"把服务端状态和客户端状态一锅端进全局 store","d":"服务端状态是「可被他人修改、随时过期」的副本，需要 TTL/失效/去重/重试；客户端状态（弹窗开关、输入草稿）本地存活即可。 分两类：服务端状态交给专用数据层（本章 ex04 的 TTL/SWR、ex02 的去重取消、ex09 的分页合并），客户端状态用组件本地 state 或轻量 store（ex01）。判据一句话：「刷新页面后还要…"},{"h":"以为「状态变了才重渲染」是自动的","d":"只有引用变化才触发重渲染。若 reducer 的 default 分支返回新对象（如 {...state}），无意义的 action 也会通知订阅者。 未知 action 必须原样返回旧引用：本章 ex01 实跑 unknown_action_keeps_identity=true 且 renders_after_noop_actio…"},{"h":"乐观更新只写「成功路径」，不写回滚","d":"断网或 422 时，本地乐观插入的条目会永远停留在「待同步」状态，用户看到幽灵数据。 乐观更新必须具备三件套：临时 id、失败回滚、并发有序结算。本章 ex03 用正反两组证明：成功 success_count_kept=true（保留且 id 由 tmp-1 变 101），失败 after_rollback_count=0 且 fa…"},{"h":"并发请求同一资源重复发出、且不取消过期请求","d":"既不省带宽，又会「竞态覆盖」：先发的慢请求后到，把新数据覆盖回旧值（搜索框输入 a→ab 的经典 bug）。 in-flight map 去重 + 取消过期请求。ex02 实跑：3 个并发同 key 只发 1 次（sent_while_inflight=1，deduped_flags=false,true,true），取消的请求 ca…"},{"h":"把 TTL 缓存当成二态（命中/未命中）","d":"漏掉 stale 这一态，就无法实现「先给旧值、后台刷新」的丝滑体验，只能白屏等待。 三态建模：fresh（直接可用）、stale（先给旧值 + 后台刷新）、expired（返回空）。ex04 用整数逻辑时钟给出精确边界：ttl=100, swr=200 时 t50=fresh、t110=stale（t110_value_served…"},{"h":"无限滚动只做「追加」，不做「去重 + 稳定排序」","d":"网络乱序到达时，第 2 页可能与第 1 页重叠（并发写入或重复触发加载），表现为列表里出现重复项或顺序错乱。 合并层必须幂等 + 可交换。ex09 实跑：乱序到达（p3,p1,p2）合并后 out_of_order_ids=1,2,3,4,5 且 order_stable=true；重叠页去重后 merged_count=4（raw_…"},{"h":"嵌套结构直接在组件里消费，不归一化","d":"同一条用户数据在 N 条记录里出现 N 次，改一次要改 N 处（更新异常），且深比较成本高。 normalize 成实体表 + id 索引。ex08 实跑：3 条 post 携带 3 份 author，归一化后 normalized_user_count=2、dedup_saved=1，且还原无损 roundtrip_equal=tr…"},{"h":"把高频变化的值（输入框内容）放进 Context","d":"Context 变化会广播给所有消费者，导致整棵树每次按键都重渲染，主线程卡顿。 Context 只放低频环境值（主题、语言、当前用户）；高频值用组件本地 state，或按关注点拆分多个 Context，或引入支持选择器的外部 store。"}],"asks":[{"q":"一个全栈项目，你会怎么组织目录？为什么共享类型要从契约生成而不是手写？","a":"按依赖方向组织，而不是按文件类型：apps/web（前端）、apps/api（后端）、packages/shared（纯逻辑）、packages/contract（OpenAPI 文档 + 生成物）。三条硬规则：① 依赖单向 apps/ → packages/，禁止反向依赖；② shared 只放纯逻辑（无 IO、无 fs/window），否则同一份代码无法在浏览器/Node/Edge 三套宿主里…","fu":["monorepo 与 multirepo 你怎么选？","循环依赖（反向依赖）在前端会产生什么具体故障？"],"tag":"通用/字节"},{"q":"服务端状态和客户端状态怎么区分？为什么不该塞进同一个全局 store？","a":"判据一句话：「刷新页面后它还需要从服务器重新获取吗？」 需要 → 服务端状态（文章列表、用户资料、订单），交给缓存/数据层；不需要 → 客户端状态（弹窗开关、输入草稿、当前 tab），本地存活即可。 为什么不能一锅端：服务端状态的本质是「分布式共享可变状态的本地副本」，天然需要处理过期、去重、重试、失效、乐观更新、分页合并——这些正是 TanStack Query / SWR / Apollo 存…","fu":["Context 为什么会造成大范围重渲染？怎么缓解？","归一化（normalize）解决的是什么问题？"],"tag":"通用/阿里"},{"q":"乐观更新怎么做？失败了怎么回滚？哪些场景不能用？","a":"三段式：先用临时 id 把变更本地生效（乐观），服务端返回后把临时 id 换成真实 id（确认），失败则移除（回滚）。三个必备部件：① 临时 id（不与真实 id 冲突）；② 可逆操作或快照（用于回滚）；③ 并发同一资源的多次乐观变更要有序结算（多个 tmp- 各自确认，不能假设最后一个成功的就是对的）。 回滚的正确性条件：本地先行的效果必须有可计算的逆操作。本章 ex03 实跑：成功时 afte…","fu":["乐观更新与幂等键怎么配合？","多个并发乐观变更如何有序结算？"],"tag":"通用/字节"},{"q":"列表页请求返回乱序，或者无限滚动出现重复项，你怎么根治？","a":"两个根因分开治： 乱序（竞态覆盖）：响应到达顺序 ≠ 请求发出顺序。先发的慢请求后到，会把新数据覆盖回旧值（搜索框输入 a→ab 的经典 bug）。解法：① AbortController 取消过期请求；② 用递增 seq 标记请求，只接受「最新请求」的响应；③ 去重（同一资源只发一次）。本章 ex02 实跑：3 个并发同 key 请求只发 1 次（sent_while_inflight=1），取…","fu":["去重、去抖、节流三者的区别？","游标分页会不会漏行？什么情况下会？"],"tag":"通用/腾讯"}]},{"id":"fs-ch08","subj":"fullstack","title":"部署 / CI-CD / Docker","summary":"Linux 与 SSH 基础；Docker 镜像与容器；Docker Compose 编排；GitHub Actions 流水线；环境变量与日志；基础监控与回滚。","concepts":[{"id":"fs-ch08/01-linux-ssh-process-logs","file":"01-linux-ssh-process-logs.md","title":"fs-ch08 · 一、Linux 服务器：SSH、进程管理与日志","kind":"flow","secs":[{"h":"一、SSH 与免密登录（含端口转发）","s":"SSH（Secure Shell，IANA 分配的默认端口 22）在不可信网络上提供加密的远程登录与文件传输。认证方式有密码与公钥两类；免密登录指的是公钥（publickey）认证：客户端持有私钥，服务端在 ~/.ssh/authori…","c":{"lang":"text","code":"ssh-keygen -t ed25519 -C \"deploy@ci\"        # 生成密钥对（私钥留在本机，永不外传）\nssh-copy-id -i ~/.ssh/id_ed25519.pub deploy@10.0.0.11"}},{"h":"二、进程管理：systemd / pm2 / supervisor","s":"三个常见选择的定位：","c":{"lang":"text","code":"[Unit]\nDescription=orders-api\nAfter=network-online.target\n\n[Service]\nUser=app\nExecStart=/usr/bin/node /srv/orders/dist/server.js\nRestart=on-failure\nRestartSec=2\n…"}},{"h":"三、日志：journalctl 与 logrotate","s":"Linux 上的日志有两条主线：systemd 的 journald 把各服务日志统一收进二进制 journal，用 journalctl 查询；logrotate 则负责把已有的文本日志按大小/时间轮转、压缩与清理。两者配合的典型形态…","c":{"lang":"text","code":"journalctl -u orders-api --since \"30 min ago\" -p err --no-pager\njournalctl -b -1 -p warning            # 上一次启动\njournalctl --disk-usage                # 当前占用\njournalctl --vacuum-size=500M          # 只保留 500M"}}]},{"id":"fs-ch08/02-docker-image-and-build","file":"02-docker-image-and-build.md","title":"fs-ch08 · 二、Docker 镜像、分层与构建优化","kind":"flow","secs":[{"h":"一、镜像分层、写时复制与构建缓存","s":"分层带来两个直接后果：","c":{"lang":"text","code":"=== deps_first (layers=6) ===\n  change=src/app.js     cached=4 rebuilt=2 npm_ci_layer_rebuild=False\n  change=package.json   cached=2 rebuilt=4 npm_ci_layer_rebuild=True\n=== copy_all_first (layers=5) ===\n  change=src/app.js     cached=2 rebuilt=3 npm_ci_layer_rebuild=True\n  change=package.json   cached=2 rebuilt=3 npm_ci_layer_rebuild=True\n=== judgement ===\nsource_edit_rebuilds_deps_first=2\nsource_edit_rebuilds_copy_all_first=3\n…"}},{"h":"二、多阶段构建与镜像瘦身","s":"本章 ex03 用层数与体积做纯计算：","c":{"lang":"text","code":"=== single_stage ===\n  base=node:22-bookworm 380.0MB\n  total_layers=5 image_size=963.0MB\n=== multistage_builder (中间阶段，不进最终镜像) ===\n  base=node:22-bookworm 380.0MB\n  total_layers=5 image_size=963.0MB\n  builder_stage_discarded=True\n=== multistage_runtime (最终镜像) ===\n  base=node:22-bookworm-slim 75.0MB\n…"}},{"h":"三、容器的隔离边界与 .dockerignore","s":"容器的隔离由两层机制叠加：namespace 决定「能看到什么」（PID、网络、挂载、UTS、IPC、user、cgroup 等命名空间），cgroup（v2 为统一层级）决定「能用多少」（CPU 权重与上限、内存上限、IO 限速）。容…","c":{"lang":"text","code":"patterns=node_modules **/*.log .git dist !dist/keep.txt *.md coverage/\n=== excluded (7) === node_modules/left-pad/index.js, logs/app.log, logs/2026/app.log, .git/HEAD, dist/bundle.js, README.md, coverage/lcov.info\n=== kept (4) === package.json, src/index.js, src/deep/nested/app.js, dist/keep.txt\nstar_does_not_cross_slash=True"}}]},{"id":"fs-ch08/03-compose-and-12factor","file":"03-compose-and-12factor.md","title":"fs-ch08 · 三、Docker Compose 编排与 12-Factor 配置","kind":"flow","secs":[{"h":"一、Docker Compose：服务依赖、网络、卷与健康检查","s":"compose.yaml 用一份声明描述多容器应用：services（各容器）、networks（自定义网络，服务名即 DNS 名）、volumes（具名卷，生命周期独立于容器）、env_file/environment（配置注入）。","c":{"lang":"yaml","code":"services:\n  db:\n    image: postgres:16.4\n    healthcheck:\n      test: [\"CMD-SHELL\", \"pg_isready -U app\"]\n      interval: 5s\n      timeout: 3s\n      retries: 10\n    volumes: [pgdata:/var/lib/postgresql/data]\n…"}},{"h":"二、12-Factor 与配置外置","s":"The Twelve-Factor App 的核心主张之一：配置是「会因部署环境而不同的东西」，必须与代码分离，外置到环境变量。十二因子包括：代码库（一份代码库多份部署）、依赖（显式声明并隔离）、配置（存环境变量）、后端服务（当作可替换…","c":{"lang":"text","code":"DATABASE_URL         source=env       ok\nLOG_LEVEL            source=file      ok_externalized_but_prefer_env\nPORT                 source=hardcoded VIOLATION_HARDCODED_CONFIG           src/server.js:12\nSTRIPE_SECRET_KEY    source=hardcoded VIOLATION_CRITICAL_HARDCODED_SECRET  src/pay.js:7\nDB_PASSWORD          source=hardcoded VIOLATION_CRITICAL_HARDCODED_SECRET  src/db.js:4\n=== summary ===\ncompliant=5 violations=3 critical=2\ncompliance_pct=62.5"}}]},{"id":"fs-ch08/04-cicd-release-and-observability","file":"04-cicd-release-and-observability.md","title":"fs-ch08 · 四、CI/CD 流水线、发布策略与可观测性","kind":"timeline","secs":[{"h":"一、CI/CD 流水线设计（GitHub Actions）","s":"GitHub Actions 的 workflow 是三层结构：workflow（一个 YAML 文件）→ job（默认并行，用 needs: 串行）→ step（顺序执行）。runs-on 指定 runner，on 声明触发条件，se…","c":{"lang":"yaml","code":"name: ci\non: [push, pull_request]\njobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:\n      - run: npm ci\n      - run: npm run build\n  test:\n…"}},{"h":"二、环境与发布策略：蓝绿、金丝雀、滚动与回滚","s":"发布策略的本质是「在切换流量时，如何控制风险与恢复速度」：","c":{"lang":"text","code":"=== canary ===\n  step  weight  new_version_users  share_pct  err_permille  action\n  0     5       107                5.35       0             continue\n  1     25      510                25.50      10            continue\n  2     50      1007               50.35      15            continue\n  3     100     2000               100.00     -             no_data\n=== blue_green ===\n  0     0       0                  0.00       0             continue\n  1     100    \n…"}},{"h":"三、监控、告警与日志聚合","s":"可观测性由三根支柱构成：metrics（可聚合、适合告警）、logs（信息密度高、适合定位）、traces（跨服务因果、适合延迟归因）。健康检查在编排层表现为探针：","c":{"lang":"text","code":"=== trip_then_recover probes=0000111 failureThreshold=3 successThreshold=2 ===\n  t=0 probe=0 consec_fail=1 state=healthy\n  t=1 probe=0 consec_fail=2 state=healthy\n  t=2 probe=0 consec_fail=3 state=unhealthy      ← 第 3 次失败才切换\n  t=5 probe=1 consec_fail=0 consec_ok=2 state=healthy\n  events=t2:became_unhealthy,t5:became_healthy\n=== flap_never_trips probes=101010 failureThreshold=3 successThreshold=2 ===\n  final_state=healthy                             ← 抖动永不触\n…"}}]}],"exams":[{"kind":"choice","q":"改一行源码会重建几层：deps-first 与 COPY . . 反模式对照","stem":"Dockerfile A 的顺序是 FROM → WORKDIR → COPY package.json package-lock.json ./ → RUN npm ci → COPY . . → RUN npm run build（共 6 层）；Dockerfile B 把 COPY . . 提前到 RUN npm ci 之前（共 5 层）。现在只修改 src/app.js 一行并重新构建（不…","opts":[{"k":"A","t":"A 重建 2 层且 npm ci 层命中缓存；B 重建 3 层且 npm ci 层被迫重跑"},{"k":"B","t":"A 重建 3 层；B 重建 2 层"},{"k":"C","t":"两者都只重建 1 层（只有 COPY . . 那一层失效）"},{"k":"D","t":"两者都会让全部层重建，因为构建缓存按整份上下文哈希"}],"ans":"A","why":"构建缓存是前缀链：某层失效则其后全部重建，因此「失效点之后的层数」就是重建层数。ex02 实测：A 的 COPY . . 是第 5 层，命中前 4 层、重建 2 层，且 npm_ci_layer_rebuild=False；B 的 COPY . . 是第 3 层，后面还有两条 RUN，命中 2 层、重建 3 层，且 npm_ci_layer_rebuild=True（最贵的依赖…"},{"kind":"choice","q":"12-Factor 视角下哪种做法违规","stem":"按 12-Factor 的「配置」因子，下列哪种做法属于违规（而不是「可接受但可改进」）？","opts":[{"k":"A","t":"把 LOG_LEVEL 放在外部配置文件 config/default.json，由代码读取"},{"k":"B","t":"把数据库连接串从环境变量 process.env.DATABASE_URL 读取"},{"k":"C","t":"把 STRIPE_SECRET_KEY 直接写在 src/pay.js 源码里"},{"k":"D","t":"把特性开关 FEATURE_NEW_UI 从环境变量读取"}],"ans":"C","why":"12-Factor 的「配置」指会因部署环境而不同的东西，必须与代码分离。环境变量是推荐形态（B、D 合规）；外部配置文件属于「已外置但不如环境变量」（A 记 ok_externalized_but_prefer_env，可接受）；写死在源码里是违规，若该项还是密钥则升级为 critical——因为密钥会随 Git 历史永久存在，且轮换前一直有效。ex11 对 C 这类项输出…"},{"kind":"output","q":"读探针时间线，写出状态切换时刻与终态","stem":"某容器配置 failureThreshold=3、successThreshold=2，探针序列（t 从 0 开始，1 表示成功）为 0000111，初始状态为 healthy。本章 ex08 实跑给出的时间线为： t=0 probe=0 consec_fail=1 state=healthy t=1 probe=0 consec_fail=2 state=healthy t=2 probe=0…","opts":[],"ans":"trip_tick=2 recover_tick=5 final_state=healthy recover_requires_consecutive_successes=2 (t=4 只有 1 次连续成功，未达 successThreshold=2)","why":"判定采用不对称阈值的滞回状态机：连续失败达到 failureThreshold 才降级（t=2 恰好第 3 次失败，索引从 0 起），连续成功达到 successThreshold 才恢复（t=5 是第 2 次连续成功）。t=4 只有 1 次连续成功，不足 2 次，因此仍为 unhealthy。ex08 的 trip_at_failure_threshold=True、sing…"},{"kind":"fix_error","q":"修复一个有 8 处问题的 Dockerfile","stem":"下面的 Dockerfile 被本章 ex01 的检查器报出 8 个问题，请逐条修复并说明依据（要求最终检查器输出 issues=0）。 FROM node:latest WORKDIR /app RUN apt-get update RUN apt-get install -y curl git ADD ./app.tar.gz /app COPY . . RUN npm install EXP…","opts":[],"ans":"# 修复后的 Dockerfile（对应 ex01 的 good 基准，检查器输出 issues=0） FROM node:22.11-bookworm AS build WORKDIR /app COPY package.json package-lock.json ./ RUN apt-get update &&…","why":"8 个问题与修复：① node:latest → 固定 node:22.11-bookworm；② apt-get update 与 install 拆成两条 RUN → 合并进同一条并在末尾清理 /var/lib/apt/lists/；③ 用 ADD → 改 COPY（除非需要自动解压 tar）；④ COPY . . 在 RUN npm install 之前 → 改为先 CO…"},{"kind":"coding","q":"实现 Compose 服务依赖的分层启动顺序求解","stem":"实现 start_order(services)：入参是 {服务名: [依赖服务名, ...]}，返回 (waves, error)，其中 waves 是按「同层可并发启动」分组的列表（每层内按名称字典序），error 在存在循环依赖时为非空字符串。要求对正常图与环形图各给一组结果，并打印判断量。","opts":[],"ans":"def start_order(services): deps = {n: list(d) for n, d in services.items()} waves, done = [], set() while len(done) < len(services): wave = sorted(n for n in se…","why":"每轮收集「所有依赖都已在 done 中」的服务作为一层，层内可并发启动；若某一轮收集不到任何服务而仍有未完成项，说明剩余子图无入度为零的顶点，即存在环——这正是 Kahn 拓扑排序的环判定。分层而非线性顺序是有意义的：层数等于最短启动批次（= 最长依赖链长度），同层服务可并行以缩短启动时间。ex07 实测：wave0=cache,db、wave1=api,worker、wave…"},{"kind":"coding","q":"实现健康检查的滞回状态机","stem":"实现 probe_events(probes, failure_threshold, success_threshold)：按整数 tick 依次消费布尔探针序列，返回 (final_state, events)，events 是在哪些 tick 发生了状态切换。要求演示三组：① 连续失败 3 次后降级；② 抖动序列（成功失败交替）永不触发；③ 恢复需要连续 2 次成功，单次成功不算。","opts":[],"ans":"def probe_events(probes, failure_threshold, success_threshold): state, fails, oks, events = \"healthy\", 0, 0, [] for i, ok in enumerate(probes): if ok: fails, ok…","why":"两个方向的阈值必须不对称（降级看连续失败、恢复看连续成功），任何一次反向探针都重置对应计数器——这就是滞回（hysteresis），作用是让抖动序列无法把状态推过阈值，避免反复重启与摘挂流量。注意 tick 从 0 开始：[False,False,False] 的降级发生在 t=2。ex08 实测 trip_at_failure_threshold=True、flapping_…"},{"kind":"coding","q":"GitHub 算法补充 · Kahn 拓扑排序与环检测","stem":"实现拓扑排序（Kahn 入度法）：给定 {节点: [依赖节点, ...]}，输出一个线性序（打破平局时取字典序最小者）以及是否存在环。该算法是本章 CI 流水线 needs: 依赖图与 Compose depends_on 启动序的底层工具。题面与实现参考见 external_url，此处不复述第三方题面正文。","opts":[],"ans":"// Kahn：反复取入度为 0 的顶点，删除其出边；取不满则存在环 function topoSort(graph) { const nodes = Object.keys(graph); const indeg = new Map(nodes.map(n => [n, 0])); const succ = new…","why":"Kahn 算法先把入度为 0 的顶点入队（这里按字典序排序以保证输出确定），每次取出一个顶点追加到结果并把它指向的后继入度减一，减到 0 的后继入队。若最终生成的顶点数少于总数，说明剩下的顶点互相成环（不存在入度 0 的顶点），据此可判定环存在。时间复杂度 O(V+E)。ex05 与 ex07 的依赖求解都是它的应用形态。"},{"kind":"coding","q":"LeetCode 210 · 课程表 II（拓扑序，算法素养补充）","stem":"给定课程数与先修关系，返回一种可行的学习顺序；若无法完成全部课程则返回空序列。题面与约束以官方为准，详见 external_url，此处不复述题面正文。","opts":[],"ans":"from collections import deque def find_order(n, prerequisites): succ = [[] for _ in range(n)] indeg = [0] n for a, b in prerequisites: # 先修 b -> 课程 a succ[b].ap…","why":"与 ex07 完全同构：先统计入度，把入度为 0 的节点入队，逐个出队并递减后继入度，最后判断产出数量是否等于 n——少于 n 即存在环、无可行顺序。时间复杂度 O(V+E)，空间 O(V+E)。工程上这就是 CI 的 needs: 依赖图与 Compose 启动序的判定算法。"}],"works":[{"h":"把 apt-get update 与 apt-get install 拆成两条 RUN","d":"缓存命中会让 update 层复用过期索引，install 层要么 404 要么装到旧版本，且 rm -rf /var/lib/apt/lists/ 也失去意义。 写在同一 RUN：RUN apt-get update && apt-get install -y --no-install-recommends curl && rm -…"},{"h":"基础镜像用 node:latest 或不带 tag","d":"构建不可复现，同一 Dockerfile 昨天成功今天失败。 固定到具体版本（node:22.11-bookworm）或直接固定 digest；ex01 对 node:latest 报 base_image_latest:node:latest。"},{"h":"先 COPY . . 再 RUN npm ci（依赖安装顺序倒置）","d":"改一行源码就让「装依赖」这一最贵的层失效。 先 COPY package.json package-lock.json ./ → RUN npm ci → 再 COPY . .。ex02 实测：改 src/app.js 时 deps-first 重建 2 层且 npm_ci_layer_rebuild=False，反模式重建 3 层且…"},{"h":"不写 .dockerignore","d":"COPY . . 会把宿主的 node_modules、.git、.env、日志一起送进 build context 与镜像。 用 .dockerignore 排除（ex04 实测 node_modules/dist/.git//.log/coverage/ 被排除）；注意取反规则 !dist/keep.txt 可以让某个被排除目录下…"},{"h":"用 ADD 代替 COPY","d":"ADD 隐式解压 tar、支持 URL 下载，语义不唯一且难以预测构建结果。 除非确实需要自动解压，一律用 COPY；ex01 报 add_instruction_used。"},{"h":"以为 RUN rm secret.env 能把文件从镜像里删掉","d":"分层只增不减，删除只是在新层写了一条遮蔽记录，文件字节仍留在下方层，docker save/docker history 能捞出来。 让敏感文件一开始就不进任何层：在构建上下文打包前用 .dockerignore 挡掉，或用构建期 secret 挂载（--mount=type=secret）。"},{"h":"最终镜像以 root 运行","d":"容器内 root 叠加内核漏洞即逃逸面，且挂载宿主目录时可写任意宿主文件。 USER node 或 USER 10001（非 0）；ex01 对最终阶段无 USER 或 USER root 报 final_stage_runs_as_root。"},{"h":"多阶段构建却没用 COPY --from=","d":"第二阶段又把宿主上下文整份拷了一遍，builder 白建、镜像没瘦下来。 COPY --from=build /app/dist ./dist；ex01 对多阶段但全文无 --from= 报 multi_stage_without_from。"}],"asks":[{"q":"Docker 镜像为什么分层？为什么「改了后面的指令前面的层还能命中缓存」？","a":"分层是什么：镜像是一组只读层加一份元数据，容器是「镜像 + 一个可写层」。会改文件系统的指令（RUN/COPY/ADD）各产生一层；ENV/WORKDIR/USER/CMD 只改元数据不产生层。 为什么分层：① 层按内容寻址（digest），相同内容的层只存一份，同一个 base 被一百个镜像共享也只占一份空间；② 层可被容器联合挂载复用（overlayfs 的 lowerdir 只读、upper…","fu":[".dockerignore 与 COPY 的排除规则谁先生效？","多阶段构建为什么能把体积降下来？"],"tag":"通用/字节"},{"q":"怎么设计一条可信的 CI/CD 流水线？为什么 job 要串成 DAG？","a":"结构：workflow → job → step 三层；job 默认并行，用 needs: 串行。一条典型的四段线是 build → test → 制镜像 → 部署，其中测试必须在制镜像之前、部署必须在镜像之后。 为什么用 DAG 而不是线性脚本：① 无关 job（lint 与 e2e 准备）可以并行，缩短墙钟；② 依赖关系被显式声明，不会出现「测试没过就上线」；③ 结构可被静态校验。 快速失败：…","fu":["关键路径上有哪些手段能真正缩短流水线？","为什么镜像只在主干分支推送？"],"tag":"通用/腾讯"},{"q":"蓝绿发布和金丝雀发布有什么区别？各自怎么回滚？","a":"蓝绿：维护两套完整环境，流量在它们之间做原子切换。回滚等于切回上一套，速度极快、状态干净；代价是资源翻倍，且数据库变更很难「跟着版本一起切」。 金丝雀：只有一个生产环境，新版本按权重逐步接管流量（5% → 25% → 50% → 100%），每级观察指标，异常就停止放量并回退权重。回滚是「停放量」而非「换环境」。 关键实现细节——稳定分桶：金丝雀必须用稳定哈希（如 crc32(user) % 10…","fu":["两套环境同时读同一数据库时怎么保证兼容？","金丝雀的流量按什么维度切（用户/地区/请求头）？"],"tag":"通用/字节"},{"q":"回滚判据怎么设计？为什么不能看到一个错误率尖峰就回滚？","a":"为什么不能看单点：每个窗口观测到的只是比例的样本估计 $\\hat p = x/n$，标准误是 $\\sqrt{\\hat p(1-\\hat p)/n}$——样本越小方差越大，单点尖峰很可能只是噪声。单点就回滚会产生「发布-回滚」抖动，最终团队不敢发版。 本章 ex09 的判据（三个条件同时满足才回滚）：① 最小样本量（min_requests=200），不足则不下结论、继续观察；② 阈值用整数口径比较…","fu":["怎么区分「发布导致的劣化」与「上游抖动」？","自动回滚和人工确认回滚怎么选？"],"tag":"通用/美团"}]}];

export default CHAPTERS;
